func writeEmbeddedBuildModuleFiles(dir string) error {
	if strings.TrimSpace(dir) == "" {
		return errors.New("編譯暫存目錄不存在")
	}
	if err := os.WriteFile(filepath.Join(dir, "go.mod"), []byte(embeddedBuildGoMod+"\n"), 0644); err != nil {
		return fmt.Errorf("寫入內建 go.mod 失敗: %w", err)
	}
	if err := os.WriteFile(filepath.Join(dir, "go.sum"), []byte(embeddedBuildGoSum+"\n"), 0644); err != nil {
		return fmt.Errorf("寫入內建 go.sum 失敗: %w", err)
	}
	return nil
}

