type botSkinConfig struct {
	ArmSize  string `json:"arm_size"`
	Preset   string `json:"preset,omitempty"`
	Source   string `json:"source,omitempty"`
	FileName string `json:"file_name,omitempty"`
}

func botSkinData() login.ClientData {
	pixels := make([]byte, 64*64*4)
	for i := 0; i < len(pixels); i += 4 {
		pixels[i+3] = 255
	}
	return login.ClientData{
		SkinData:        base64.StdEncoding.EncodeToString(pixels),
		SkinImageWidth:  64,
		SkinImageHeight: 64,
	}
}

func botSkinPNGPath(id int) string {
	return filepath.Join(botDataDir, fmt.Sprintf("skin%d.png", id))
}

func botSkinConfigPath(id int) string {
	return filepath.Join(botDataDir, fmt.Sprintf("skin%d.json", id))
}

func normaliseSkinArmSize(arm string) string {
	if strings.EqualFold(strings.TrimSpace(arm), "slim") {
		return "slim"
	}
	return "wide"
}

func skinResourcePatch(arm string) []byte {
	if normaliseSkinArmSize(arm) == "slim" {
		return []byte(`{"geometry":{"default":"geometry.humanoid.customSlim"}}`)
	}
	return []byte(`{"geometry":{"default":"geometry.humanoid.custom"}}`)
}

func solidSkinPNG(preset string) ([]byte, []byte, error) {
	preset = strings.ToLower(strings.TrimSpace(preset))
	fill := color.NRGBA{R: 0, G: 0, B: 0, A: 255}
	if preset == "white" {
		// 灰白色，避免在遊戲內亮到接近發光白。
		fill = color.NRGBA{R: 205, G: 205, B: 205, A: 255}
	} else if preset != "black" {
		return nil, nil, errors.New("未知的 Skin 預設")
	}

	img := image.NewNRGBA(image.Rect(0, 0, 64, 64))
	pixels := make([]byte, 0, 64*64*4)
	for y := 0; y < 64; y++ {
		for x := 0; x < 64; x++ {
			img.SetNRGBA(x, y, fill)
			pixels = append(pixels, fill.R, fill.G, fill.B, fill.A)
		}
	}

	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		return nil, nil, err
	}
	return buf.Bytes(), pixels, nil
}

func decodeSkinPNG(raw []byte) ([]byte, int, int, error) {
	img, err := png.Decode(bytes.NewReader(raw))
	if err != nil {
		return nil, 0, 0, errors.New("Skin 必須是 PNG 圖片")
	}
	bounds := img.Bounds()
	width, height := bounds.Dx(), bounds.Dy()
	// 這個 Bot 使用 gophertunnel 內建的標準 humanoid 幾何，因此只接受
	// Bedrock / Java 現行最常用的 64x64 標準 Skin，避免高解析或自訂幾何進服後錯位。
	if width != 64 || height != 64 {
		return nil, width, height, fmt.Errorf("Skin 尺寸必須是 64x64，目前是 %dx%d", width, height)
	}
	pixels := make([]byte, 0, width*height*4)
	for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
		for x := bounds.Min.X; x < bounds.Max.X; x++ {
			c := color.NRGBAModel.Convert(img.At(x, y)).(color.NRGBA)
			pixels = append(pixels, c.R, c.G, c.B, c.A)
		}
	}
	return pixels, width, height, nil
}

func loadBotSkinConfig(id int) botSkinConfig {
	cfg := botSkinConfig{ArmSize: "wide", Preset: "", Source: ""}
	if data, err := os.ReadFile(botSkinConfigPath(id)); err == nil {
		_ = json.Unmarshal(data, &cfg)
	}
	cfg.ArmSize = normaliseSkinArmSize(cfg.ArmSize)
	cfg.Preset = strings.ToLower(strings.TrimSpace(cfg.Preset))
	cfg.Source = strings.ToLower(strings.TrimSpace(cfg.Source))
	if cfg.Source == "" {
		switch cfg.Preset {
		case "black", "white":
			cfg.Source = cfg.Preset
		default:
			if _, err := os.Stat(botSkinPNGPath(id)); err == nil {
				cfg.Source = "custom"
			}
		}
	}
	return cfg
}

func loadBotSkin(id int) (pixels []byte, width, height int, arm string, ok bool, err error) {
	raw, err := os.ReadFile(botSkinPNGPath(id))
	if os.IsNotExist(err) {
		return nil, 0, 0, "wide", false, nil
	}
	if err != nil {
		return nil, 0, 0, "wide", false, err
	}
	pixels, width, height, err = decodeSkinPNG(raw)
	if err != nil {
		return nil, width, height, "wide", false, err
	}
	cfg := loadBotSkinConfig(id)
	return pixels, width, height, cfg.ArmSize, true, nil
}

func skinIDForPixels(id int, pixels []byte) string {
	sum := sha256.Sum256(pixels)
	return fmt.Sprintf("minecraft-bot-%d-%x", id, sum[:8])
}

var (
	skinClientDataMu    sync.RWMutex
	skinClientDataCache = map[int]login.ClientData{}
)

var botClientIdentityMu sync.Mutex

func botClientIdentitySeed(id int) [32]byte {
	botClientIdentityMu.Lock()
	defer botClientIdentityMu.Unlock()

	path := filepath.Join(botDataDir, fmt.Sprintf("client-identity-%d", id))
	if raw, err := os.ReadFile(path); err == nil && strings.TrimSpace(string(raw)) != "" {
		return sha256.Sum256(bytes.TrimSpace(raw))
	}

	// 每個 App 安裝只建立一次本機隨機種子，之後跨重啟沿用。
	// 它不是 Microsoft/Xbox 憑證，只用來讓 Bedrock client metadata 穩定。
	identity := uuid.NewString()
	_ = os.MkdirAll(botDataDir, 0755)
	_ = os.WriteFile(path, []byte(identity+"\n"), 0600)
	return sha256.Sum256([]byte(identity))
}

func applyStableBotClientIdentity(id int, clientData *login.ClientData) {
	if clientData == nil {
		return
	}
	// Bedrock 原版會讓同一台裝置的幾個 client identifiers 跨重啟保持一致。
	// 之前全部留空，gophertunnel 每次 Dial 都會重新產生，伺服器/驗證端會把
	// 同一隻 Bot 看成不斷換新裝置。這裡只固定「本機裝置資料」，不偽造 Xbox 身分。
	seed := botClientIdentitySeed(id)
	randomID := int64(binary.BigEndian.Uint64(seed[:8]) & uint64(math.MaxInt64))
	if randomID == 0 {
		randomID = int64(id)
	}
	clientData.ClientRandomID = randomID
	clientData.DeviceID = login.DeviceID(fmt.Sprintf("%x", seed[:16]))
	clientData.SelfSignedID = uuid.NewSHA1(uuid.NameSpaceOID, seed[:]).String()
	clientData.PlayFabID = fmt.Sprintf("%x", seed[16:24])
}

func buildBotClientData(id int) login.ClientData {
	clientData := botSkinData()
	applyStableBotClientIdentity(id, &clientData)
	pixels, width, height, arm, ok, err := loadBotSkin(id)
	if err != nil || !ok {
		return clientData
	}
	clientData.SkinData = base64.StdEncoding.EncodeToString(pixels)
	clientData.SkinImageWidth = width
	clientData.SkinImageHeight = height
	clientData.SkinID = skinIDForPixels(id, pixels)
	clientData.SkinResourcePatch = base64.StdEncoding.EncodeToString(skinResourcePatch(arm))
	clientData.ArmSize = arm
	clientData.PersonaSkin = false
	clientData.PremiumSkin = false
	clientData.TrustedSkin = true
	clientData.OverrideSkin = true
	return clientData
}

func refreshBotSkinClientData(id int) login.ClientData {
	clientData := buildBotClientData(id)
	skinClientDataMu.Lock()
	skinClientDataCache[id] = clientData
	skinClientDataMu.Unlock()
	return clientData
}

func preloadBotSkinClientData(count int) {
	if count < 1 {
		count = DefaultBotCount
	}
	if count > DefaultBotCount {
		count = DefaultBotCount
	}
	for id := 1; id <= count; id++ {
		refreshBotSkinClientData(id)
	}
}

func botClientData(id int) login.ClientData {
	skinClientDataMu.RLock()
	clientData, ok := skinClientDataCache[id]
	skinClientDataMu.RUnlock()
	if ok {
		return clientData
	}
	return refreshBotSkinClientData(id)
}

func decodeBase64OrEmpty(value string) []byte {
	if value == "" {
		return nil
	}
	data, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		return nil
	}
	return data
}

func protocolSkinForConnection(id int, conn *minecraft.Conn, pixels []byte, width, height int, arm string) protocol.Skin {
	cd := conn.ClientData()
	armValue := uint8(protocol.ArmSizeWide)
	if normaliseSkinArmSize(arm) == "slim" {
		armValue = uint8(protocol.ArmSizeSlim)
	}
	return protocol.Skin{
		SkinID:                    skinIDForPixels(id, pixels),
		PlayFabID:                 cd.PlayFabID,
		SkinResourcePatch:         skinResourcePatch(arm),
		SkinImageWidth:            uint32(width),
		SkinImageHeight:           uint32(height),
		SkinData:                  pixels,
		CapeImageWidth:            uint32(cd.CapeImageWidth),
		CapeImageHeight:           uint32(cd.CapeImageHeight),
		CapeData:                  decodeBase64OrEmpty(cd.CapeData),
		SkinGeometry:              decodeBase64OrEmpty(cd.SkinGeometry),
		GeometryDataEngineVersion: decodeBase64OrEmpty(cd.SkinGeometryVersion),
		PremiumSkin:               false,
		PersonaSkin:               false,
		PersonaCapeOnClassicSkin:  false,
		PrimaryUser:               true,
		CapeID:                    "",
		ArmSize:                   armValue,
		Trusted:                   true,
		OverrideAppearance:        true,
	}
}

func (s timedTokenSource) Token() (*oauth2.Token, error) {
	type tokenResult struct {
		token *oauth2.Token
		err   error
	}
	result := make(chan tokenResult, 1)
	go func() {
		token, err := s.source.Token()
		result <- tokenResult{token: token, err: err}
	}()
	select {
	case value := <-result:
		return value.token, value.err
	case <-time.After(s.timeout):
		return nil, fmt.Errorf("Microsoft Token 更新超過 %s", s.timeout)
	}
}

const botDataDir = "bot-data"

var (
	botDialSlots = make(chan struct{}, DefaultBotCount)
	botAuthSlots = make(chan struct{}, DefaultBotCount)

	// Minecraft auth-chain 自適應限流：
	// 正常時只做很短錯峰，讓 4 隻盡快登入；
	// 一旦真的收到 429，才依 Retry-After / 退避時間暫時放慢。
	minecraftAuthChainMu          sync.Mutex
	minecraftAuthChainNextAllowed time.Time
	minecraftAuthChainGap         = 450 * time.Millisecond
	minecraftAuthChain429Streak   int
	appSettingsMu                 sync.RWMutex
	configuredBotCount            = DefaultBotCount
	scheduleFileMu                sync.Mutex

	// App 啟動時，所有已啟用 Bot 先各自完成本機初始化，
	// 到齊後放行；Minecraft auth-chain 會自動錯峰，避免 4 隻同時撞出 429。
	initialLoginGateMu       sync.Mutex
	initialLoginGate         chan struct{}
	initialLoginGateExpected int
	initialLoginGateReady    int
	initialLoginGateReleased bool
)

type appSettingsConfig struct {
	BotCount int `json:"bot_count"`
}

func loadAppSettings() {
	count := 0
	if data, err := os.ReadFile(filepath.Join(botDataDir, "app-settings.json")); err == nil {
		var cfg appSettingsConfig
		if json.Unmarshal(data, &cfg) == nil {
			count = cfg.BotCount
		}
	}
	if count < 1 || count > DefaultBotCount {
		for i := 1; i <= DefaultBotCount; i++ {
			if _, err := os.Stat(fmt.Sprintf("token%d.json", i)); err == nil {
				count = i
			}
		}
		if count < 1 {
			count = 1
		}
	}
	appSettingsMu.Lock()
	configuredBotCount = count
	appSettingsMu.Unlock()
}

func currentConfiguredBotCount() int {
	appSettingsMu.RLock()
	defer appSettingsMu.RUnlock()
	return configuredBotCount
}

func prepareInitialLoginGate(botCount int) {
	if botCount < 1 {
		botCount = 1
	}
	if botCount > DefaultBotCount {
		botCount = DefaultBotCount
	}

	configured := currentConfiguredBotCount()
	if configured > botCount {
		configured = botCount
	}

	expected := 0
	for id := 1; id <= configured; id++ {
		if _, err := os.Stat(fmt.Sprintf("token%d.json", id)); err == nil {
			expected++
		}
	}

	initialLoginGateMu.Lock()
	defer initialLoginGateMu.Unlock()

	initialLoginGateExpected = expected
	initialLoginGateReady = 0
	initialLoginGateReleased = expected <= 1

	if expected > 1 {
		initialLoginGate = make(chan struct{})
	} else {
		initialLoginGate = nil
	}
}

func waitInitialLoginGate() {
	// 最快模式：不再額外等其他 Bot。
	// 429 防護由 minecraftAuthChainTransport 單獨處理。
	return
}

func saveAppSettings(count int) error {
	if count < 1 || count > DefaultBotCount {
		return errors.New("帳號數量必須是 1 到 4")
	}
	appSettingsMu.Lock()
	configuredBotCount = count
	appSettingsMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return err
	}
	data, _ := json.MarshalIndent(appSettingsConfig{BotCount: count}, "", "  ")
	settingsPath := filepath.Join(botDataDir, "app-settings.json")
	_, _ = backupFileToDesktop(settingsPath)
	return os.WriteFile(settingsPath, data, 0644)
}

func desktopBackupDir() string {
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return filepath.Join(".", "廢土Bot備份")
	}
	return filepath.Join(home, "Desktop", "廢土Bot備份")
}

func backupFileToDesktop(path string) (string, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	dir := desktopBackupDir()
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}
	// 每個檔案只保留緊鄰的上一版；再次備份時直接取代，避免備份資料夾無限累積。
	name := "上一版-" + filepath.Base(path)
	target := filepath.Join(dir, name)
	tmp := target + ".tmp"
	if err := os.WriteFile(tmp, data, 0600); err != nil {
		return "", err
	}
	_ = os.Remove(target)
	if err := os.Rename(tmp, target); err != nil {
		_ = os.Remove(tmp)
		return "", err
	}
	return target, nil
}

func backupExecutableToDesktopFast(path string) (string, error) {
	dir := desktopBackupDir()
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}

	target := filepath.Join(dir, "上一版-"+filepath.Base(path))
	tmp := target + fmt.Sprintf(".tmp-%d", os.Getpid())
	_ = os.Remove(tmp)

	// EXE 更新時正式檔會先 remove 再建立，因此硬連結會安全地保留「上一版」
	// 的舊檔內容，不會像 main.go 的原地覆寫那樣跟著一起被改掉。
	// Desktop 與 App 在同一個 NTFS volume 時，這一步幾乎是瞬間完成。
	if err := os.Link(path, tmp); err == nil {
		_ = os.Remove(target)
		if err := os.Rename(tmp, target); err == nil {
			return target, nil
		}
		_ = os.Remove(tmp)
	}

	// 不同磁碟 / 不支援 hard-link 時才走串流複製，避免 os.ReadFile
	// 一次把整個 EXE 讀進記憶體。
	src, err := os.Open(path)
	if err != nil {
		return "", err
	}
	defer src.Close()

	dst, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
	if err != nil {
		return "", err
	}

	buf := make([]byte, 1<<20)
	_, copyErr := io.CopyBuffer(dst, src, buf)
	closeErr := dst.Close()
	if copyErr != nil {
		_ = os.Remove(tmp)
		return "", copyErr
	}
	if closeErr != nil {
		_ = os.Remove(tmp)
		return "", closeErr
	}

	_ = os.Remove(target)
	if err := os.Rename(tmp, target); err != nil {
		_ = os.Remove(tmp)
		return "", err
	}
	return target, nil
}

func cleanupObsoleteFiles() {
	// 舊備份永久移除，只保留固定命名的上一版；登入資料與目前設定不在清理範圍。
	dir := desktopBackupDir()
	if entries, err := os.ReadDir(dir); err == nil {
		for _, entry := range entries {
			if entry.IsDir() || strings.HasPrefix(entry.Name(), "上一版-") {
				continue
			}
			_ = os.Remove(filepath.Join(dir, entry.Name()))
		}
	}

	// Windows App／EXE 圖示會在自我更新完成前直接寫入正式 EXE；這些只是舊版中繼檔。
	_ = os.Remove(filepath.Join(botDataDir, "lantern-cutout.png"))
	_ = os.Remove(filepath.Join(botDataDir, "app-icon.ico"))
	_ = os.Remove(filepath.Join(botDataDir, "app-profile"))
	// 舊版曾允許外部 app-icon.png 覆蓋 App 圖示；現在綠寶石圖示固定內嵌，
	// 永久刪除此外部覆蓋檔，避免備份還原或舊版本再次把燈籠/方塊圖示帶回來。
	_ = os.Remove("app-icon.png")
	_ = os.Remove(filepath.Join(botDataDir, "app-icon.png"))

	// 清除舊版自動更新曾經留在 bot-data 的 EXE。
	obsoleteNames := []string{
		"Minecraft Bot.new",
		"Minecraft Bot.new.exe",
		"Minecraft Bot.new.exe~",
		"Minecraft Bot.update.exe",
		"Minecraft Bot.update.exe~",
		"Minecraft Bot.pending.exe",
		"Minecraft Bot.pending.exe~",
		"Minecraft Bot.tmp.exe",
		"Minecraft Bot.tmp.exe~",
		"Minecraft Bot.restart-helper.exe",
	}
	for _, name := range obsoleteNames {
		_ = os.Remove(filepath.Join(botDataDir, name))
	}

	// 正式啟動器所在資料夾也清一次；正在執行中的 EXE 在 Windows 會刪除失敗，屬正常現象，
	// 真正的自我替換會由外部 updater 在主程式退出後完成。
	if exe, _ := os.Executable(); exe != "" {
		exe, _ = filepath.Abs(exe)
		exeDir := filepath.Dir(exe)
		for _, name := range obsoleteNames {
			candidate := filepath.Join(exeDir, name)
			if !sameFilePath(candidate, exe) {
				_ = os.Remove(candidate)
			}
		}
	}
}

func sameFilePath(a, b string) bool {
	aa, _ := filepath.Abs(a)
	bb, _ := filepath.Abs(b)
	return strings.EqualFold(filepath.Clean(aa), filepath.Clean(bb))
}

type savedCron struct {
	Interval int    `json:"interval"`
	MaxRuns  int    `json:"max_runs"`
	Command  string `json:"command"`
}

type savedBotSchedules struct {
	Cron1 savedCron `json:"cron1"`
	Cron2 savedCron `json:"cron2"`
}

func scheduleConfigPath() string {
	return filepath.Join(botDataDir, "schedules.json")
}

func loadBotScheduleConfig(id int) (savedBotSchedules, bool) {
	scheduleFileMu.Lock()
	defer scheduleFileMu.Unlock()
	data, err := os.ReadFile(scheduleConfigPath())
	if err != nil {
		return savedBotSchedules{}, false
	}
	all := map[string]savedBotSchedules{}
	if json.Unmarshal(data, &all) != nil {
		return savedBotSchedules{}, false
	}
	cfg, ok := all[strconv.Itoa(id)]
	return cfg, ok
}

func saveAllScheduleConfigs() error {
	sessionMu.RLock()
	bots := make([]*BotSession, 0, len(sessions))
	for _, bot := range sessions {
		bots = append(bots, bot)
	}
	sessionMu.RUnlock()
	all := make(map[string]savedBotSchedules, len(bots))
	for _, bot := range bots {
		bot.mu.Lock()
		all[strconv.Itoa(bot.ID)] = savedBotSchedules{
			Cron1: savedCron{Interval: bot.CronInterval, MaxRuns: bot.CronMaxRuns, Command: bot.CronCommand},
			Cron2: savedCron{Interval: bot.Cron2Interval, MaxRuns: bot.Cron2MaxRuns, Command: bot.Cron2Command},
		}
		bot.mu.Unlock()
	}
	data, err := json.MarshalIndent(all, "", "  ")
	if err != nil {
		return err
	}
	scheduleFileMu.Lock()
	defer scheduleFileMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return err
	}
	path := scheduleConfigPath()
	_, _ = backupFileToDesktop(path)
	return os.WriteFile(path, data, 0644)
}

func botDialTarget(address string) string {
	// V25: the known-good reference dials the hostname exactly as configured.
	// Do not pin Bedrock hosts to an old IP: DNS/edge routing may change, and
	// the hard-coded address was one of the remaining differences from the working login.
	return strings.TrimSpace(address)
}

