type suiteTaskManager struct {
	mu        sync.Mutex
	queues    map[int][]*suiteTask
	history   map[int][]*suiteTask
	paused    map[int]bool
	workers   map[int]bool
	resources map[int]map[string]suiteResourceLease
	seq       uint64
}

var bedrockSuiteTasks = &suiteTaskManager{
	queues:    map[int][]*suiteTask{},
	history:   map[int][]*suiteTask{},
	paused:    map[int]bool{},
	workers:   map[int]bool{},
	resources: map[int]map[string]suiteResourceLease{},
}

type suiteTaskQueueStore struct {
	Version int                 `json:"version"`
	SavedAt time.Time           `json:"saved_at"`
	Queues  map[int][]suiteTask `json:"queues"`
	Paused  map[int]bool        `json:"paused"`
}

var (
	suiteTaskStoreLoadOnce sync.Once
	suiteTaskStoreSaveOnce sync.Once
	suiteTaskStoreSaveCh   = make(chan struct{}, 1)
)

func suiteTaskStorePath() string {
	return filepath.Join(botDataDir, "minecraft-bot-task-queue.json")
}

func suiteLoadTaskStore() {
	suiteTaskStoreLoadOnce.Do(func() {
		data, err := os.ReadFile(suiteTaskStorePath())
		if err != nil || len(data) == 0 {
			return
		}
		var saved suiteTaskQueueStore
		if json.Unmarshal(data, &saved) != nil {
			return
		}
		now := time.Now()
		workerIDs := make([]int, 0, len(saved.Queues))
		bedrockSuiteTasks.mu.Lock()
		for botID, list := range saved.Queues {
			for i := range list {
				t := suiteCloneTask(&list[i])
				if suiteTaskTerminalStatus(t.Status) {
					continue
				}
				t.cancel = nil
				if t.Attempt < 1 {
					t.Attempt = 1
				}
				if t.PayloadHash == "" {
					t.PayloadHash = suitePayloadDigest(t.Payload)
				}
				if t.Status == suiteTaskRunning {
					t.Status = suiteTaskBlocked
					t.Stage = "App 上次中斷，等待從檢查點續作"
					t.Outcome = suiteOutcomeRecoveryRequired
					t.NextAction = suiteNextResume
					t.RetryAt = now.Add(suiteAutoRecoveryBaseDelay)
					t.StartedAt = time.Time{}
					t.CompletedAt = time.Time{}
				}
				if suiteTaskAutoRecoveryEligible(&t) {
					// SessionGeneration is process-local. A persisted value from the old
					// process must not accidentally equal the first generation in this one.
					t.SessionGen = 0
					t.Status = suiteTaskBlocked
					if t.RetryAt.IsZero() || t.RetryAt.Before(now) {
						t.RetryAt = now
					} else if maxRetryAt := now.Add(suiteAutoRecoveryMaxDelay); t.RetryAt.After(maxRetryAt) {
						t.RetryAt = maxRetryAt
					}
				}
				cp := t
				bedrockSuiteTasks.queues[botID] = append(bedrockSuiteTasks.queues[botID], &cp)
			}
			if len(bedrockSuiteTasks.queues[botID]) > 0 && !bedrockSuiteTasks.workers[botID] {
				bedrockSuiteTasks.workers[botID] = true
				workerIDs = append(workerIDs, botID)
			}
		}
		for botID, paused := range saved.Paused {
			bedrockSuiteTasks.paused[botID] = paused
		}
		bedrockSuiteTasks.mu.Unlock()
		for _, botID := range workerIDs {
			go bedrockSuiteTasks.worker(botID)
		}
	})
}

func suiteWriteTaskStore() {
	saved := suiteTaskQueueStore{
		Version: 2,
		SavedAt: time.Now(),
		Queues:  map[int][]suiteTask{},
		Paused:  map[int]bool{},
	}
	bedrockSuiteTasks.mu.Lock()
	for botID, list := range bedrockSuiteTasks.queues {
		for _, task := range list {
			if task == nil || suiteTaskTerminalStatus(task.Status) {
				continue
			}
			saved.Queues[botID] = append(saved.Queues[botID], suiteCloneTask(task))
		}
	}
	for botID, paused := range bedrockSuiteTasks.paused {
		saved.Paused[botID] = paused
	}
	bedrockSuiteTasks.mu.Unlock()

	data, err := json.MarshalIndent(saved, "", "  ")
	if err != nil || os.MkdirAll(botDataDir, 0o755) != nil {
		return
	}
	path := suiteTaskStorePath()
	tmp := path + ".tmp"
	if os.WriteFile(tmp, data, 0o600) != nil {
		return
	}
	_ = os.Remove(path)
	if os.Rename(tmp, path) != nil {
		_ = os.Remove(tmp)
	}
}

func suiteScheduleTaskStoreSave() {
	suiteTaskStoreSaveOnce.Do(func() {
		go func() {
			for range suiteTaskStoreSaveCh {
				time.Sleep(500 * time.Millisecond)
				for {
					select {
					case <-suiteTaskStoreSaveCh:
						continue
					default:
					}
					break
				}
				suiteWriteTaskStore()
			}
		}()
	})
	select {
	case suiteTaskStoreSaveCh <- struct{}{}:
	default:
	}
}

func suiteCloneTask(t *suiteTask) suiteTask {
	if t == nil {
		return suiteTask{}
	}
	cp := *t
	cp.Resources = append([]string(nil), t.Resources...)
	if t.Payload != nil {
		cp.Payload = suiteClonePayloadMap(t.Payload)
	}
	if t.Checkpoint != nil {
		cp.Checkpoint = suiteClonePayloadMap(t.Checkpoint)
	}
	cp.cancel = nil
	return cp
}

func suitePayloadDigest(payload map[string]interface{}) string {
	if payload == nil {
		return fmt.Sprintf("%x", sha256.Sum256([]byte("null")))
	}
	data, err := json.Marshal(payload)
	if err != nil {
		return ""
	}
	return fmt.Sprintf("%x", sha256.Sum256(data))
}

func suiteTaskOutcome(err error) (outcome, nextAction string) {
	if err == nil {
		return suiteOutcomeSucceeded, suiteNextNone
	}
	if errors.Is(err, context.Canceled) {
		return suiteOutcomeCancelled, suiteNextNone
	}

	msg := strings.ToLower(strings.TrimSpace(err.Error()))
	containsAny := func(values ...string) bool {
		for _, value := range values {
			if strings.Contains(msg, strings.ToLower(value)) {
				return true
			}
		}
		return false
	}

	// Authentication is still handled by this App's existing Bedrock/Xbox
	// implementation. This classifier only tells the queue which existing action
	// should be used; it never starts a second login flow.
	if containsAny("credential", "token expired", "authentication", "unauthorized", "forbidden", "登入失效", "憑證", "權杖") {
		return suiteOutcomeConnectionLost, suiteNextRefreshCredentials
	}
	if containsAny("license", "quota", "授權暫停", "授權已暫停", "額度") {
		return suiteOutcomeLicensePaused, suiteNextWaitLicense
	}
	if containsAny(
		"connection reset", "connection closed", "use of closed network connection",
		"broken pipe", "unexpected eof", "eof", "timeout awaiting response",
		"connection_lost", "bot 尚未連線", "bot 已離線", "途中 bot 已離線", "連線已中斷", "等待 bot 登入逾時",
	) {
		return suiteOutcomeConnectionLost, suiteNextReconnect
	}
	if containsAny(
		"recovery_required", "死亡", "重生", "respawn", "teleport", "傳送", "維度切換",
		"世界尚未", "世界維度尚未", "世界同步逾時", "導航底層", "區塊資料不足",
	) {
		return suiteOutcomeRecoveryRequired, suiteNextResume
	}
	if containsAny("控制權", "控制旗標", "資源忙碌", "等待資源", "正在執行", "連線世代", "control owner", "generation changed") {
		return suiteOutcomeControlShift, suiteNextResume
	}
	if containsAny(
		"transient_protocol", "stack request", "item stack", "inventory transaction", "封包", "server tick",
		"尚未收到背包", "尚未取得 bot 位置", "尚未建立 playerauthinput", "最近沒有收到伺服器封包", "伺服器座標", "setback",
	) {
		return suiteOutcomeTransient, suiteNextRetry
	}
	if containsAny(
		"不可空白", "不存在", "不正確", "尚未支援", "格式", "無效", "超過最大走路距離",
		"找不到材料", "缺少材料", "藍圖沒有方塊", "目標距離", "座標超出",
	) {
		return suiteOutcomePermanentInput, suiteNextResolve
	}
	return suiteOutcomeBlockedOperator, suiteNextResolve
}

func suiteTaskAutoRecoveryEligible(t *suiteTask) bool {
	if t == nil {
		return false
	}
	switch t.NextAction {
	case suiteNextReconnect, suiteNextRefreshCredentials:
		return t.Outcome == suiteOutcomeConnectionLost
	case suiteNextResume:
		return t.Outcome == suiteOutcomeRecoveryRequired || t.Outcome == suiteOutcomeControlShift
	case suiteNextRetry:
		return t.Outcome == suiteOutcomeTransient
	default:
		return false
	}
}

func suiteAutomaticRecoveryDelay(retry int) time.Duration {
	if retry < 1 {
		retry = 1
	}
	delay := suiteAutoRecoveryBaseDelay
	for i := 1; i < retry && delay < suiteAutoRecoveryMaxDelay; i++ {
		delay *= 2
		if delay > suiteAutoRecoveryMaxDelay {
			delay = suiteAutoRecoveryMaxDelay
		}
	}
	return delay
}

// suiteScheduleAutomaticRecovery keeps a recoverable task in the live queue.
// Checkpoint and SessionGen deliberately stay on the same task: the runner uses
// the checkpoint to resume confirmed work and the gate below requires a newer
// connection generation for reconnect/credential outcomes.
func suiteScheduleAutomaticRecovery(t *suiteTask, now time.Time) bool {
	if !suiteTaskAutoRecoveryEligible(t) || t.AutoRetries >= suiteMaxAutoRecoveryRetries {
		return false
	}
	if t.Attempt < 1 {
		t.Attempt = 1
	}
	t.AutoRetries++
	t.Attempt++
	delay := suiteAutomaticRecoveryDelay(t.AutoRetries)
	t.RetryAt = now.Add(delay)
	t.Status = suiteTaskBlocked
	t.StartedAt = time.Time{}
	t.CompletedAt = time.Time{}
	t.UpdatedAt = now

	switch t.NextAction {
	case suiteNextReconnect:
		t.Stage = "等待 BOT 重連後自動續作"
	case suiteNextRefreshCredentials:
		t.Stage = "等待憑證更新並由既有登入流程重連"
	case suiteNextResume:
		t.Stage = "等待角色／世界復原後自動續作"
	case suiteNextRetry:
		t.Stage = "暫時性錯誤，等待自動重試"
	}
	t.Message = fmt.Sprintf("自動復原 %d/%d；最早 %s 後重試", t.AutoRetries, suiteMaxAutoRecoveryRetries, delay.Round(time.Second))
	return true
}

func suiteResetTaskForManualRelease(t *suiteTask, now time.Time) {
	if t == nil {
		return
	}
	// "解除阻擋" is an explicit operator override: run the task immediately
	// through the normal Bot-ready path and grant a fresh bounded auto-recovery
	// budget. Leaving NextAction/RetryAt behind would make the worker keep applying
	// the old recovery gate even though the UI reported that it was released.
	t.Status = suiteTaskQueued
	t.Stage = "等待執行"
	t.Message = ""
	t.Error = ""
	t.Outcome = ""
	t.NextAction = suiteNextNone
	t.AutoRetries = 0
	t.RetryAt = time.Time{}
	t.StartedAt = time.Time{}
	t.CompletedAt = time.Time{}
	t.UpdatedAt = now
}

// suiteAutomaticRecoveryGate is pure so the timing/session rules can be tested
// without starting the Bot. reconnect/refresh_credentials must observe a new
// connected SessionGeneration; resume/retry may continue in the current healthy
// session after their bounded backoff.
func suiteAutomaticRecoveryGate(t *suiteTask, now time.Time, botReady bool, sessionGeneration uint64) (bool, time.Duration) {
	if !suiteTaskAutoRecoveryEligible(t) {
		return true, 0
	}
	if remaining := t.RetryAt.Sub(now); remaining > 0 {
		if remaining > suiteAutoRecoveryPollDelay {
			remaining = suiteAutoRecoveryPollDelay
		}
		if remaining < 50*time.Millisecond {
			remaining = 50 * time.Millisecond
		}
		return false, remaining
	}
	if !botReady {
		return false, suiteAutoRecoveryPollDelay
	}
	if t.NextAction == suiteNextReconnect || t.NextAction == suiteNextRefreshCredentials {
		if sessionGeneration == 0 || (t.SessionGen != 0 && sessionGeneration == t.SessionGen) {
			return false, suiteAutoRecoveryPollDelay
		}
	}
	return true, 0
}

func (m *suiteTaskManager) nextID(botID int) string {
	// A process-local counter reused IDs after every restart and could overwrite
	// an older history row. UUID lineage matches the reference task store and is
	// stable across App restarts.
	return fmt.Sprintf("B%d-%s", botID, uuid.NewString())
}

func suiteNormaliseResources(resources []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(resources))
	for _, r := range resources {
		r = strings.ToLower(strings.TrimSpace(r))
		if r == "" || seen[r] {
			continue
		}
		seen[r] = true
		out = append(out, r)
	}
	sort.Strings(out)
	return out
}

func suiteResourcesForKind(kind string) []string {
	switch strings.ToLower(strings.TrimSpace(kind)) {
	case "collect":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite}
	case "build", "mapart", "build_library", "draw_map":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite, suiteResourceContainer}
	case "explosion", "blast":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite, suiteResourceContainer, suiteResourceFormsChat}
	case "eat", "survival":
		return []string{suiteResourceInteraction, suiteResourceInventoryWrite}
	case "combat":
		return []string{suiteResourceLook, suiteResourceInteraction, suiteResourceCombat, suiteResourceInventoryWrite}
	case "craft", "idle_craft":
		return []string{suiteResourceInventoryWrite, suiteResourceCrafting}
	case "walk":
		return []string{suiteResourceMovement, suiteResourceLook}
	case "container":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite, suiteResourceContainer}
	case "command", "command_sequence":
		return []string{suiteResourceFormsChat}
	case "rename_map":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite, suiteResourceContainer, suiteResourceFormsChat}
	case "copy_map":
		return []string{suiteResourceMovement, suiteResourceLook, suiteResourceInteraction, suiteResourceInventoryWrite, suiteResourceContainer, suiteResourceCrafting, suiteResourceFormsChat}
	default:
		return nil
	}
}

func suiteTaskTerminalStatus(status string) bool {
	switch strings.ToLower(strings.TrimSpace(status)) {
	case suiteTaskCompleted, suiteTaskError, suiteTaskCancelled:
		return true
	default:
		return false
	}
}

// archiveTaskLocked moves a terminal task out of the live queue and into bounded history.
// Keeping completed/error/cancelled tasks inside queues was the reason Task Queue kept growing
// after every run and also made the dashboard count old work as live work.
func (m *suiteTaskManager) archiveTaskLocked(botID int, t *suiteTask) {
	if t == nil {
		return
	}
	q := m.queues[botID]
	for i := 0; i < len(q); i++ {
		if q[i] == t || (q[i] != nil && q[i].ID == t.ID) {
			m.queues[botID] = append(q[:i], q[i+1:]...)
			break
		}
	}

	h := m.history[botID]
	// De-duplicate by task ID so a cancel/snapshot race cannot create two history rows.
	for i := len(h) - 1; i >= 0; i-- {
		if h[i] != nil && h[i].ID == t.ID {
			h = append(h[:i], h[i+1:]...)
		}
	}
	h = append(h, t)
	if len(h) > 100 {
		h = h[len(h)-100:]
	}
	m.history[botID] = h
}

func suiteTaskStableDedupeKindV117(kind string) bool {
	switch strings.ToLower(strings.TrimSpace(kind)) {
	case "build", "build_library", "draw_map", "mapart", "explosion", "blast", "place_plane", "clear_bedrock", "clear_obsidian", "rename_map", "copy_map":
		return true
	default:
		return false
	}
}

func (m *suiteTaskManager) enqueue(botID int, kind, name string, priority int, payload map[string]interface{}) suiteTask {
	return m.enqueueWithLineage(botID, kind, name, priority, payload, nil, "", 1)
}

func (m *suiteTaskManager) enqueueWithLineage(botID int, kind, name string, priority int, payload, checkpoint map[string]interface{}, parentID string, attempt int) suiteTask {
	// V117 SOURCE-PARITY: queued work owns an immutable payload snapshot. In
	// particular, a scanned material-station revision is frozen now instead of
	// being silently replaced by a later rescan while this task is waiting.
	payload = suiteClonePayloadMap(payload)
	suiteAttachStorageSnapshotToPayloadV117(botID, payload)

	m.mu.Lock()
	defer m.mu.Unlock()
	if name = strings.TrimSpace(name); name == "" {
		name = kind
	}
	if attempt < 1 {
		attempt = 1
	}
	kind = strings.ToLower(strings.TrimSpace(kind))
	payloadHash := suitePayloadDigest(payload)
	// The reference tool de-duplicates capability/build work by payload identity.
	// Keep commands/interactive actions repeatable, but never enqueue a second
	// identical long-running job while the first one is still live.
	if suiteTaskStableDedupeKindV117(kind) {
		for _, existing := range m.queues[botID] {
			if existing == nil || suiteTaskTerminalStatus(existing.Status) {
				continue
			}
			if existing.Kind == kind && existing.PayloadHash != "" && existing.PayloadHash == payloadHash {
				return suiteCloneTask(existing)
			}
		}
	}
	t := &suiteTask{
		ID:          m.nextID(botID),
		ParentID:    strings.TrimSpace(parentID),
		BotID:       botID,
		Kind:        kind,
		Name:        name,
		Status:      suiteTaskQueued,
		Priority:    priority,
		Payload:     payload,
		Checkpoint:  suiteClonePayloadMap(checkpoint),
		Resources:   suiteNormaliseResources(suiteResourcesForKind(kind)),
		CreatedAt:   time.Now(),
		UpdatedAt:   time.Now(),
		Stage:       "立即啟動",
		NextAction:  suiteNextNone,
		PayloadHash: payloadHash,
		Attempt:     attempt,
	}
	m.queues[botID] = append(m.queues[botID], t)
	sort.SliceStable(m.queues[botID], func(i, j int) bool {
		return m.queues[botID][i].Priority > m.queues[botID][j].Priority
	})
	if !m.workers[botID] {
		m.workers[botID] = true
		go m.worker(botID)
	}
	suiteScheduleTaskStoreSave()
	return suiteCloneTask(t)
}

func (m *suiteTaskManager) snapshot(botID int) map[string]interface{} {
	m.mu.Lock()
	defer m.mu.Unlock()
	// Older/in-flight state can still contain a terminal queued task (for example a queued
	// task cancelled before the worker started). Archive those before exposing the snapshot.
	for _, t := range append([]*suiteTask(nil), m.queues[botID]...) {
		if t != nil && t.cancel == nil && suiteTaskTerminalStatus(t.Status) {
			m.archiveTaskLocked(botID, t)
		}
	}
	queue := make([]suiteTask, 0, len(m.queues[botID]))
	for _, t := range m.queues[botID] {
		if t == nil || suiteTaskTerminalStatus(t.Status) {
			continue
		}
		queue = append(queue, suiteCloneTask(t))
	}
	h := m.history[botID]
	if len(h) > 40 {
		h = h[len(h)-40:]
	}
	history := make([]suiteTask, 0, len(h))
	for _, t := range h {
		history = append(history, suiteCloneTask(t))
	}
	leases := make([]suiteResourceLease, 0, len(m.resources[botID]))
	for _, l := range m.resources[botID] {
		leases = append(leases, l)
	}
	sort.Slice(leases, func(i, j int) bool { return leases[i].Resource < leases[j].Resource })
	return map[string]interface{}{"ok": true, "paused": m.paused[botID], "queue": queue, "history": history, "resources": leases}
}

func (m *suiteTaskManager) setPaused(botID int, paused bool) {
	m.mu.Lock()
	m.paused[botID] = paused
	if paused {
		for _, task := range m.queues[botID] {
			if task != nil && task.cancel != nil && task.Status == suiteTaskRunning {
				task.Status = suiteTaskPaused
				task.Stage = "已暫停，保留檢查點"
				task.UpdatedAt = time.Now()
				task.cancel()
				break
			}
		}
	} else {
		for _, task := range m.queues[botID] {
			if task != nil && task.Status == suiteTaskPaused {
				task.Status = suiteTaskQueued
				task.Stage = "從檢查點等待續作"
				task.Message = ""
				task.Error = ""
				task.UpdatedAt = time.Now()
			}
		}
		if len(m.queues[botID]) > 0 && !m.workers[botID] {
			m.workers[botID] = true
			go m.worker(botID)
		}
	}
	m.mu.Unlock()
	suiteScheduleTaskStoreSave()
}

func (m *suiteTaskManager) findLocked(botID int, id string) *suiteTask {
	for _, t := range m.queues[botID] {
		if t.ID == id {
			return t
		}
	}
	return nil
}

func (m *suiteTaskManager) cancelTask(botID int, id string) bool {
	m.mu.Lock()
	t := m.findLocked(botID, id)
	if t == nil {
		m.mu.Unlock()
		return false
	}
	running := t.cancel != nil
	if running {
		t.cancel()
	}
	t.Status = suiteTaskCancelled
	t.Stage = "已取消"
	t.Outcome = suiteOutcomeCancelled
	t.NextAction = suiteNextNone
	t.UpdatedAt = time.Now()
	t.CompletedAt = time.Now()
	persisted := suiteCloneTask(t)
	if !running {
		m.archiveTaskLocked(botID, t)
	}
	m.mu.Unlock()
	suiteScheduleTaskStoreSave()
	if !running {
		suitePersistTaskHistory(persisted)
	}
	return true
}

func (m *suiteTaskManager) removeTask(botID int, id string) bool {
	m.mu.Lock()
	q := m.queues[botID]
	for i, t := range q {
		if t != nil && t.ID == id {
			running := t.cancel != nil
			if running {
				t.cancel()
			}
			t.Status = suiteTaskCancelled
			t.Stage = "已移除"
			t.Outcome = suiteOutcomeCancelled
			t.NextAction = suiteNextNone
			t.UpdatedAt = time.Now()
			t.CompletedAt = time.Now()
			persisted := suiteCloneTask(t)
			m.queues[botID] = append(q[:i], q[i+1:]...)
			m.mu.Unlock()
			suiteScheduleTaskStoreSave()
			if !running {
				suitePersistTaskHistory(persisted)
			}
			return true
		}
	}
	h := m.history[botID]
	for i, t := range h {
		if t != nil && t.ID == id {
			m.history[botID] = append(h[:i], h[i+1:]...)
			m.mu.Unlock()
			suiteScheduleTaskStoreSave()
			return true
		}
	}
	m.mu.Unlock()
	return false
}

func (m *suiteTaskManager) clearFinished(botID int) {
	m.mu.Lock()
	defer m.mu.Unlock()
	q := m.queues[botID][:0]
	for _, t := range m.queues[botID] {
		if t != nil && !suiteTaskTerminalStatus(t.Status) {
			q = append(q, t)
		}
	}
	m.queues[botID] = q
	h := m.history[botID][:0]
	for _, t := range m.history[botID] {
		if t != nil && !suiteTaskTerminalStatus(t.Status) {
			h = append(h, t)
		}
	}
	m.history[botID] = h
	suiteScheduleTaskStoreSave()
}

func (m *suiteTaskManager) cloneTaskByID(botID int, id string) (suiteTask, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, t := range m.queues[botID] {
		if t.ID == id {
			return suiteCloneTask(t), true
		}
	}
	for i := len(m.history[botID]) - 1; i >= 0; i-- {
		t := m.history[botID][i]
		if t.ID == id {
			return suiteCloneTask(t), true
		}
	}
	return suiteTask{}, false
}

func (m *suiteTaskManager) retryTask(botID int, id string) (suiteTask, bool) {
	old, ok := m.cloneTaskByID(botID, id)
	if !ok {
		return suiteTask{}, false
	}
	name := old.Name
	if strings.TrimSpace(name) == "" {
		name = old.Kind
	}
	parentID := old.ParentID
	if parentID == "" {
		parentID = old.ID
	}
	return m.enqueueWithLineage(botID, old.Kind, name, old.Priority, old.Payload, old.Checkpoint, parentID, old.Attempt+1), true
}

func (m *suiteTaskManager) retryFailed(botID int) int {
	m.mu.Lock()
	type retrySpec struct {
		kind       string
		name       string
		priority   int
		payload    map[string]interface{}
		checkpoint map[string]interface{}
		parentID   string
		attempt    int
	}
	specs := make([]retrySpec, 0)
	for _, t := range m.history[botID] {
		if t.Status != suiteTaskError {
			continue
		}
		cp := suiteCloneTask(t)
		parentID := cp.ParentID
		if parentID == "" {
			parentID = cp.ID
		}
		specs = append(specs, retrySpec{kind: cp.Kind, name: cp.Name, priority: cp.Priority, payload: cp.Payload, checkpoint: cp.Checkpoint, parentID: parentID, attempt: cp.Attempt + 1})
	}
	m.mu.Unlock()
	for _, spec := range specs {
		m.enqueueWithLineage(botID, spec.kind, spec.name, spec.priority, spec.payload, spec.checkpoint, spec.parentID, spec.attempt)
	}
	return len(specs)
}

func (m *suiteTaskManager) clearQueue(botID int) int {
	m.mu.Lock()
	q := m.queues[botID]
	removed := 0
	keep := q[:0]
	persisted := make([]suiteTask, 0, len(q))
	for _, t := range q {
		if t.Status == suiteTaskRunning {
			keep = append(keep, t)
			continue
		}
		if t.cancel != nil {
			t.cancel()
		}
		t.Status = suiteTaskCancelled
		t.Stage = "已清除"
		t.Outcome = suiteOutcomeCancelled
		t.NextAction = suiteNextNone
		t.UpdatedAt = time.Now()
		t.CompletedAt = time.Now()
		persisted = append(persisted, suiteCloneTask(t))
		removed++
	}
	m.queues[botID] = keep
	m.mu.Unlock()
	suiteScheduleTaskStoreSave()
	for _, task := range persisted {
		suitePersistTaskHistory(task)
	}
	return removed
}

func (m *suiteTaskManager) releaseTask(botID int, id string) bool {
	m.mu.Lock()
	t := m.findLocked(botID, id)
	if t != nil && (t.Status == suiteTaskBlocked || t.Status == suiteTaskPaused) {
		suiteResetTaskForManualRelease(t, time.Now())
		m.mu.Unlock()
		suiteScheduleTaskStoreSave()
		return true
	}
	if t != nil {
		queued := t.Status == suiteTaskQueued
		m.mu.Unlock()
		return queued
	}
	var old suiteTask
	found := false
	for i := len(m.history[botID]) - 1; i >= 0; i-- {
		if m.history[botID][i] != nil && m.history[botID][i].ID == id {
			old = suiteCloneTask(m.history[botID][i])
			found = true
			break
		}
	}
	m.mu.Unlock()
	if !found || old.Status != suiteTaskError {
		return false
	}
	parentID := old.ParentID
	if parentID == "" {
		parentID = old.ID
	}
	m.enqueueWithLineage(botID, old.Kind, old.Name, old.Priority, old.Payload, old.Checkpoint, parentID, old.Attempt+1)
	return true
}

func (m *suiteTaskManager) reorderTask(botID int, id string, direction int) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	q := m.queues[botID]
	idx := -1
	for i, t := range q {
		if t.ID == id {
			idx = i
			break
		}
	}
	if idx < 0 || q[idx].Status == suiteTaskRunning {
		return false
	}
	target := idx + direction
	if target < 0 || target >= len(q) {
		return false
	}
	q[idx], q[target] = q[target], q[idx]
	// 同優先級時 worker 依目前 slice 順序執行；調整一點優先級可避免下一次 enqueue
	// 的排序又把使用者手動順序打回去。
	if direction < 0 && q[target].Priority <= q[idx].Priority {
		q[target].Priority = q[idx].Priority + 1
	} else if direction > 0 && q[target].Priority >= q[idx].Priority {
		q[target].Priority = q[idx].Priority - 1
	}
	m.queues[botID] = q
	suiteScheduleTaskStoreSave()
	return true
}

func (m *suiteTaskManager) reassignTask(botID int, id string, targetBotID int) (suiteTask, bool) {
	if targetBotID <= 0 || targetBotID == botID {
		return suiteTask{}, false
	}
	old, ok := m.cloneTaskByID(botID, id)
	if !ok {
		return suiteTask{}, false
	}
	// 排隊中的任務先從原 Bot 移除；歷史中的完成/失敗任務則直接複製到新 Bot。
	if old.Status == suiteTaskQueued || old.Status == suiteTaskBlocked || old.Status == suiteTaskPaused {
		if !m.removeTask(botID, id) {
			return suiteTask{}, false
		}
	} else if old.Status == suiteTaskRunning {
		return suiteTask{}, false
	}
	old.BotID = targetBotID
	parentID := old.ParentID
	if parentID == "" {
		parentID = old.ID
	}
	return m.enqueueWithLineage(targetBotID, old.Kind, old.Name, old.Priority, old.Payload, old.Checkpoint, parentID, old.Attempt), true
}

func (m *suiteTaskManager) updateQueuedTask(botID int, id, name string, priority *int, payload map[string]interface{}) (suiteTask, bool, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	t := m.findLocked(botID, id)
	if t == nil {
		return suiteTask{}, false, nil
	}
	if t.Status == suiteTaskRunning {
		return suiteTask{}, true, fmt.Errorf("執行中的任務不可直接編輯；請先取消後重排")
	}
	if strings.TrimSpace(name) != "" {
		t.Name = strings.TrimSpace(name)
	}
	if priority != nil {
		t.Priority = *priority
	}
	if payload != nil {
		if t.Payload == nil {
			t.Payload = map[string]interface{}{}
		}
		for k, v := range payload {
			t.Payload[k] = v
		}
		t.PayloadHash = suitePayloadDigest(t.Payload)
	}
	t.Resources = suiteNormaliseResources(suiteResourcesForKind(t.Kind))
	t.UpdatedAt = time.Now()
	if t.Status == suiteTaskBlocked || t.Status == suiteTaskPaused {
		t.Stage = "已更新設定，等待繼續"
	} else {
		t.Stage = "等待執行"
	}
	sort.SliceStable(m.queues[botID], func(i, j int) bool { return m.queues[botID][i].Priority > m.queues[botID][j].Priority })
	suiteScheduleTaskStoreSave()
	return suiteCloneTask(t), true, nil
}

func (m *suiteTaskManager) acquireResources(ctx context.Context, t *suiteTask) (func(), error) {
	resources := suiteNormaliseResources(t.Resources)
	for {
		if err := ctx.Err(); err != nil {
			return nil, err
		}
		m.mu.Lock()
		busy := ""
		if m.resources[t.BotID] == nil {
			m.resources[t.BotID] = map[string]suiteResourceLease{}
		}
		for _, r := range resources {
			if l, ok := m.resources[t.BotID][r]; ok && l.TaskID != t.ID {
				busy = fmt.Sprintf("%s：%s", r, l.TaskName)
				break
			}
		}
		if busy == "" {
			for _, r := range resources {
				m.resources[t.BotID][r] = suiteResourceLease{TaskID: t.ID, TaskName: t.Name, Resource: r, Acquired: time.Now()}
			}
			m.mu.Unlock()
			return func() {
				m.mu.Lock()
				for _, r := range resources {
					if l, ok := m.resources[t.BotID][r]; ok && l.TaskID == t.ID {
						delete(m.resources[t.BotID], r)
					}
				}
				m.mu.Unlock()
			}, nil
		}
		t.Status = suiteTaskBlocked
		t.Stage = "等待資源"
		t.Message = busy
		t.UpdatedAt = time.Now()
		m.mu.Unlock()
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(80 * time.Millisecond):
		}
	}
}

func suiteTaskBotRecoveryState(botID int) (bool, uint64) {
	sessionMu.RLock()
	bot := sessions[botID]
	sessionMu.RUnlock()
	if bot == nil {
		return false, 0
	}
	bot.mu.Lock()
	ready := bot.IsActive && bot.Connected && bot.PlayerReady && bot.conn != nil && !bot.Respawning.Load()
	generation := bot.SessionGeneration
	bot.mu.Unlock()
	return ready, generation
}

func (m *suiteTaskManager) worker(botID int) {
	for {
		m.mu.Lock()
		if m.paused[botID] {
			m.mu.Unlock()
			time.Sleep(120 * time.Millisecond)
			continue
		}
		var t *suiteTask
		for _, candidate := range m.queues[botID] {
			if candidate.Status == suiteTaskQueued || candidate.Status == suiteTaskBlocked {
				t = candidate
				break
			}
		}
		if t == nil {
			// Clear the worker flag while holding the same lock enqueue() uses. This
			// avoids losing a task enqueued between an unlocked return and a defer.
			m.workers[botID] = false
			m.mu.Unlock()
			return
		}
		candidate := suiteCloneTask(t)
		needsRecoveryGate := suiteTaskAutoRecoveryEligible(&candidate)
		m.mu.Unlock()

		if needsRecoveryGate {
			botReady, sessionGeneration := suiteTaskBotRecoveryState(botID)
			allowed, wait := suiteAutomaticRecoveryGate(&candidate, time.Now(), botReady, sessionGeneration)
			if !allowed {
				if wait <= 0 {
					wait = suiteAutoRecoveryPollDelay
				}
				time.Sleep(wait)
				continue
			}
		}

		m.mu.Lock()
		// The task may have been cancelled, removed or manually released while the
		// worker was waiting for its retry deadline/session-generation gate.
		t = m.findLocked(botID, candidate.ID)
		if t == nil || m.paused[botID] || (t.Status != suiteTaskQueued && t.Status != suiteTaskBlocked) {
			m.mu.Unlock()
			continue
		}
		ctx, cancel := context.WithCancel(context.Background())
		t.cancel = cancel
		t.Status = suiteTaskRunning
		t.Stage = "準備"
		t.Message = ""
		t.Error = ""
		t.Outcome = ""
		t.NextAction = suiteNextNone
		t.RetryAt = time.Time{}
		t.StartedAt = time.Now()
		t.WaitingMS = t.StartedAt.Sub(t.CreatedAt).Milliseconds()
		t.UpdatedAt = time.Now()
		m.mu.Unlock()
		suiteScheduleTaskStoreSave()

		release, err := m.acquireResources(ctx, t)
		if err == nil {
			err = runSuiteTaskSafely(ctx, t)
		}
		if release != nil {
			release()
		}
		cancel()

		m.mu.Lock()
		t.cancel = nil
		finishedAt := time.Now()
		t.UpdatedAt = finishedAt
		t.CompletedAt = finishedAt
		if !t.StartedAt.IsZero() {
			t.ActiveMS += t.CompletedAt.Sub(t.StartedAt).Milliseconds()
		}
		if t.Status == suiteTaskPaused && errors.Is(err, context.Canceled) {
			t.Stage = "已暫停，保留檢查點"
			t.Outcome = suiteOutcomeControlShift
			t.NextAction = suiteNextResume
			t.CompletedAt = time.Time{}
			m.mu.Unlock()
			suiteScheduleTaskStoreSave()
			continue
		}
		t.Outcome, t.NextAction = suiteTaskOutcome(err)
		if t.Status == suiteTaskCancelled || errors.Is(err, context.Canceled) {
			t.Status = suiteTaskCancelled
			t.Stage = "已取消"
			t.Outcome = suiteOutcomeCancelled
			t.NextAction = suiteNextNone
		} else if err != nil {
			t.Error = err.Error()
			if suiteScheduleAutomaticRecovery(t, finishedAt) {
				// Recoverable work remains in the durable live queue. The worker will
				// consume RetryAt/NextAction/SessionGen before entering the runner again.
				m.mu.Unlock()
				suiteScheduleTaskStoreSave()
				continue
			}
			t.Status = suiteTaskError
			t.RetryAt = time.Time{}
			switch t.Outcome {
			case suiteOutcomeConnectionLost:
				t.Stage = "連線中斷"
			case suiteOutcomeLicensePaused:
				t.Stage = "等待授權"
			case suiteOutcomeControlShift:
				t.Stage = "控制權已轉移"
			case suiteOutcomeRecoveryRequired:
				t.Stage = "等待角色／世界復原"
			case suiteOutcomeTransient:
				t.Stage = "暫時性協定錯誤"
			case suiteOutcomePermanentInput:
				t.Stage = "任務輸入需修正"
			case suiteOutcomeBlockedOperator:
				t.Stage = "需要人工處理"
			default:
				t.Stage = "執行失敗"
			}
		} else {
			t.Status = suiteTaskCompleted
			t.Stage = "完成"
			t.Progress = 100
			t.RetryAt = time.Time{}
		}
		// A finished task must leave the live queue exactly once. History is bounded and
		// de-duplicated by archiveTaskLocked, so long-running sessions no longer accumulate
		// completed rows in Task Queue.
		m.archiveTaskLocked(botID, t)
		persisted := suiteCloneTask(t)
		m.mu.Unlock()
		suiteScheduleTaskStoreSave()
		suitePersistTaskHistory(persisted)
	}
}

func (m *suiteTaskManager) update(t *suiteTask, stage string, progress float64, message string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if t == nil {
		return
	}
	// V59: pause cancels the running context. A final in-flight status update used
	// to set the task back to RUNNING after setPaused() had already marked it PAUSED.
	// The worker would then archive the cancellation and Resume had nothing usable
	// to restart. While paused, preserve the checkpoint/status exactly as-is.
	if t.Status == suiteTaskPaused {
		return
	}
	if t.Status != suiteTaskCancelled {
		t.Status = suiteTaskRunning
	}
	t.Stage = strings.TrimSpace(stage)
	if progress >= 0 {
		t.Progress = math.Max(0, math.Min(100, progress))
	}
	t.Message = strings.TrimSpace(message)
	t.UpdatedAt = time.Now()
	suiteScheduleTaskStoreSave()
}

func (m *suiteTaskManager) checkpoint(t *suiteTask, values map[string]interface{}) {
	if t == nil || len(values) == 0 {
		return
	}
	m.mu.Lock()
	if t.Checkpoint == nil {
		t.Checkpoint = map[string]interface{}{}
	}
	for key, value := range values {
		t.Checkpoint[key] = value
	}
	t.UpdatedAt = time.Now()
	m.mu.Unlock()
	suiteScheduleTaskStoreSave()
}

func (m *suiteTaskManager) checkpointInt(t *suiteTask, key string) int {
	if t == nil {
		return 0
	}
	m.mu.Lock()
	checkpoint := suiteClonePayloadMap(t.Checkpoint)
	m.mu.Unlock()
	return suitePayloadInt(checkpoint, key, 0)
}

