func copyBedrockCraftRecipe(networkID uint32, width, height int32, shapeless bool, input []protocol.ItemDescriptorCount, output []protocol.ItemStack) bedrockCraftRecipe {
	return bedrockCraftRecipe{
		NetworkID: networkID,
		Width:     width,
		Height:    height,
		Shapeless: shapeless,
		Input:     append([]protocol.ItemDescriptorCount(nil), input...),
		Output:    append([]protocol.ItemStack(nil), output...),
	}
}

// updateBedrockCraftingData mirrors the recipes announced by the current
// server. Only normal shaped/shapeless recipes that can fit in the player's
// 2x2 grid are retained; workbench-only 3x3 recipes cannot be made in this UI.
func (bot *BotSession) updateBedrockCraftingData(pk *packet.CraftingData) {
	if bot == nil || pk == nil {
		return
	}
	recipes := make([]bedrockCraftRecipe, 0, len(pk.ShapedRecipes)+len(pk.ShapelessRecipes))
	appendShaped := func(recipe protocol.ShapedRecipe) {
		if recipe.RecipeNetworkID == 0 || recipe.Width <= 0 || recipe.Height <= 0 || recipe.Width > 2 || recipe.Height > 2 || len(recipe.Output) == 0 {
			return
		}
		recipes = append(recipes, copyBedrockCraftRecipe(recipe.RecipeNetworkID, recipe.Width, recipe.Height, false, recipe.Input, recipe.Output))
	}
	appendShapeless := func(recipe protocol.ShapelessRecipe) {
		if recipe.RecipeNetworkID == 0 || len(recipe.Input) == 0 || len(recipe.Input) > 4 || len(recipe.Output) == 0 {
			return
		}
		recipes = append(recipes, copyBedrockCraftRecipe(recipe.RecipeNetworkID, 0, 0, true, recipe.Input, recipe.Output))
	}
	for _, recipe := range pk.ShapedRecipes {
		appendShaped(recipe)
	}
	for _, recipe := range pk.ShapelessRecipes {
		appendShapeless(recipe)
	}
	for _, recipe := range pk.UserDataShapelessRecipes {
		appendShapeless(recipe.ShapelessRecipe)
	}
	for _, recipe := range pk.ShapelessChemistryRecipes {
		appendShapeless(recipe.ShapelessRecipe)
	}
	for _, recipe := range pk.ShapedChemistryRecipes {
		appendShaped(recipe.ShapedRecipe)
	}
	multiRecipeIDs := make([]uint32, 0, len(pk.MultiRecipes))
	for _, recipe := range pk.MultiRecipes {
		if recipe.RecipeNetworkID != 0 {
			multiRecipeIDs = append(multiRecipeIDs, recipe.RecipeNetworkID)
		}
	}

	bot.mu.Lock()
	if pk.ClearRecipes {
		bot.MapArtCraftRecipes = nil
		bot.MapArtMultiRecipeIDs = nil
	}
	bot.MapArtCraftRecipes = append(bot.MapArtCraftRecipes, recipes...)
	bot.MapArtMultiRecipeIDs = append(bot.MapArtMultiRecipeIDs, multiRecipeIDs...)
	totalRecipes := len(bot.MapArtCraftRecipes)
	totalMultiRecipes := len(bot.MapArtMultiRecipeIDs)
	bot.InventoryRevision++
	bot.mu.Unlock()
	logCollectDiagnostic(bot, "crafting_data", fmt.Sprintf(
		"clear=%t shaped=%d shapeless=%d user_shapeless=%d chemistry_shapeless=%d chemistry_shaped=%d accepted_2x2=%d total_2x2=%d",
		pk.ClearRecipes,
		len(pk.ShapedRecipes),
		len(pk.ShapelessRecipes),
		len(pk.UserDataShapelessRecipes),
		len(pk.ShapelessChemistryRecipes),
		len(pk.ShapedChemistryRecipes),
		len(recipes),
		totalRecipes,
	))
	if len(multiRecipeIDs) > 0 {
		logCollectDiagnostic(bot, "crafting_multi_data", fmt.Sprintf("received=%d total=%d", len(multiRecipeIDs), totalMultiRecipes))
	}
	bot.mapArtSignal()
}

const (
	bedrockPlayerCraftingSlotOffset = 28
	bedrockCreatedOutputSlot        = 50
)

// The player inventory's 2x2 crafting slots are shown as logical slots 0..3 in
// the App, but Bedrock stack requests address them as UI slots 28..31.
func bedrockPlayerCraftingWireSlot(logical int) (int, bool) {
	if logical < 0 || logical >= 4 {
		return 0, false
	}
	return logical + bedrockPlayerCraftingSlotOffset, true
}

func bedrockPlayerCraftingLogicalSlot(wire int) (int, bool) {
	if wire >= bedrockPlayerCraftingSlotOffset && wire < bedrockPlayerCraftingSlotOffset+4 {
		return wire - bedrockPlayerCraftingSlotOffset, true
	}
	// Some servers normalise the auxiliary container to a compact four-slot
	// array in InventoryContent. Accept that form while always sending 28..31.
	if wire >= 0 && wire < 4 {
		return wire, true
	}
	return 0, false
}

func bedrockPlayerCraftingContent(content []protocol.ItemInstance) []protocol.ItemInstance {
	grid := make([]protocol.ItemInstance, 4)
	if len(content) >= bedrockPlayerCraftingSlotOffset+4 {
		copy(grid, content[bedrockPlayerCraftingSlotOffset:bedrockPlayerCraftingSlotOffset+4])
		return grid
	}
	copy(grid, content)
	return grid
}

func (bot *BotSession) updateMapArtAuxiliaryContent(container protocol.FullContainerName, content []protocol.ItemInstance) bool {
	if bot == nil {
		return false
	}
	id := int(container.ContainerID)
	if id != protocol.ContainerCursor && id != protocol.ContainerCraftingInput &&
		id != protocol.ContainerCraftingOutputPreview && id != protocol.ContainerCreatedOutput {
		return false
	}
	cp := append([]protocol.ItemInstance(nil), content...)
	if id == protocol.ContainerCraftingInput {
		cp = bedrockPlayerCraftingContent(cp)
	}
	bot.mu.Lock()
	switch id {
	case protocol.ContainerCursor:
		bot.MapArtCursor = protocol.ItemInstance{}
		if len(cp) > 0 {
			bot.MapArtCursor = cp[0]
		}
		bot.MapArtCursorReady = true
	case protocol.ContainerCraftingInput:
		bot.MapArtCraftingInput = cp
		bot.MapArtCraftingInputReady = true
	default:
		bot.MapArtCraftingOutput = cp
		bot.MapArtCraftingOutputReady = true
	}
	for _, item := range cp {
		bot.updateMapArtBlockNameLocked(item)
		bot.learnDropItemAliasesLocked(item)
	}
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
	return true
}

func (bot *BotSession) updateMapArtAuxiliarySlot(container protocol.FullContainerName, slot uint32, item protocol.ItemInstance) bool {
	if bot == nil {
		return false
	}
	id := int(container.ContainerID)
	if id != protocol.ContainerCursor && id != protocol.ContainerCraftingInput &&
		id != protocol.ContainerCraftingOutputPreview && id != protocol.ContainerCreatedOutput {
		return false
	}
	bot.mu.Lock()
	switch id {
	case protocol.ContainerCursor:
		bot.MapArtCursor = item
		bot.MapArtCursorReady = true
	case protocol.ContainerCraftingInput:
		logicalSlot, ok := bedrockPlayerCraftingLogicalSlot(int(slot))
		if !ok {
			bot.mu.Unlock()
			return false
		}
		if len(bot.MapArtCraftingInput) < 4 {
			next := make([]protocol.ItemInstance, 4)
			copy(next, bot.MapArtCraftingInput)
			bot.MapArtCraftingInput = next
		}
		bot.MapArtCraftingInput[logicalSlot] = item
		bot.MapArtCraftingInputReady = true
	default:
		need := int(slot) + 1
		if need > len(bot.MapArtCraftingOutput) {
			next := make([]protocol.ItemInstance, need)
			copy(next, bot.MapArtCraftingOutput)
			bot.MapArtCraftingOutput = next
		}
		bot.MapArtCraftingOutput[int(slot)] = item
		bot.MapArtCraftingOutputReady = true
	}
	bot.updateMapArtBlockNameLocked(item)
	bot.learnDropItemAliasesLocked(item)
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
	return true
}

func (bot *BotSession) updateBedrockMapPreview(pk *packet.ClientBoundMapItemData) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	if bot.MapPreviews == nil {
		bot.MapPreviews = map[int64]*bedrockMapPreview{}
	}
	preview := bot.MapPreviews[pk.MapID]
	if preview == nil {
		preview = &bedrockMapPreview{
			MapID: pk.MapID, Pixels: make([]color.RGBA, 128*128), Known: make([]bool, 128*128),
		}
		bot.MapPreviews[pk.MapID] = preview
	}
	preview.Dimension = pk.Dimension
	preview.Locked = pk.LockedMap
	preview.Origin = pk.Origin
	if scale, ok := pk.Scale.Value(); ok {
		preview.Scale = scale
	}
	width, widthSet := pk.Width.Value()
	height, heightSet := pk.Height.Value()
	xOffset, xSet := pk.XOffset.Value()
	yOffset, ySet := pk.YOffset.Value()
	pixels, pixelsSet := pk.Pixels.Value()
	if pixelsSet {
		if !widthSet || width <= 0 {
			width = 128
		}
		if !heightSet || height <= 0 {
			height = int32((len(pixels) + int(width) - 1) / int(width))
		}
		if !xSet {
			xOffset = 0
		}
		if !ySet {
			yOffset = 0
		}
		for y := int32(0); y < height; y++ {
			for x := int32(0); x < width; x++ {
				source := int(y*width + x)
				dx, dy := xOffset+x, yOffset+y
				if source < 0 || source >= len(pixels) || dx < 0 || dx >= 128 || dy < 0 || dy >= 128 {
					continue
				}
				destination := int(dy*128 + dx)
				preview.Pixels[destination] = pixels[source]
				preview.Known[destination] = true
			}
		}
	}
	preview.UpdatedAt = time.Now()
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func bedrockMapPreviewPNG(bot *BotSession, mapID int64) ([]byte, bool) {
	if bot == nil {
		return nil, false
	}
	bot.mu.Lock()
	preview := bot.MapPreviews[mapID]
	if preview == nil {
		bot.mu.Unlock()
		return nil, false
	}
	pixels := append([]color.RGBA(nil), preview.Pixels...)
	known := append([]bool(nil), preview.Known...)
	bot.mu.Unlock()

	img := image.NewRGBA(image.Rect(0, 0, 128, 128))
	for i, pixel := range pixels {
		if i >= len(known) || !known[i] {
			continue
		}
		img.SetRGBA(i%128, i/128, pixel)
	}
	var buf bytes.Buffer
	if png.Encode(&buf, img) != nil {
		return nil, false
	}
	return buf.Bytes(), true
}

func requestBedrockMapPreview(bot *BotSession, mapID int64) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	bot.mu.Lock()
	conn := bot.conn
	ready := bot.Connected && bot.PlayerReady && conn != nil && !bot.Respawning.Load()
	bot.mu.Unlock()
	if !ready {
		return errors.New("BOT 尚未完成登入/出生")
	}
	if err := conn.WritePacket(&packet.MapInfoRequest{MapID: mapID}); err != nil {
		return err
	}
	return conn.Flush()
}

// requestBedrockInventoryResync sends Bedrock's inventory-mismatch transaction.
// A conforming server answers it by resending its authoritative inventory. This
// is the real server resync behind the App button; fetching our local snapshot
// again cannot recover an initial Content/Slot packet that a proxy delayed.
func requestBedrockInventoryResync(bot *BotSession) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	bot.mu.Lock()
	conn := bot.conn
	available := bot.Connected && conn != nil && !bot.Respawning.Load()
	bot.mu.Unlock()
	if !available {
		return errors.New("BOT 尚未完成 Bedrock 連線")
	}
	if err := conn.WritePacket(&packet.InventoryTransaction{
		TransactionData: &protocol.MismatchTransactionData{},
	}); err != nil {
		return fmt.Errorf("送出背包重新同步失敗: %w", err)
	}
	if err := conn.Flush(); err != nil {
		return fmt.Errorf("送出背包重新同步失敗: %w", err)
	}
	return nil
}

func suiteContainerHintKind(raw string) string {
	v := strings.ToLower(strings.TrimSpace(raw))
	v = strings.ReplaceAll(v, "minecraft:", "")
	switch {
	case strings.Contains(v, "shulker"):
		return "minecraft:shulker_box"
	case strings.Contains(v, "barrel"):
		return "minecraft:barrel"
	case strings.Contains(v, "chest"):
		return "minecraft:chest"
	default:
		return ""
	}
}

// updateMapArtContainerHint remembers tile-entity positions sent by the server.
// This is important on Java/Geyser servers where the block runtime palette does
// not always provide a usable runtimeID -> name mapping for ordinary chests.
func (bot *BotSession) updateMapArtContainerHint(pk *packet.BlockActorData) {
	if bot == nil || pk == nil {
		return
	}
	kind := ""
	for _, key := range []string{"id", "Id", "identifier", "type"} {
		if value, ok := pk.NBTData[key]; ok {
			kind = suiteContainerHintKind(fmt.Sprint(value))
			if kind != "" {
				break
			}
		}
	}
	if kind == "" {
		return
	}
	pos := Vec3i{X: int(pk.Position[0]), Y: int(pk.Position[1]), Z: int(pk.Position[2])}
	bot.mu.Lock()
	if bot.MapArtContainerHints == nil {
		bot.MapArtContainerHints = map[string]string{}
	}
	bot.MapArtContainerHints[mapArtDimensionBlockKey(bot.MapArtCurrentDimension, pos)] = kind
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) updateMapArtContainerOpen(pk *packet.ContainerOpen) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	if pk.ContainerType == 0xff {
		bot.PlayerInventoryActionOpen = true
		bot.PlayerInventoryActionWindowID = pk.WindowID
		bot.mu.Unlock()
		bot.mapArtSignal()
		return
	}
	pos := Vec3i{X: int(pk.ContainerPosition[0]), Y: int(pk.ContainerPosition[1]), Z: int(pk.ContainerPosition[2])}
	if bot.MapArtContainerHints == nil {
		bot.MapArtContainerHints = map[string]string{}
	}
	bot.MapArtContainerHints[mapArtDimensionBlockKey(bot.MapArtCurrentDimension, pos)] = "minecraft:container"
	bot.MapArtContainerOpen = true
	bot.MapArtContainerWindowID = pk.WindowID
	bot.MapArtContainerType = pk.ContainerType
	bot.MapArtContainerPos = pos
	bot.MapArtContainerItems = nil
	bot.MapArtContainerItemsReady = false
	bot.MapArtContainerName = protocol.FullContainerName{}
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) updateMapArtContainerClose(pk *packet.ContainerClose) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	if bot.PlayerInventoryActionOpen && bot.PlayerInventoryActionWindowID == pk.WindowID {
		bot.PlayerInventoryActionOpen = false
		bot.PlayerInventoryActionWindowID = 0
	}
	if bot.MapArtContainerOpen && bot.MapArtContainerWindowID == pk.WindowID {
		bot.MapArtContainerOpen = false
		bot.MapArtContainerItemsReady = false
		bot.MapArtContainerItems = nil
		bot.MapArtContainerName = protocol.FullContainerName{}
		bot.InventoryRevision++
	}
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) updateMapArtContainerContent(windowID uint32, container protocol.FullContainerName, content []protocol.ItemInstance) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	if bot.MapArtContainerOpen && uint32(bot.MapArtContainerWindowID) == windowID {
		bot.MapArtContainerItems = append([]protocol.ItemInstance(nil), content...)
		bot.MapArtContainerItemsReady = true
		bot.MapArtContainerName = container
		for _, item := range content {
			bot.updateMapArtBlockNameLocked(item)
			bot.learnDropItemAliasesLocked(item)
		}
		bot.InventoryRevision++
	}
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) updateMapArtContainerSlot(windowID uint32, slot uint32, item protocol.ItemInstance) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	if bot.MapArtContainerOpen && uint32(bot.MapArtContainerWindowID) == windowID {
		need := int(slot) + 1
		if need > len(bot.MapArtContainerItems) {
			next := make([]protocol.ItemInstance, need)
			copy(next, bot.MapArtContainerItems)
			bot.MapArtContainerItems = next
		}
		bot.MapArtContainerItems[int(slot)] = item
		bot.MapArtContainerItemsReady = true
		bot.updateMapArtBlockNameLocked(item)
		bot.learnDropItemAliasesLocked(item)
		bot.InventoryRevision++
	}
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) updateMapArtStackResponses(responses []protocol.ItemStackResponse) {
	if bot == nil || len(responses) == 0 {
		return
	}
	bot.mu.Lock()
	if bot.MapArtStackResponses == nil {
		bot.MapArtStackResponses = map[int32]protocol.ItemStackResponse{}
	}
	for _, response := range responses {
		bot.MapArtStackResponses[response.RequestID] = response
		// The response has arrived; waitMapArtStackResponse will consume the
		// response itself, while this bookkeeping entry may be released now.
		delete(bot.BedrockPendingStackRequests, response.RequestID)
	}
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) nextMapArtStackRequestID() int32 {
	if bot == nil {
		return -1
	}
	bot.mu.Lock()
	defer bot.mu.Unlock()
	// 原版 1.26.40 客戶端以負奇數遞減：-1、-3、-5……。
	// 伺服器會用這個 ID 回覆 ItemStackResponse；不要再送 Bot 自造的正數序列。
	if bot.MapArtStackRequestID >= 0 {
		bot.MapArtStackRequestID = -1
	} else {
		bot.MapArtStackRequestID -= 2
	}
	return bot.MapArtStackRequestID
}

func (bot *BotSession) waitMapArtStackResponse(ctx context.Context, requestID int32, timeout time.Duration) (protocol.ItemStackResponse, error) {
	if bot == nil {
		return protocol.ItemStackResponse{}, errors.New("地圖繪 BOT 不存在")
	}
	if timeout <= 0 {
		timeout = time.Second
	}
	timer := time.NewTimer(timeout)
	defer timer.Stop()
	for {
		bot.mu.Lock()
		response, ok := bot.MapArtStackResponses[requestID]
		if ok {
			delete(bot.MapArtStackResponses, requestID)
		}
		notify := bot.MapArtNotify
		bot.mu.Unlock()
		if ok {
			return response, nil
		}
		select {
		case <-ctx.Done():
			return protocol.ItemStackResponse{}, ctx.Err()
		case <-timer.C:
			return protocol.ItemStackResponse{}, fmt.Errorf("等待 ItemStackResponse #%d 逾時", requestID)
		case <-notify:
		}
	}
}

func (bot *BotSession) applyMapArtInventorySwap(a, b int) {
	if bot == nil || a < 0 || b < 0 {
		return
	}
	bot.mu.Lock()
	need := maxInt(a, b) + 1
	if need > len(bot.MapArtInventory) {
		next := make([]protocol.ItemInstance, need)
		copy(next, bot.MapArtInventory)
		bot.MapArtInventory = next
	}
	bot.MapArtInventory[a], bot.MapArtInventory[b] = bot.MapArtInventory[b], bot.MapArtInventory[a]
	bot.updateMapArtBlockNameLocked(bot.MapArtInventory[a])
	bot.updateMapArtBlockNameLocked(bot.MapArtInventory[b])
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func (bot *BotSession) syncMapArtServerTick(tick uint64) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	changed := false
	if !bot.MapArtServerTickReady {
		bot.MapArtServerTick = tick
		bot.MapArtServerTickAt = time.Now()
		bot.MapArtServerTickReady = true
		changed = true
	} else if tick > 0 && tick >= bot.MapArtServerTick {
		// tick=0 的 MovePlayer/Actor 狀態包很常見。基準建立後若仍以
		// 0 >= 0 更新時間，PlayerAuthInput 會永遠從 tick 1 開始，
		// 實際伺服器會把挖掘輸入視為過期或不連續而直接忽略。
		bot.MapArtServerTick = tick
		bot.MapArtServerTickAt = time.Now()
		changed = true
	}
	bot.mu.Unlock()
	if changed {
		bot.mapArtSignal()
	}
}

func (bot *BotSession) nextMapArtAuthTick() (uint64, error) {
	if bot == nil {
		return 0, errors.New("地圖繪 BOT 不存在")
	}

	bot.mu.Lock()
	defer bot.mu.Unlock()

	// 只按照實際送出的 PlayerAuthInput 封包遞增。runAuthInputHeartbeat、
	// 自動走路與採集共用此鎖，所以不會重號或跨號。
	bot.MapArtMoveTick++
	bot.MapArtLastAuthInputAt = time.Now()
	return bot.MapArtMoveTick, nil
}

func bedrockMovePlayerIsHardCorrection(mode byte) bool {
	return mode == packet.MoveModeReset || mode == packet.MoveModeTeleport
}

// sendBedrockAuthInput keeps allocation and network write in one critical
// section. Callers provide every field except Tick and receive the allocated
// tick for correction-history bookkeeping.
func (bot *BotSession) sendBedrockPlacementFrameV105(
	conn *minecraft.Conn,
	input *packet.PlayerAuthInput,
	tx *packet.InventoryTransaction,
) (uint64, error) {
	if bot == nil || conn == nil || input == nil || tx == nil {
		return 0, errors.New("V105 放置 frame 連線或封包不存在")
	}
	bot.authInputMu.Lock()
	defer bot.authInputMu.Unlock()

	bot.mu.Lock()
	active := bot.conn == conn && bot.Connected
	bot.mu.Unlock()
	if !active {
		return 0, errors.New("V105 放置 frame 期間連線已變更或中斷")
	}
	tick, err := bot.nextMapArtAuthTick()
	if err != nil {
		return 0, err
	}
	input.Tick = tick
	// Important: preserve packet order but flush only once. The old fast path did:
	// PlayerAuthInput -> Flush -> InventoryTransaction -> Flush for every block.
	// On Windows/gophertunnel this doubles the synchronous network flush work and
	// makes the nominal 40ms scheduler miss its deadline under sustained load.
	if err := conn.WritePacket(input); err != nil {
		return tick, err
	}
	if err := conn.WritePacket(tx); err != nil {
		return tick, err
	}
	if err := conn.Flush(); err != nil {
		return tick, err
	}
	return tick, nil
}

func (bot *BotSession) sendBedrockAuthInput(conn *minecraft.Conn, input *packet.PlayerAuthInput) (uint64, error) {
	if bot == nil || conn == nil || input == nil {
		return 0, errors.New("PlayerAuthInput 連線或封包不存在")
	}
	bot.authInputMu.Lock()
	defer bot.authInputMu.Unlock()

	bot.mu.Lock()
	active := bot.conn == conn && bot.Connected
	bot.mu.Unlock()
	if !active {
		return 0, errors.New("PlayerAuthInput 連線已變更或中斷")
	}
	tick, err := bot.nextMapArtAuthTick()
	if err != nil {
		return 0, err
	}
	input.Tick = tick
	if err := conn.WritePacket(input); err != nil {
		return tick, err
	}
	if err := conn.Flush(); err != nil {
		return tick, err
	}
	return tick, nil
}

// sendBedrockAuthInputBatchV124 keeps one authoritative clear-bedrock tick in a
// single network flush. pre packets are ordered before PlayerAuthInput (FINISH/
// legacy break), post packets are ordered immediately after it (next START).
// This preserves packet order while avoiding 3~4 synchronous Flush calls for
// every mined block on Windows/gophertunnel.
func (bot *BotSession) sendBedrockAuthInputBatchV124(
	conn *minecraft.Conn,
	input *packet.PlayerAuthInput,
	pre []packet.Packet,
	post []packet.Packet,
) (uint64, error) {
	if bot == nil || conn == nil || input == nil {
		return 0, errors.New("PlayerAuthInput 批次連線或封包不存在")
	}
	bot.authInputMu.Lock()
	defer bot.authInputMu.Unlock()

	bot.mu.Lock()
	active := bot.conn == conn && bot.Connected
	bot.mu.Unlock()
	if !active {
		return 0, errors.New("PlayerAuthInput 批次連線已變更或中斷")
	}
	tick, err := bot.nextMapArtAuthTick()
	if err != nil {
		return 0, err
	}
	input.Tick = tick
	for _, pk := range pre {
		if pk == nil {
			continue
		}
		if err := conn.WritePacket(pk); err != nil {
			return tick, err
		}
	}
	if err := conn.WritePacket(input); err != nil {
		return tick, err
	}
	for _, pk := range post {
		if pk == nil {
			continue
		}
		if err := conn.WritePacket(pk); err != nil {
			return tick, err
		}
	}
	if err := conn.Flush(); err != nil {
		return tick, err
	}
	return tick, nil
}

// runAuthInputHeartbeat reproduces the continuous 20 TPS PlayerAuthInput stream
// sent by a normal Bedrock client. Server-authoritative movement and actions are
// inserted into this same monotonically increasing, serialised tick stream.
func (bot *BotSession) runAuthInputHeartbeat(conn *minecraft.Conn) {
	if bot == nil || conn == nil {
		return
	}

	// Server-authoritative movement advances only when an input frame arrives.
	// Keep this stream alive while idle; active movement emits its own 20 TPS
	// frames and temporarily suppresses the idle frame below.
	ticker := time.NewTicker(50 * time.Millisecond)
	defer ticker.Stop()

	for {
		<-ticker.C

		bot.mu.Lock()
		if bot.conn != conn || !bot.Connected {
			bot.mu.Unlock()
			return
		}
		ackServerData := !bot.MapArtServerDataAcknowledged
		localMovement := bot.BFLocalMoveActive
		lastAuthAt := bot.MapArtLastAuthInputAt
		ready := bot.PlayerReady && !bot.Respawning.Load()
		pos := bot.LastPlayerPos
		onGround := bot.LastPlayerOnGround
		pitch := bot.LastPlayerPitch
		yaw := bot.LastPlayerYaw
		headYaw := bot.LastPlayerHeadYaw
		bot.mu.Unlock()
		if !ready || localMovement || (!lastAuthAt.IsZero() && time.Since(lastAuthAt) < 35*time.Millisecond) {
			continue
		}

		flags := protocol.NewInputFlags(packet.InputFlagCount)
		flags.Set(packet.InputFlagBlockBreakingDelayEnabled)
		if ackServerData {
			flags.Set(packet.InputFlagClientAckServerData)
		}
		if mapArtLikelyOnGround(pos, onGround) {
			flags.Set(packet.InputFlagVerticalCollision)
		}
		input := &packet.PlayerAuthInput{
			Pitch:              pitch,
			Yaw:                yaw,
			HeadYaw:            headYaw,
			Position:           mgl32.Vec3{pos[0], pos[1], pos[2]},
			MoveVector:         mgl32.Vec2{},
			InputData:          flags,
			InputMode:          packet.InputModeMouse,
			PlayMode:           packet.PlayModeScreen,
			InteractionModel:   packet.InteractionModelCrosshair,
			InteractPitch:      pitch,
			InteractYaw:        yaw,
			Delta:              mgl32.Vec3{},
			AnalogueMoveVector: mgl32.Vec2{},
			CameraOrientation:  mapArtCameraForward(yaw),
			RawMoveVector:      mgl32.Vec2{},
		}
		if _, err := bot.sendBedrockAuthInput(conn, input); err != nil {
			return
		}
		bot.mu.Lock()
		if bot.conn == conn {
			if ackServerData {
				bot.MapArtServerDataAcknowledged = true
			}
		}
		bot.mu.Unlock()
	}
}

