func suiteSourceMethodMatrixSnapshot() map[string]interface{} {
	native, equivalent := 0, 0
	authNames := map[string]bool{
		"Logout": true, "ResumeAfterCredentialUpdate": true,
		"ResumeAuthenticatedQueuedTask": true, "StartDiscordLogin": true, "StartOAuth": true,
	}
	authMapped, nonLoginMapped := 0, 0
	for _, item := range suiteSourceMethodMatrix {
		if item.Mode == "bedrock_native" {
			native++
		} else {
			equivalent++
		}
		if authNames[item.Name] {
			authMapped++
		} else {
			nonLoginMapped++
		}
	}
	return map[string]interface{}{
		"ok": true, "source": "windows-amd64-map-tool", "source_methods": len(suiteSourceMethodMatrix),
		"mapped": len(suiteSourceMethodMatrix), "bedrock_native": native,
		"bedrock_equivalent": equivalent, "methods": suiteSourceMethodMatrix,
		"non_login_source_methods": len(suiteSourceMethodMatrix) - len(authNames),
		"non_login_mapped":         nonLoginMapped,
		"login_methods":            len(authNames), "login_mapped_to_own": authMapped,
		"login_source": "existing_app_bedrock_xbox",
		"build":        "FULL-PORT-V30-NONLOGIN-FULL-OWN-LOGIN",
	}
}

