type suitePortStateData struct {
	StorageProfiles map[int][]suiteStorageProfile    `json:"storage_profiles"`
	BuildClaims     map[int][]suiteBuildClaim        `json:"build_claims"`
	MapTools        map[int]suiteMapToolSettings     `json:"map_tools"`
	MapPolicy       map[int][]string                 `json:"map_policy"`
	Library         map[int][]suiteLibraryItem       `json:"library"`
	ImportGroups    map[int][]suiteImportGroup       `json:"import_groups"`
	History         map[int][]suitePersistentHistory `json:"history"`
	IssueReports    map[int][]suiteIssueReport       `json:"issue_reports,omitempty"`
}

var suitePortState = struct {
	sync.Mutex
	loaded bool
	data   suitePortStateData
}{}

func suitePortStatePath() string {
	return filepath.Join(botDataDir, "minecraft-bot-toolbox.json")
}

func suiteEnsurePortStateLocked() {
	if suitePortState.loaded {
		return
	}
	suitePortState.loaded = true
	suitePortState.data = suitePortStateData{
		StorageProfiles: map[int][]suiteStorageProfile{},
		BuildClaims:     map[int][]suiteBuildClaim{},
		MapTools:        map[int]suiteMapToolSettings{},
		MapPolicy:       map[int][]string{},
		Library:         map[int][]suiteLibraryItem{},
		ImportGroups:    map[int][]suiteImportGroup{},
		History:         map[int][]suitePersistentHistory{},
		IssueReports:    map[int][]suiteIssueReport{},
	}
	data, err := os.ReadFile(suitePortStatePath())
	if err != nil || len(data) == 0 {
		return
	}
	var loaded suitePortStateData
	if json.Unmarshal(data, &loaded) != nil {
		return
	}
	if loaded.StorageProfiles == nil {
		loaded.StorageProfiles = map[int][]suiteStorageProfile{}
	}
	if loaded.BuildClaims == nil {
		loaded.BuildClaims = map[int][]suiteBuildClaim{}
	}
	if loaded.MapTools == nil {
		loaded.MapTools = map[int]suiteMapToolSettings{}
	}
	if loaded.MapPolicy == nil {
		loaded.MapPolicy = map[int][]string{}
	}
	if loaded.Library == nil {
		loaded.Library = map[int][]suiteLibraryItem{}
	}
	if loaded.ImportGroups == nil {
		loaded.ImportGroups = map[int][]suiteImportGroup{}
	}
	if loaded.History == nil {
		loaded.History = map[int][]suitePersistentHistory{}
	}
	if loaded.IssueReports == nil {
		loaded.IssueReports = map[int][]suiteIssueReport{}
	}
	suitePortState.data = loaded
}

func suiteSavePortStateLocked() error {
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(suitePortState.data, "", "  ")
	if err != nil {
		return err
	}
	path := suitePortStatePath()
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0600); err != nil {
		return err
	}
	_ = os.Remove(path)
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return err
	}
	return nil
}

func suiteLibraryDir() string {
	return filepath.Join(botDataDir, "toolbox-library")
}

func suiteLibraryArtifactPath(id string) string {
	id = strings.TrimSpace(id)
	if id == "" {
		return ""
	}
	id = regexp.MustCompile(`[^a-zA-Z0-9_-]+`).ReplaceAllString(id, "_")
	return filepath.Join(suiteLibraryDir(), id+".json.gz")
}

func suiteClonePayloadMap(in map[string]interface{}) map[string]interface{} {
	if in == nil {
		return nil
	}
	data, err := json.Marshal(in)
	if err != nil {
		out := make(map[string]interface{}, len(in))
		for k, v := range in {
			out[k] = v
		}
		return out
	}
	var out map[string]interface{}
	if json.Unmarshal(data, &out) != nil {
		return nil
	}
	return out
}

func suitePersistTaskHistory(t suiteTask) {
	entry := suitePersistentHistory{
		ID:          uuid.NewString(),
		BotID:       t.BotID,
		TaskID:      t.ID,
		ParentID:    t.ParentID,
		Kind:        t.Kind,
		Name:        t.Name,
		Status:      t.Status,
		Stage:       t.Stage,
		Message:     t.Message,
		Error:       t.Error,
		Outcome:     t.Outcome,
		NextAction:  t.NextAction,
		PayloadHash: t.PayloadHash,
		Attempt:     t.Attempt,
		AutoRetries: t.AutoRetries,
		SessionGen:  t.SessionGen,
		WaitingMS:   t.WaitingMS,
		ActiveMS:    t.ActiveMS,
		Progress:    t.Progress,
		Payload:     suiteClonePayloadMap(t.Payload),
		Checkpoint:  suiteClonePayloadMap(t.Checkpoint),
		CreatedAt:   t.CreatedAt,
		StartedAt:   t.StartedAt,
		CompletedAt: t.CompletedAt,
	}
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	list := suitePortState.data.History[t.BotID]
	for i := range list {
		if list[i].TaskID == t.ID && t.ID != "" {
			entry.ID = list[i].ID
			list[i] = entry
			suitePortState.data.History[t.BotID] = list
			suiteUpdateClaimUseStatusLocked(t.BotID, t.ID, t.Status)
			_ = suiteSavePortStateLocked()
			return
		}
	}
	list = append(list, entry)
	if len(list) > 500 {
		list = list[len(list)-500:]
	}
	suitePortState.data.History[t.BotID] = list
	suiteUpdateClaimUseStatusLocked(t.BotID, t.ID, t.Status)
	_ = suiteSavePortStateLocked()
}

func suiteFindLibraryItemLocked(botID int, itemID string) (*suiteLibraryItem, int) {
	list := suitePortState.data.Library[botID]
	for i := range list {
		if list[i].ID == itemID {
			cp := list[i]
			return &cp, i
		}
	}
	return nil, -1
}

func suiteSaveBlueprintArtifact(botID int, groupID, sourceName string, bp Blueprint) (suiteLibraryItem, error) {
	if len(bp.Cells) == 0 {
		return suiteLibraryItem{}, errors.New("藍圖沒有方塊")
	}
	if strings.TrimSpace(bp.Name) == "" {
		bp.Name = strings.TrimSuffix(filepath.Base(sourceName), filepath.Ext(sourceName))
	}
	if bp.Materials == nil || len(bp.Materials) == 0 {
		bp.Materials = MaterialTotalsCells(bp.Cells)
	}
	if bp.Width <= 0 || bp.Depth <= 0 {
		bp.Bounds = boundsForCells(bp.Cells)
		bp.Width = bp.Bounds.MaxX - bp.Bounds.MinX + 1
		bp.Depth = bp.Bounds.MaxZ - bp.Bounds.MinZ + 1
	}
	itemID := uuid.NewString()
	path := suiteLibraryArtifactPath(itemID)
	if path == "" {
		return suiteLibraryItem{}, errors.New("無法建立藍圖儲存路徑")
	}
	if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
		return suiteLibraryItem{}, err
	}
	data, err := json.Marshal(bp)
	if err != nil {
		return suiteLibraryItem{}, err
	}
	tmp := path + ".tmp"
	f, err := os.Create(tmp)
	if err != nil {
		return suiteLibraryItem{}, err
	}
	gz := gzip.NewWriter(f)
	_, writeErr := gz.Write(data)
	closeErr := gz.Close()
	fileCloseErr := f.Close()
	if writeErr != nil || closeErr != nil || fileCloseErr != nil {
		_ = os.Remove(tmp)
		if writeErr != nil {
			return suiteLibraryItem{}, writeErr
		}
		if closeErr != nil {
			return suiteLibraryItem{}, closeErr
		}
		return suiteLibraryItem{}, fileCloseErr
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return suiteLibraryItem{}, err
	}
	now := time.Now()
	item := suiteLibraryItem{
		ID:         itemID,
		BotID:      botID,
		GroupID:    groupID,
		Name:       bp.Name,
		SourceName: sourceName,
		Format:     bp.Format,
		Width:      bp.Width,
		Depth:      bp.Depth,
		BlockCount: len(bp.Cells),
		Materials:  cloneCountMap(bp.Materials),
		Artifact:   filepath.Base(path),
		CreatedAt:  now,
		UpdatedAt:  now,
	}
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	suitePortState.data.Library[botID] = append(suitePortState.data.Library[botID], item)
	err = suiteSavePortStateLocked()
	suitePortState.Unlock()
	if err != nil {
		_ = os.Remove(path)
		return suiteLibraryItem{}, err
	}
	return item, nil
}

func suiteLoadBlueprintArtifact(botID int, itemID string) (Blueprint, suiteLibraryItem, error) {
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	item, _ := suiteFindLibraryItemLocked(botID, itemID)
	suitePortState.Unlock()
	if item == nil {
		return Blueprint{}, suiteLibraryItem{}, errors.New("找不到地圖/藍圖項目")
	}
	path := filepath.Join(suiteLibraryDir(), item.Artifact)
	f, err := os.Open(path)
	if err != nil {
		return Blueprint{}, *item, err
	}
	defer f.Close()
	gz, err := gzip.NewReader(f)
	if err != nil {
		return Blueprint{}, *item, err
	}
	defer gz.Close()
	data, err := io.ReadAll(io.LimitReader(gz, 128<<20))
	if err != nil {
		return Blueprint{}, *item, err
	}
	var bp Blueprint
	if err := json.Unmarshal(data, &bp); err != nil {
		return Blueprint{}, *item, err
	}
	if len(bp.Cells) == 0 {
		return Blueprint{}, *item, errors.New("藍圖內容為空")
	}
	return bp, *item, nil
}

func suiteTaskReferencesLibraryItemV117(botID int, itemID string) bool {
	itemID = strings.TrimSpace(itemID)
	if itemID == "" {
		return false
	}
	bedrockSuiteTasks.mu.Lock()
	defer bedrockSuiteTasks.mu.Unlock()
	check := func(t *suiteTask) bool {
		if t == nil || t.BotID != botID || t.Payload == nil {
			return false
		}
		return strings.TrimSpace(suitePayloadString(t.Payload, "library_id", "")) == itemID
	}
	for _, t := range bedrockSuiteTasks.queues[botID] {
		if !suiteTaskTerminalStatus(t.Status) && check(t) {
			return true
		}
	}
	for _, t := range bedrockSuiteTasks.history[botID] {
		if check(t) {
			return true
		}
	}
	return false
}

func suiteLibraryItemReferencedLockedV117(botID int, itemID string) bool {
	for _, group := range suitePortState.data.ImportGroups[botID] {
		for _, id := range group.ItemIDs {
			if id == itemID {
				return true
			}
		}
	}
	for _, h := range suitePortState.data.History[botID] {
		if strings.TrimSpace(suitePayloadString(h.Payload, "library_id", "")) == itemID {
			return true
		}
	}
	return false
}

func suiteCleanupUnusedStorageV117(botID int) map[string]int {
	activeRefs := map[string]bool{}
	bedrockSuiteTasks.mu.Lock()
	for _, t := range bedrockSuiteTasks.queues[botID] {
		if t != nil && !suiteTaskTerminalStatus(t.Status) {
			if id := strings.TrimSpace(suitePayloadString(t.Payload, "library_id", "")); id != "" {
				activeRefs[id] = true
			}
		}
	}
	bedrockSuiteTasks.mu.Unlock()

	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	for _, group := range suitePortState.data.ImportGroups[botID] {
		for _, id := range group.ItemIDs {
			activeRefs[id] = true
		}
	}
	for _, h := range suitePortState.data.History[botID] {
		if id := strings.TrimSpace(suitePayloadString(h.Payload, "library_id", "")); id != "" {
			activeRefs[id] = true
		}
	}
	knownArtifacts := map[string]bool{}
	for _, item := range suitePortState.data.Library[botID] {
		if item.Artifact != "" {
			knownArtifacts[item.Artifact] = true
		}
	}
	suitePortState.Unlock()

	removedArtifacts := 0
	entries, _ := os.ReadDir(suiteLibraryDir())
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !knownArtifacts[name] {
			if os.Remove(filepath.Join(suiteLibraryDir(), name)) == nil {
				removedArtifacts++
			}
		}
	}
	return map[string]int{
		"removed_artifacts":  removedArtifacts,
		"removed_item_icons": cleanupItemIconCache(30 * 24 * time.Hour),
		"active_refs":        len(activeRefs),
	}
}

func suiteDeleteLibraryItem(botID int, itemID string) bool {
	if suiteTaskReferencesLibraryItemV117(botID, itemID) {
		return false
	}
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	list := suitePortState.data.Library[botID]
	next := list[:0]
	artifact := ""
	found := false
	for _, item := range list {
		if item.ID == itemID {
			artifact = item.Artifact
			found = true
			continue
		}
		next = append(next, item)
	}
	if !found {
		return false
	}
	if suiteLibraryItemReferencedLockedV117(botID, itemID) {
		return false
	}
	suitePortState.data.Library[botID] = next
	for gi := range suitePortState.data.ImportGroups[botID] {
		ids := suitePortState.data.ImportGroups[botID][gi].ItemIDs[:0]
		for _, id := range suitePortState.data.ImportGroups[botID][gi].ItemIDs {
			if id != itemID {
				ids = append(ids, id)
			}
		}
		suitePortState.data.ImportGroups[botID][gi].ItemIDs = ids
	}
	_ = suiteSavePortStateLocked()
	if artifact != "" {
		_ = os.Remove(filepath.Join(suiteLibraryDir(), artifact))
	}
	return true
}

func suiteLibrarySnapshot(botID int) map[string]interface{} {
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	library := append([]suiteLibraryItem(nil), suitePortState.data.Library[botID]...)
	groups := append([]suiteImportGroup(nil), suitePortState.data.ImportGroups[botID]...)
	history := append([]suitePersistentHistory(nil), suitePortState.data.History[botID]...)
	return map[string]interface{}{
		"ok":            true,
		"library":       library,
		"import_groups": groups,
		"history":       history,
	}
}

func suiteStoreImportGroup(botID int, name, source string, itemIDs []string) (suiteImportGroup, error) {
	g := suiteImportGroup{
		ID:        uuid.NewString(),
		BotID:     botID,
		Name:      strings.TrimSpace(name),
		Source:    strings.TrimSpace(source),
		ItemIDs:   append([]string(nil), itemIDs...),
		CreatedAt: time.Now(),
		UpdatedAt: time.Now(),
	}
	if g.Name == "" {
		g.Name = "匯入 " + g.CreatedAt.Format("2006-01-02 15:04")
	}
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	suitePortState.data.ImportGroups[botID] = append(suitePortState.data.ImportGroups[botID], g)
	if err := suiteSavePortStateLocked(); err != nil {
		return suiteImportGroup{}, err
	}
	return g, nil
}

// suiteAuthoritativePositionV139 is the coordinate source used by App/toolbox
// displays. The real server MovePlayer position wins whenever available; only
// before the first server position exists do we fall back to reconciled local.
func suiteAuthoritativePositionV139(bot *BotSession) ([3]float32, bool, string) {
	if bot == nil {
		return [3]float32{}, false, "none"
	}
	bot.mu.Lock()
	defer bot.mu.Unlock()
	if bot.HasServerPlayerPos && bot.LastServerPlayerPos != ([3]float32{}) {
		return bot.LastServerPlayerPos, true, "server"
	}
	if bot.HasPlayerPos && bot.LastPlayerPos != ([3]float32{}) {
		return bot.LastPlayerPos, true, "reconciled_local"
	}
	return [3]float32{}, false, "none"
}

func suiteCurrentPosition(bot *BotSession) (Vec3i, string, error) {
	if bot == nil {
		return Vec3i{}, "", errors.New("找不到 BOT")
	}
	pos, ok, _ := suiteAuthoritativePositionV139(bot)
	bot.mu.Lock()
	serverAddr := bot.ServerAddr
	bot.mu.Unlock()
	if !ok {
		return Vec3i{}, serverAddr, errors.New("尚未取得 BOT 位置")
	}
	return Vec3i{
		X: int(math.Floor(float64(pos[0]))),
		Y: int(math.Floor(float64(pos[1]))),
		Z: int(math.Floor(float64(pos[2]))),
	}, serverAddr, nil
}

func suiteParseWorldBlockKey(key string) (Vec3i, bool) {
	if split := strings.IndexByte(key, '|'); split >= 0 {
		key = key[split+1:]
	}
	parts := strings.Split(key, ",")
	if len(parts) != 3 {
		return Vec3i{}, false
	}
	x, ex := strconv.Atoi(parts[0])
	y, ey := strconv.Atoi(parts[1])
	z, ez := strconv.Atoi(parts[2])
	if ex != nil || ey != nil || ez != nil {
		return Vec3i{}, false
	}
	return Vec3i{X: x, Y: y, Z: z}, true
}

func suiteParseDimensionWorldBlockKey(key string) (int32, Vec3i, bool) {
	if split := strings.IndexByte(key, '|'); split >= 0 {
		dimension, err := strconv.ParseInt(key[:split], 10, 32)
		if err != nil {
			return 0, Vec3i{}, false
		}
		pos, ok := suiteParseWorldBlockKey(key[split+1:])
		return int32(dimension), pos, ok
	}
	pos, ok := suiteParseWorldBlockKey(key)
	return 0, pos, ok
}

const suiteStorageFloorToleranceV116 = 2

func suiteStorageSameFloorV116(y, anchorY int) bool {
	d := y - anchorY
	if d < 0 {
		d = -d
	}
	return d <= suiteStorageFloorToleranceV116
}

func suiteScanNearbyContainers(bot *BotSession, maxDistance int, seedBoxes ...suiteStorageBox) []map[string]interface{} {
	if bot == nil {
		return nil
	}
	if maxDistance < 2 {
		maxDistance = 16
	}
	if maxDistance > 96 {
		maxDistance = 96
	}
	bot.mu.Lock()
	player := bot.LastPlayerPos
	hasPlayer := bot.HasPlayerPos
	dimension := bot.MapArtCurrentDimension
	dimensionKnown := bot.MapArtDimensionKnown
	world := make(map[string]uint32, len(bot.MapArtWorldBlocks))
	for k, v := range bot.MapArtWorldBlocks {
		world[k] = v
	}
	hints := make(map[string]string, len(bot.MapArtContainerHints))
	for k, v := range bot.MapArtContainerHints {
		hints[k] = v
	}
	names := make(map[uint32]string, len(bot.MapArtBlockNames))
	for k, v := range bot.MapArtBlockNames {
		names[k] = v
	}
	chunks := make([]*mapArtChunkSnapshot, 0, len(bot.MapArtChunks))
	for _, snapshot := range bot.MapArtChunks {
		chunks = append(chunks, snapshot)
	}
	bot.mu.Unlock()
	if !hasPlayer || !dimensionKnown {
		return nil
	}
	// V116: automatic warehouse discovery is floor-scoped. The previous 3D
	// radius search mixed upstairs/downstairs containers into one station, so the
	// Bot could fly to a visually unrelated floor while scanning/refilling.
	scanFloorY := int(math.Floor(float64(player[1])))

	type candidate struct {
		pos  Vec3i
		name string
		dist float64
	}
	containerRuntimeIDs := make(map[uint32]bool)
	for runtimeID, rawName := range names {
		name := strings.ToLower(strings.TrimSpace(rawName))
		if strings.Contains(name, "chest") || strings.Contains(name, "barrel") || strings.Contains(name, "shulker_box") {
			containerRuntimeIDs[runtimeID] = true
		}
	}

	// Geyser/Java-backed servers can expose a usable block RuntimeID while the
	// runtime palette name itself is missing or generic. Learn the container
	// RuntimeID from any authoritative BlockActor/ContainerOpen hint we already
	// received, and from previously verified warehouse boxes supplied by a
	// discovery re-scan. Once learned, the normal LevelChunk sweep can find other
	// chests of the same kind on the BOT's CURRENT floor without falling back to
	// the upstairs/downstairs hint positions themselves.
	runtimeIDAtCopied := func(pos Vec3i) (uint32, bool) {
		if runtimeID, ok := world[mapArtDimensionBlockKey(dimension, pos)]; ok {
			return runtimeID, true
		}
		for _, snapshot := range chunks {
			if snapshot == nil || snapshot.dimension != dimension {
				continue
			}
			if runtimeID, ok := snapshot.runtimeIDAt(pos); ok {
				return runtimeID, true
			}
		}
		return 0, false
	}
	for key := range hints {
		keyDimension, pos, ok := suiteParseDimensionWorldBlockKey(key)
		if !ok || keyDimension != dimension {
			continue
		}
		if runtimeID, ok := runtimeIDAtCopied(pos); ok {
			containerRuntimeIDs[runtimeID] = true
		}
	}
	for _, box := range seedBoxes {
		if !box.Enabled {
			continue
		}
		if runtimeID, ok := runtimeIDAtCopied(box.Position); ok {
			containerRuntimeIDs[runtimeID] = true
		}
	}

	foundByPosition := make(map[Vec3i]candidate)
	addCandidate := func(pos Vec3i, runtimeID uint32) {
		if !containerRuntimeIDs[runtimeID] {
			return
		}
		if !suiteStorageSameFloorV116(pos.Y, scanFloorY) {
			return
		}
		dx := float64(pos.X) - float64(player[0])
		dy := float64(pos.Y) - float64(player[1])
		dz := float64(pos.Z) - float64(player[2])
		dist := math.Sqrt(dx*dx + dy*dy + dz*dz)
		if dist > float64(maxDistance) {
			return
		}
		foundByPosition[pos] = candidate{pos: pos, name: strings.ToLower(strings.TrimSpace(names[runtimeID])), dist: dist}
	}

	// Prefer explicit block-actor/container-open hints. They survive servers where
	// the runtime block-name palette is incomplete, which previously made a chest
	// directly beside the Bot show up as "找到 0 個容器".
	for key, rawName := range hints {
		keyDimension, pos, ok := suiteParseDimensionWorldBlockKey(key)
		if !ok || keyDimension != dimension {
			continue
		}
		if !suiteStorageSameFloorV116(pos.Y, scanFloorY) {
			continue
		}
		dx := float64(pos.X) - float64(player[0])
		dy := float64(pos.Y) - float64(player[1])
		dz := float64(pos.Z) - float64(player[2])
		dist := math.Sqrt(dx*dx + dy*dy + dz*dz)
		if dist > float64(maxDistance) {
			continue
		}
		name := strings.ToLower(strings.TrimSpace(rawName))
		if name == "" {
			name = "minecraft:container"
		}
		foundByPosition[pos] = candidate{pos: pos, name: name, dist: dist}
	}

	// Full LevelChunk snapshots contain ordinary pre-existing containers. The
	// sparse MapArtWorldBlocks map only contains later UpdateBlock packets, so
	// scanning only that map missed almost every chest on a normally loaded map.
	minX, maxX := int(math.Floor(float64(player[0])))-maxDistance, int(math.Floor(float64(player[0])))+maxDistance
	minY, maxY := scanFloorY-suiteStorageFloorToleranceV116, scanFloorY+suiteStorageFloorToleranceV116
	minZ, maxZ := int(math.Floor(float64(player[2])))-maxDistance, int(math.Floor(float64(player[2])))+maxDistance
	for _, snapshot := range chunks {
		if snapshot == nil || snapshot.dimension != dimension || snapshot.chunkX*16 > maxX || snapshot.chunkX*16+15 < minX || snapshot.chunkZ*16 > maxZ || snapshot.chunkZ*16+15 < minZ {
			continue
		}
		for subY, storage := range snapshot.sub {
			worldY := subY * 16
			if worldY > maxY || worldY+15 < minY {
				continue
			}
			paletteHasContainer := false
			for _, runtimeID := range storage.palette {
				if containerRuntimeIDs[runtimeID] {
					paletteHasContainer = true
					break
				}
			}
			if !paletteHasContainer {
				continue
			}
			for localX := 0; localX < 16; localX++ {
				worldX := snapshot.chunkX*16 + localX
				if worldX < minX || worldX > maxX {
					continue
				}
				for localZ := 0; localZ < 16; localZ++ {
					worldZ := snapshot.chunkZ*16 + localZ
					if worldZ < minZ || worldZ > maxZ {
						continue
					}
					for localY := 0; localY < 16; localY++ {
						pos := Vec3i{X: worldX, Y: worldY + localY, Z: worldZ}
						if pos.Y < minY || pos.Y > maxY {
							continue
						}
						runtimeID, ok := storage.runtimeID(localX, localY, localZ)
						if ok {
							addCandidate(pos, runtimeID)
						}
					}
				}
			}
		}
	}

	// Merge UpdateBlock overrides after the chunk snapshot so removals/placements
	// seen after LevelChunk win and dimension-prefixed keys are handled correctly.
	for key, runtimeID := range world {
		keyDimension, pos, ok := suiteParseDimensionWorldBlockKey(key)
		if !ok || keyDimension != dimension {
			continue
		}
		if !containerRuntimeIDs[runtimeID] {
			delete(foundByPosition, pos)
			continue
		}
		addCandidate(pos, runtimeID)
	}
	found := make([]candidate, 0, len(foundByPosition))
	for _, c := range foundByPosition {
		found = append(found, c)
	}
	sort.Slice(found, func(i, j int) bool {
		if found[i].dist != found[j].dist {
			return found[i].dist < found[j].dist
		}
		if found[i].pos.Y != found[j].pos.Y {
			return found[i].pos.Y < found[j].pos.Y
		}
		if found[i].pos.Z != found[j].pos.Z {
			return found[i].pos.Z < found[j].pos.Z
		}
		return found[i].pos.X < found[j].pos.X
	})
	if len(found) > 80 {
		found = found[:80]
	}
	out := make([]map[string]interface{}, 0, len(found))
	for _, c := range found {
		out = append(out, map[string]interface{}{"position": c.pos, "block": c.name, "distance": math.Round(c.dist*10) / 10})
	}
	return out
}

// suiteContainerBlockAt returns the currently known container block at pos.
// It intentionally validates against the live Bedrock world cache so a stale
// UI coordinate cannot be persisted as a material box.
func suiteContainerBlockAt(bot *BotSession, pos Vec3i) (string, bool) {
	if bot == nil {
		return "", false
	}
	bot.mu.Lock()
	dimension := bot.MapArtCurrentDimension
	hint := strings.ToLower(strings.TrimSpace(bot.MapArtContainerHints[mapArtDimensionBlockKey(dimension, pos)]))
	bot.mu.Unlock()
	if hint != "" {
		return hint, true
	}
	runtimeID, ok := bot.mapArtWorldRuntimeID(pos)
	if !ok {
		return "", false
	}
	bot.mu.Lock()
	name := strings.ToLower(strings.TrimSpace(bot.MapArtBlockNames[runtimeID]))
	bot.mu.Unlock()
	if strings.Contains(name, "chest") || strings.Contains(name, "barrel") || strings.Contains(name, "shulker_box") {
		return name, true
	}
	return name, false
}

// suiteScanFacingContainer picks the container that is actually in front of the
// Bot's current camera. The old toolbox "scan" returned every cached container
// in a large radius, which made the first result look unrelated to the box the
// user was facing. This is a discovery-only helper: it never moves the Bot.
func suiteScanFacingContainer(bot *BotSession, maxDistance int) (map[string]interface{}, bool) {
	if bot == nil {
		return nil, false
	}
	if maxDistance < 2 {
		maxDistance = 8
	}
	if maxDistance > 16 {
		maxDistance = 16
	}
	rows := suiteScanNearbyContainers(bot, maxDistance)
	if len(rows) == 0 {
		return nil, false
	}

	bot.mu.Lock()
	player := bot.LastPlayerPos
	hasPlayer := bot.HasPlayerPos
	yaw := bot.LastPlayerYaw
	pitch := bot.LastPlayerPitch
	bot.mu.Unlock()
	if !hasPlayer {
		return nil, false
	}

	yawRad := float64(yaw) * math.Pi / 180
	pitchRad := float64(pitch) * math.Pi / 180
	cosPitch := math.Cos(pitchRad)
	forwardX := -math.Sin(yawRad) * cosPitch
	forwardY := -math.Sin(pitchRad)
	forwardZ := math.Cos(yawRad) * cosPitch

	type scored struct {
		row   map[string]interface{}
		score float64
	}
	strict := make([]scored, 0, len(rows))
	fallback := make([]scored, 0, len(rows))
	for _, row := range rows {
		pos, ok := row["position"].(Vec3i)
		if !ok {
			continue
		}
		dx := float64(pos.X) + 0.5 - float64(player[0])
		dy := float64(pos.Y) + 0.5 - float64(player[1])
		dz := float64(pos.Z) + 0.5 - float64(player[2])
		dist := math.Sqrt(dx*dx + dy*dy + dz*dz)
		if dist <= 0.001 || dist > float64(maxDistance)+1.0 {
			continue
		}
		along := dx*forwardX + dy*forwardY + dz*forwardZ
		if along <= 0 {
			continue
		}
		perpSq := dist*dist - along*along
		if perpSq < 0 {
			perpSq = 0
		}
		perp := math.Sqrt(perpSq)
		// Crosshair-like preference: roughly one block around the camera ray.
		// The allowance grows slightly with distance so looking at a chest face is
		// still accepted even if the cached player pitch is one frame behind.
		if perp <= 1.05+along*0.08 {
			strict = append(strict, scored{row: row, score: perp*4 + along*0.04})
		}
		// Forgiving front-cone fallback for third-person/camera timing differences.
		dot := along / dist
		if dot >= 0.55 {
			fallback = append(fallback, scored{row: row, score: (1-dot)*8 + dist*0.08})
		}
	}
	pick := strict
	if len(pick) == 0 {
		pick = fallback
	}
	if len(pick) == 0 {
		return nil, false
	}
	sort.SliceStable(pick, func(i, j int) bool { return pick[i].score < pick[j].score })
	return pick[0].row, true
}

// suiteScanStorageBoxAtControlled opens exactly one requested box, reads its
// contents and closes it. The caller owns the Bedrock action lease.
func suiteScanStorageBoxAtControlled(ctx context.Context, bot *BotSession, pos Vec3i) (suiteStorageBox, error) {
	box := suiteStorageBox{Position: pos, Enabled: true, Materials: map[string]int{}}
	if name, ok := suiteContainerBlockAt(bot, pos); !ok {
		if name == "" {
			box.LastError = "箱子所在區塊尚未載入"
		} else {
			box.LastError = "該座標不是箱子/木桶/界伏盒：" + name
		}
		return box, errors.New(box.LastError)
	}
	boxCtx, cancel := context.WithTimeout(ctx, 6500*time.Millisecond)
	err := bedrockOpenContainerAtControlled(boxCtx, bot, pos)
	cancel()
	if err != nil {
		// An interrupted/failed open may leave the server-side container window
		// half-open. Always force a close before the scan advances, otherwise the
		// next box can inherit stale container state and keep the BOT control lease
		// occupied until the whole HTTP request times out.
		_ = bedrockCloseContainerControlled(bot)
		box.LastError = err.Error()
		return box, err
	}

	bot.mu.Lock()
	for _, item := range bot.MapArtContainerItems {
		if item.Stack.Count == 0 {
			continue
		}
		name := bedrockItemIdentityLocked(bot, item)
		if name == "" {
			name = fmt.Sprintf("network:%d", item.Stack.NetworkID)
		}
		box.Materials[name] += int(item.Stack.Count)
	}
	bot.mu.Unlock()
	box.VerifiedAt = time.Now()
	box.LastError = ""
	_ = bedrockCloseContainerControlled(bot)
	select {
	case <-ctx.Done():
		return box, ctx.Err()
	case <-time.After(45 * time.Millisecond):
	}
	return box, nil
}

func suiteParseVec3Lines(raw string) []Vec3i {
	out := []Vec3i{}
	seen := map[Vec3i]bool{}
	raw = strings.ReplaceAll(raw, "\r", "")
	for _, line := range strings.Split(raw, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		parts := strings.FieldsFunc(line, func(r rune) bool { return r == ',' || r == ' ' || r == ';' || r == '\t' })
		if len(parts) < 3 {
			continue
		}
		x, e1 := strconv.Atoi(parts[0])
		y, e2 := strconv.Atoi(parts[1])
		z, e3 := strconv.Atoi(parts[2])
		if e1 != nil || e2 != nil || e3 != nil {
			continue
		}
		v := Vec3i{X: x, Y: y, Z: z}
		if !seen[v] {
			seen[v] = true
			out = append(out, v)
		}
	}
	return out
}

// suiteStorageScanOptimiseCandidatesV116 orders the already floor-filtered
// container candidates by a nearest-neighbour route. Explicit pinned/offset boxes
// may still cross floors, but automatic discovery never mixes warehouse levels.
func suiteStorageScanOptimiseCandidatesV113(bot *BotSession, rows []map[string]interface{}, scanMode string) []map[string]interface{} {
	if bot == nil || len(rows) == 0 {
		return rows
	}
	bot.mu.Lock()
	player := bot.LastPlayerPos
	hasPlayer := bot.HasPlayerPos
	bot.mu.Unlock()
	if !hasPlayer {
		return rows
	}

	type candidate struct {
		row map[string]interface{}
		pos Vec3i
	}
	valid := make([]candidate, 0, len(rows))
	invalid := make([]map[string]interface{}, 0)
	for _, row := range rows {
		pos, ok := row["position"].(Vec3i)
		if !ok {
			invalid = append(invalid, row)
			continue
		}
		valid = append(valid, candidate{row: row, pos: pos})
	}
	if len(valid) == 0 {
		return rows
	}

	out := make([]map[string]interface{}, 0, len(valid)+len(invalid))
	curX, curY, curZ := float64(player[0]), float64(player[1]), float64(player[2])
	remaining := append([]candidate(nil), valid...)
	for len(remaining) > 0 {
		best := 0
		bestScore := math.MaxFloat64
		for i, c := range remaining {
			dx := float64(c.pos.X) - curX
			dy := float64(c.pos.Y) - curY
			dz := float64(c.pos.Z) - curZ
			// Vertical travel is usually much more expensive in warehouse interiors.
			score := dx*dx + dz*dz + dy*dy*2.5
			if score < bestScore {
				best, bestScore = i, score
			}
		}
		chosen := remaining[best]
		out = append(out, chosen.row)
		curX, curY, curZ = float64(chosen.pos.X), float64(chosen.pos.Y), float64(chosen.pos.Z)
		remaining = append(remaining[:best], remaining[best+1:]...)
	}
	out = append(out, invalid...)
	return out
}

func suiteScanStorageProfile(ctx context.Context, bot *BotSession, profile suiteStorageProfile, seedBoxes ...suiteStorageBox) (suiteStorageProfile, error) {
	// A warehouse travel task may have been started immediately before the scan.
	// Warehouse/manual movement now uses the same flight engine, so do not fail the
	// whole scan merely because that final flight still owns the manual lease for a
	// moment. Wait for movement to release naturally; never steal control from an
	// unrelated interaction/build task.
	var release func()
	var err error
	waitUntil := time.Now().Add(30 * time.Second)
	for {
		release, err = beginBedrockAction(bot, "掃描材料箱")
		if err == nil {
			break
		}
		bot.mu.Lock()
		owner := bedrockCurrentControlOwnerLocked(bot)
		legacyBusy, legacyWhy := bedrockLegacyAutomationBusyLocked(bot)
		kind := strings.TrimSpace(bot.BedrockActionKind)
		bot.mu.Unlock()
		if time.Now().After(waitUntil) {
			return profile, err
		}
		waitingFor := bedrockControlOwnerLabel(owner)
		if kind != "" {
			waitingFor = kind
		}
		if owner == "" && legacyBusy {
			waitingFor = legacyWhy
		}
		if owner == "" && !legacyBusy {
			waitingFor = "目前操作"
		}
		suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
			state.Message = "等待「" + waitingFor + "」釋放 BOT 後開始掃描材料箱…"
		})
		select {
		case <-ctx.Done():
			return profile, ctx.Err()
		case <-time.After(80 * time.Millisecond):
		}
	}
	defer release()

	// The UI request may stay alive for several minutes. Keep the exclusive BOT
	// control lease bounded so a bad/unreachable chest can never leave later
	// warehouse/build tasks stuck at "等待資源" for the full request lifetime.
	scanCtx, scanCancel := context.WithTimeout(ctx, 150*time.Second)
	defer scanCancel()
	if err := waitMapArtRuntimePreflight(scanCtx, bot, 20*time.Second); err != nil {
		return profile, err
	}
	if profile.ScanRange <= 0 {
		profile.ScanRange = 24
	}
	if strings.TrimSpace(profile.ScanMode) == "" {
		profile.ScanMode = "nearby_containers"
	}

	// V116: preserve explicit box intent across every re-scan. A scan result is a
	// fresh suiteStorageBox value, so without this map manually pinned boxes silently
	// became ordinary auto-discovered boxes after the first refresh.
	pinnedPositions := map[Vec3i]bool{}
	for _, box := range profile.Boxes {
		if box.Pinned {
			pinnedPositions[box.Position] = true
		}
	}
	for _, box := range seedBoxes {
		if box.Pinned {
			pinnedPositions[box.Position] = true
		}
	}

	// Once the user has explicitly added material boxes, those coordinates are the
	// profile's source of truth. Re-scanning a profile must not suddenly replace
	// them with unrelated containers from a 24-block radius around the Bot.
	containers := make([]map[string]interface{}, 0)
	if len(profile.Boxes) > 0 {
		for _, box := range profile.Boxes {
			if !box.Enabled {
				continue
			}
			// Old automatic scans may already contain boxes from another floor. Keep
			// manually pinned boxes, but drop old automatic cross-floor entries.
			if !box.Pinned && !suiteStorageSameFloorV116(box.Position.Y, profile.Position.Y) {
				continue
			}
			containers = append(containers, map[string]interface{}{
				"position": box.Position,
				"block":    "saved_box",
				"distance": 0,
			})
		}
	} else {
		containers = suiteScanNearbyContainers(bot, profile.ScanRange, seedBoxes...)
		// Explicit pinned boxes are intentionally allowed outside the automatic floor
		// band. Merge them back after same-floor discovery, without duplicating a box
		// that was already found automatically.
		seenPos := map[Vec3i]bool{}
		for _, row := range containers {
			if pos, ok := row["position"].(Vec3i); ok {
				seenPos[pos] = true
			}
		}
		for _, box := range seedBoxes {
			if !box.Enabled || !box.Pinned || seenPos[box.Position] {
				continue
			}
			containers = append(containers, map[string]interface{}{
				"position": box.Position,
				"block":    "pinned_box",
				"distance": 0,
			})
			seenPos[box.Position] = true
		}
		switch strings.ToLower(strings.TrimSpace(profile.ScanMode)) {
		case "reachable_boxes":
			filtered := containers[:0]
			for _, row := range containers {
				name := strings.ToLower(strings.TrimSpace(fmt.Sprint(row["block"])))
				if strings.Contains(name, "shulker") {
					filtered = append(filtered, row)
				}
			}
			containers = filtered
		case "offset":
			containers = nil
			for _, off := range profile.Offsets {
				pos := Vec3i{X: profile.Position.X + off.X, Y: profile.Position.Y + off.Y, Z: profile.Position.Z + off.Z}
				containers = append(containers, map[string]interface{}{"position": pos, "block": "offset", "distance": 0})
			}
		}
	}

	containers = suiteStorageScanOptimiseCandidatesV113(bot, containers, profile.ScanMode)
	limit := minInt(len(containers), 48)
	suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
		state.Found = limit
		state.Current = 0
		state.Opened = 0
		state.Failed = 0
		state.Message = fmt.Sprintf("已找到 %d 個容器，準備逐箱掃描", limit)
		state.Error = ""
	})
	boxes := make([]suiteStorageBox, 0, limit)
	opened, failed := 0, 0
	for i, row := range containers {
		if i >= 48 {
			break
		}
		if scanCtx.Err() != nil {
			// Keep the successful partial scan, count the remaining candidates as
			// failed, and return normally so defer release() immediately frees the
			// BOT for queued warehouse/build work.
			failed += maxInt(0, limit-i)
			break
		}
		pos, ok := row["position"].(Vec3i)
		if !ok {
			failed++
			suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
				state.Current = i + 1
				state.Failed = failed
				state.Message = fmt.Sprintf("正在掃描第 %d / %d 個容器", minInt(i+1, limit), limit)
				state.CurrentPos = nil
			})
			continue
		}
		posCopy := pos
		suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
			state.Current = i + 1
			state.Opened = opened
			state.Failed = failed
			state.CurrentPos = &posCopy
			state.Message = fmt.Sprintf("正在開啟第 %d / %d 個容器：%d,%d,%d", minInt(i+1, limit), limit, pos.X, pos.Y, pos.Z)
		})
		box, scanErr := suiteScanStorageBoxAtControlled(scanCtx, bot, pos)
		box.Pinned = pinnedPositions[pos]
		if scanErr != nil {
			failed++
			boxes = append(boxes, box)
			// Make absolutely sure a failed container interaction cannot leak an
			// open window into the next candidate.
			_ = bedrockCloseContainerControlled(bot)
			suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
				state.Opened = opened
				state.Failed = failed
				state.Message = fmt.Sprintf("第 %d / %d 個容器失敗，繼續下一個", minInt(i+1, limit), limit)
			})
			continue
		}
		opened++
		boxes = append(boxes, box)
		// V116: profile.Position is the warehouse anchor/return coordinate. Do not
		// silently rewrite it to whichever chest happened to open first; refill uses
		// the per-box positions below and keeping the anchor stable prevents floor drift.
		suiteStorageScanSet(profile.BotID, func(state *suiteStorageScanState) {
			state.Opened = opened
			state.Failed = failed
			state.Message = fmt.Sprintf("已完成 %d / %d 個容器", minInt(i+1, limit), limit)
		})
	}
	profile.Boxes = boxes
	profile.ScannedAt = time.Now()
	profile.LastScanFound = limit
	profile.LastScanOpened = opened
	profile.LastScanFailed = failed
	profile.UpdatedAt = time.Now()
	profile.Revision++
	return profile, nil
}

func suiteFindStorageLocked(botID int, id string) (int, *suiteStorageProfile) {
	list := suitePortState.data.StorageProfiles[botID]
	for i := range list {
		if list[i].ID == id {
			return i, &list[i]
		}
	}
	return -1, nil
}

func suiteReserveClaimSlot(botID int, claimID, taskID, tileName string, tileWidth, tileDepth int) (Vec3i, int, error) {
	if strings.TrimSpace(claimID) == "" {
		return Vec3i{}, -1, errors.New("claim id is empty")
	}
	if tileWidth <= 0 {
		tileWidth = 128
	}
	if tileDepth <= 0 {
		tileDepth = 128
	}
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	list := suitePortState.data.BuildClaims[botID]
	idx := -1
	for i := range list {
		if list[i].ID == claimID {
			idx = i
			break
		}
	}
	if idx < 0 {
		return Vec3i{}, -1, errors.New("找不到領地")
	}
	claim := list[idx]
	area := NormaliseArea(Area{From: claim.From, To: claim.To})
	cols := maxInt(1, area.Width()/maxInt(1, tileWidth))
	rows := maxInt(1, area.Depth()/maxInt(1, tileDepth))
	total := cols * rows
	claim.Slots = total
	used := map[int]bool{}
	for _, u := range claim.Uses {
		if u.Status != "completed" && u.Status != "error" && u.Status != "cancelled" {
			used[u.Slot] = true
		}
	}
	slot := -1
	for i := 0; i < total; i++ {
		if !used[i] {
			slot = i
			break
		}
	}
	if slot < 0 {
		return Vec3i{}, -1, errors.New("領地沒有可用施工槽位")
	}
	start := Vec3i{X: area.From.X + (slot%cols)*tileWidth, Y: area.From.Y, Z: area.From.Z + (slot/cols)*tileDepth}
	claim.Uses = append(claim.Uses, suiteClaimUse{Slot: slot, Start: start, TaskID: taskID, TileName: tileName, Status: "queued", UpdatedAt: time.Now()})
	claim.UpdatedAt = time.Now()
	list[idx] = claim
	suitePortState.data.BuildClaims[botID] = list
	if err := suiteSavePortStateLocked(); err != nil {
		return Vec3i{}, -1, err
	}
	return start, slot, nil
}

func suiteAttachClaimTask(botID int, claimID string, slot int, taskID string) {
	if claimID == "" || slot < 0 || taskID == "" {
		return
	}
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	claims := suitePortState.data.BuildClaims[botID]
	for i := range claims {
		if claims[i].ID != claimID {
			continue
		}
		for j := len(claims[i].Uses) - 1; j >= 0; j-- {
			if claims[i].Uses[j].Slot == slot && claims[i].Uses[j].TaskID == "" {
				claims[i].Uses[j].TaskID = taskID
				claims[i].Uses[j].UpdatedAt = time.Now()
				claims[i].UpdatedAt = time.Now()
				suitePortState.data.BuildClaims[botID] = claims
				_ = suiteSavePortStateLocked()
				return
			}
		}
	}
}

func suiteUpdateClaimUseStatusLocked(botID int, taskID, status string) {
	if taskID == "" {
		return
	}
	claims := suitePortState.data.BuildClaims[botID]
	changed := false
	for i := range claims {
		for j := range claims[i].Uses {
			if claims[i].Uses[j].TaskID == taskID {
				claims[i].Uses[j].Status = status
				claims[i].Uses[j].UpdatedAt = time.Now()
				changed = true
			}
		}
		if changed {
			claims[i].UpdatedAt = time.Now()
		}
	}
	if changed {
		suitePortState.data.BuildClaims[botID] = claims
	}
}

func suiteFindClaimLocked(botID int, id string) (int, *suiteBuildClaim) {
	list := suitePortState.data.BuildClaims[botID]
	for i := range list {
		if list[i].ID == id {
			return i, &list[i]
		}
	}
	return -1, nil
}

func suiteDefaultMapToolSettings(in suiteMapToolSettings) suiteMapToolSettings {
	if in.CommandDelay <= 0 {
		in.CommandDelay = 350
	}
	if strings.TrimSpace(in.DrawMapHome) == "" {
		in.DrawMapHome = "drawmap"
	}
	if in.DrawMapStart.Y == 0 {
		in.DrawMapStart.Y = 64
	}
	if strings.TrimSpace(in.BlankMapMarker) == "" {
		in.BlankMapMarker = "minecraft:cartography_table"
	}
	if strings.TrimSpace(in.RenameExperienceStrategy) == "" {
		in.RenameExperienceStrategy = "wait"
	}
	if strings.TrimSpace(in.StorageMode) == "" {
		in.StorageMode = "warp"
	}
	if strings.TrimSpace(in.StorageReturnMode) == "" {
		in.StorageReturnMode = "back"
	}
	return in
}

func suiteSplitCommandLines(raw string) []string {
	raw = strings.ReplaceAll(raw, "\r", "")
	parts := strings.FieldsFunc(raw, func(r rune) bool { return r == '\n' || r == ';' })
	out := make([]string, 0, len(parts))
	seen := map[string]bool{}
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" || seen[part] {
			continue
		}
		seen[part] = true
		out = append(out, part)
	}
	return out
}

func suiteConfiguredMapTools(botID int) suiteMapToolSettings {
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	return suiteDefaultMapToolSettings(suitePortState.data.MapTools[botID])
}

// suiteRunConfiguredStartCommands deliberately uses this App's existing Bedrock
// connection. It never starts a second login flow and never reads external credentials.
func suiteRunConfiguredStartCommands(bot *BotSession) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	if bot.SuiteStartCommandsSent || !bot.Connected || !bot.PlayerReady || bot.conn == nil || bot.Respawning.Load() {
		bot.mu.Unlock()
		return
	}
	bot.SuiteStartCommandsSent = true
	bot.SuiteStartCommandsAt = time.Now()
	botID := bot.ID
	conn := bot.conn
	bot.mu.Unlock()

	settings := suiteConfiguredMapTools(botID)
	if len(settings.StartCommands) == 0 {
		return
	}
	go func() {
		for i, cmd := range settings.StartCommands {
			cmd = strings.TrimSpace(cmd)
			if cmd == "" {
				continue
			}
			bot.mu.Lock()
			ready := bot.Connected && bot.PlayerReady && bot.conn == conn && !bot.Respawning.Load()
			bot.mu.Unlock()
			if !ready {
				return
			}
			if err := sendClientMessageImmediate(conn, cmd); err != nil {
				bot.AddSystemLog("啟動指令失敗：" + err.Error())
				return
			}
			bot.AddSystemLog("啟動指令：" + cmd)
			if i+1 < len(settings.StartCommands) {
				time.Sleep(time.Duration(settings.CommandDelay) * time.Millisecond)
			}
		}
	}()
}

func suiteQueueConfiguredBoxCommands(botID int) (suiteTask, error) {
	settings := suiteConfiguredMapTools(botID)
	if len(settings.BoxCommands) == 0 {
		return suiteTask{}, errors.New("尚未設定箱子/補料前置指令")
	}
	t := bedrockSuiteTasks.enqueue(botID, "command_sequence", "箱子 / 補料前置指令", 55, map[string]interface{}{
		"commands": settings.BoxCommands,
		"delay_ms": settings.CommandDelay,
	})
	return t, nil
}

func suiteToolboxSnapshot(botID int) map[string]interface{} {
	suitePortState.Lock()
	defer suitePortState.Unlock()
	suiteEnsurePortStateLocked()
	storage := append([]suiteStorageProfile(nil), suitePortState.data.StorageProfiles[botID]...)
	claims := append([]suiteBuildClaim(nil), suitePortState.data.BuildClaims[botID]...)
	settings := suiteDefaultMapToolSettings(suitePortState.data.MapTools[botID])
	policy := append([]string(nil), suitePortState.data.MapPolicy[botID]...)
	return map[string]interface{}{
		"ok":         true,
		"storage":    storage,
		"claims":     claims,
		"map_tools":  settings,
		"map_policy": policy,
	}
}

func suiteDashboardSnapshotAll() map[string]interface{} {
	sessionMu.RLock()
	ids := make([]int, 0, len(sessions))
	bots := make(map[int]*BotSession, len(sessions))
	for id, bot := range sessions {
		ids = append(ids, id)
		bots[id] = bot
	}
	sessionMu.RUnlock()
	sort.Ints(ids)
	items := make([]map[string]interface{}, 0, len(ids))
	for _, id := range ids {
		bot := bots[id]
		if bot == nil {
			continue
		}
		bot.mu.Lock()
		name := bot.Name
		if strings.TrimSpace(name) == "" {
			name = fmt.Sprintf("Bot-%d", id)
		}
		position := bot.LastPlayerPos
		positionKnown := bot.HasPlayerPos
		positionSource := "reconciled_local"
		if bot.HasServerPlayerPos && bot.LastServerPlayerPos != ([3]float32{}) {
			position = bot.LastServerPlayerPos
			positionKnown = true
			positionSource = "server"
		}
		row := map[string]interface{}{
			"bot_id":            id,
			"name":              name,
			"active":            bot.IsActive,
			"connected":         bot.Connected && bot.PlayerReady && bot.conn != nil && !bot.Respawning.Load(),
			"network_connected": bot.Connected && bot.conn != nil,
			"player_ready":      bot.PlayerReady,
			"respawning":        bot.Respawning.Load(),
			"latency_ms":        bot.LatencyMS,
			"server":            bot.ServerAddr,
			"position":          map[string]float32{"x": position[0], "y": position[1], "z": position[2]},
			"position_known":    positionKnown,
			"position_source":   positionSource,
			"health":            bot.SuiteHealth,
			"max_health":        bot.SuiteMaxHealth,
			"hunger":            bot.SuiteHunger,
			"max_hunger":        bot.SuiteMaxHunger,
			"vitals_known":      bot.SuiteVitalsKnown,
			"experience_level":  bot.ExperienceLevel,
			"current_task_text": bot.CurrentTask,
			"last_packet_in":    bot.SuiteLastPacketIn,
			"last_packet_out":   bot.SuiteLastPacketOut,
		}
		bot.mu.Unlock()

		bedrockSuiteTasks.mu.Lock()
		paused := bedrockSuiteTasks.paused[id]
		queued := 0
		running := 0
		blocked := 0
		counts := map[string]int{"map": 0, "explosion": 0, "structure": 0, "other": 0}
		var current *suiteTask
		var next *suiteTask
		for _, t := range bedrockSuiteTasks.queues[id] {
			if t == nil {
				continue
			}
			switch t.Status {
			case suiteTaskQueued:
				queued++
				if next == nil {
					cp := suiteCloneTask(t)
					next = &cp
				}
			case suiteTaskRunning:
				running++
				if current == nil {
					cp := suiteCloneTask(t)
					current = &cp
				}
			case suiteTaskBlocked:
				blocked++
				if current == nil {
					cp := suiteCloneTask(t)
					current = &cp
				}
			}
			switch t.Kind {
			case "mapart", "draw_map":
				counts["map"]++
			case "explosion", "blast":
				counts["explosion"]++
			case "build", "build_library":
				counts["structure"]++
			default:
				counts["other"]++
			}
		}
		bedrockSuiteTasks.mu.Unlock()
		row["paused"] = paused
		row["queued"] = queued
		row["running"] = running
		row["blocked"] = blocked
		row["counts"] = counts
		if current != nil {
			row["current"] = *current
		}
		if next != nil {
			row["next"] = *next
		}
		items = append(items, row)
	}
	return map[string]interface{}{"ok": true, "bots": items, "updated_at": time.Now()}
}

func suiteSetBotActive(botID int, active bool) error {
	sessionMu.RLock()
	bot := sessions[botID]
	sessionMu.RUnlock()
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	bot.mu.Lock()
	bot.IsActive = active
	cancel := bot.ConnectCancel
	conn := bot.conn
	if !active {
		bot.Connected = false
		bot.PlayerReady = false
		bot.conn = nil
		bot.SessionGeneration++
		bot.ConnectCancel = nil
		bot.SuiteStartCommandsSent = false
	}
	bot.mu.Unlock()
	if !active {
		if cancel != nil {
			cancel()
		}
		if conn != nil {
			_ = conn.Close()
		}
		bot.AddSystemLog("已從 BOT 儀表板停止連線")
	} else {
		bot.AddSystemLog("已從 BOT 儀表板啟用；使用目前 App 的 Bedrock/Xbox 登入流程")
	}
	return nil
}

func mustSuiteBotForCompat(id int) *BotSession {
	bot, _ := suiteLookupBot(id)
	return bot
}

func suiteBuildClaimPreview(id int, claimID string) (map[string]interface{}, error) {
	suitePortState.Lock()
	suiteEnsurePortStateLocked()
	var claim *suiteBuildClaim
	for i := range suitePortState.data.BuildClaims[id] {
		if suitePortState.data.BuildClaims[id][i].ID == claimID {
			cp := suitePortState.data.BuildClaims[id][i]
			claim = &cp
			break
		}
	}
	suitePortState.Unlock()
	if claim == nil {
		return nil, errors.New("找不到領地")
	}
	minX, maxX := claim.From.X, claim.To.X
	if minX > maxX {
		minX, maxX = maxX, minX
	}
	minZ, maxZ := claim.From.Z, claim.To.Z
	if minZ > maxZ {
		minZ, maxZ = maxZ, minZ
	}
	width := maxX - minX + 1
	depth := maxZ - minZ + 1
	cols := maxInt(1, width/128)
	rows := maxInt(1, depth/129)
	cells := make([]map[string]interface{}, 0, cols*rows)
	for rz := 0; rz < rows; rz++ {
		for cx := 0; cx < cols; cx++ {
			start := Vec3i{X: minX + cx*128, Y: claim.From.Y, Z: minZ + rz*129}
			cells = append(cells, map[string]interface{}{"slot": rz*cols + cx, "x": cx, "z": rz, "start": start})
		}
	}
	return map[string]interface{}{"claim": claim, "width": width, "depth": depth, "columns": cols, "rows": rows, "cells": cells}, nil
}

func suiteNormaliseMaterialID(material string) string {
	material = strings.ToLower(strings.TrimSpace(material))
	if material == "" {
		return ""
	}
	if !strings.Contains(material, ":") {
		material = "minecraft:" + material
	}
	return material
}

