type Vec3i struct {
	X int `json:"x"`
	Y int `json:"y"`
	Z int `json:"z"`
}

func (p Vec3i) String() string {
	return fmt.Sprintf("%d,%d,%d", p.X, p.Y, p.Z)
}

type Area struct {
	From Vec3i `json:"from"`
	To   Vec3i `json:"to"`
}

func NormaliseArea(a Area) Area {
	return Area{
		From: Vec3i{
			X: minInt(a.From.X, a.To.X),
			Y: minInt(a.From.Y, a.To.Y),
			Z: minInt(a.From.Z, a.To.Z),
		},
		To: Vec3i{
			X: maxInt(a.From.X, a.To.X),
			Y: maxInt(a.From.Y, a.To.Y),
			Z: maxInt(a.From.Z, a.To.Z),
		},
	}
}

func (a Area) Contains(p Vec3i) bool {
	a = NormaliseArea(a)
	return p.X >= a.From.X && p.X <= a.To.X &&
		p.Y >= a.From.Y && p.Y <= a.To.Y &&
		p.Z >= a.From.Z && p.Z <= a.To.Z
}

func (a Area) Width() int {
	a = NormaliseArea(a)
	return a.To.X - a.From.X + 1
}

func (a Area) Height() int {
	a = NormaliseArea(a)
	return a.To.Y - a.From.Y + 1
}

func (a Area) Depth() int {
	a = NormaliseArea(a)
	return a.To.Z - a.From.Z + 1
}

