type collectWireCapture struct {
	bot       *BotSession
	remote    atomic.Value
	captureTo atomic.Int64
}

var (
	collectWireLogOnce sync.Once
	collectWireLogCh   = make(chan []byte, 8192)
)

func newCollectWireCapture(bot *BotSession) *collectWireCapture {
	return &collectWireCapture{bot: bot}
}

func decodeRawUpdateAttributes(payload []byte) (pk packet.UpdateAttributes, ok bool) {
	if len(payload) == 0 {
		return packet.UpdateAttributes{}, false
	}

	defer func() {
		if recover() != nil {
			ok = false
			pk = packet.UpdateAttributes{}
		}
	}()

	buf := bytes.NewBuffer(payload)
	reader := protocol.NewReader(buf, 0, false)
	pk.Marshal(reader)
	return pk, true
}

func capturePlayerExperienceFromRawPacket(
	bot *BotSession,
	header packet.Header,
	payload []byte,
) {
	if bot == nil || header.PacketID != packet.IDUpdateAttributes {
		return
	}

	pk, ok := decodeRawUpdateAttributes(payload)
	if !ok || !hasPlayerExperienceAttributes(pk.Attributes) {
		return
	}

	// UpdateAttributes is a server -> client packet. Reading it here is
	// important because Dialer.PacketFunc also receives packets consumed by
	// gophertunnel's connection/spawn sequence before handleConnection starts.
	bot.updatePlayerExperienceAttributesFrom(
		pk.Attributes,
		"dial/raw",
		pk.EntityRuntimeID,
	)
}

func (capture *collectWireCapture) setRemote(addr net.Addr) {
	if capture == nil || addr == nil {
		return
	}
	capture.remote.Store(addr.String())
}

func collectWirePacketName(id uint32) (string, bool) {
	switch id {
	case packet.IDPlayerAuthInput:
		return "PlayerAuthInput", true
	case packet.IDPlayerAction:
		return "PlayerAction", true
	case packet.IDInventoryTransaction:
		return "InventoryTransaction", true
	case packet.IDItemStackRequest:
		return "ItemStackRequest", true
	case packet.IDItemStackResponse:
		return "ItemStackResponse", true
	case packet.IDUpdateBlock:
		return "UpdateBlock", true
	case packet.IDLevelEvent:
		return "LevelEvent", true
	case packet.IDCorrectPlayerMovePrediction:
		return "CorrectPlayerMovePrediction", true
	case packet.IDMovePlayer:
		return "MovePlayer", true
	case packet.IDUpdateAttributes:
		return "UpdateAttributes", true
	case packet.IDPacketViolationWarning:
		return "PacketViolationWarning", true
	case packet.IDDisconnect:
		return "Disconnect", true
	default:
		return "", false
	}
}

func (capture *collectWireCapture) capture(header packet.Header, payload []byte, src, dst net.Addr) {
	if capture == nil || capture.bot == nil {
		return
	}

	// Always inspect XP UpdateAttributes, even when packet collection is off.
	// This is the path that catches the player's initial XP during Dial/spawn.
	capturePlayerExperienceFromRawPacket(capture.bot, header, payload)

	now := time.Now()
	capture.bot.mu.Lock()
	active := capture.bot.CollectRunning
	botID := capture.bot.ID
	botName := clean(capture.bot.Name)
	capture.bot.mu.Unlock()
	if active {
		// Several proxy/server disconnects arrive about 20-30 seconds after the
		// invalid action that caused them. Keep enough tail to retain the actual
		// Disconnect packet instead of only seeing the later context cancellation.
		capture.captureTo.Store(now.Add(3 * time.Second).UnixNano())
	}
	withinCaptureWindow := active || now.UnixNano() <= capture.captureTo.Load()
	if !withinCaptureWindow && header.PacketID != packet.IDPacketViolationWarning && header.PacketID != packet.IDDisconnect {
		return
	}

	source, destination := "", ""
	if src != nil {
		source = src.String()
	}
	if dst != nil {
		destination = dst.String()
	}
	direction := "unknown"
	if remote, ok := capture.remote.Load().(string); ok && remote != "" {
		switch {
		case source == remote:
			direction = "in"
		case destination == remote:
			direction = "out"
		}
	}

	packetName, wanted := collectWirePacketName(header.PacketID)
	// 採集期間不要只看預先猜中的幾種封包。所有進出封包都留下 ID
	// 與原始 payload，才能找出採集前後由其他 goroutine 送出的封包。
	if !wanted && withinCaptureWindow {
		packetName = fmt.Sprintf("PacketID(%d)", header.PacketID)
		wanted = true
	}
	if !wanted {
		return
	}

	const maxPayload = 4096
	raw := payload
	truncated := false
	if len(raw) > maxPayload {
		raw = raw[:maxPayload]
		truncated = true
	}
	entry := collectWirePacketLogEntry{
		Time:            now.Format(time.RFC3339Nano),
		BotID:           botID,
		BotName:         botName,
		Direction:       direction,
		PacketID:        header.PacketID,
		PacketName:      packetName,
		SenderSubClient: header.SenderSubClient,
		TargetSubClient: header.TargetSubClient,
		Source:          source,
		Destination:     destination,
		PayloadLength:   len(payload),
		PayloadBase64:   base64.StdEncoding.EncodeToString(raw),
		Truncated:       truncated,
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	collectWireLogOnce.Do(func() {
		go func() {
			if err := os.MkdirAll(botDataDir, 0755); err != nil {
				return
			}
			f, err := os.OpenFile(filepath.Join(botDataDir, "collect-wire-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
			if err != nil {
				return
			}
			defer f.Close()
			for queued := range collectWireLogCh {
				_, _ = f.Write(append(queued, '\n'))
			}
		}()
	})
	select {
	case collectWireLogCh <- line:
	default:
		// 封包 reader 絕不能因診斷磁碟速度而卡住。
	}
}

func startCollectDiagnosticWriter() {
	collectDiagnosticLogOnce.Do(func() {
		go func() {
			if err := os.MkdirAll(botDataDir, 0755); err != nil {
				return
			}
			path := filepath.Join(botDataDir, "collect-diagnostics.log")
			f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
			if err != nil {
				return
			}
			defer func() { _ = f.Close() }()
			var size int64
			if info, statErr := f.Stat(); statErr == nil {
				size = info.Size()
			}
			for line := range collectDiagnosticLogCh {
				writeBytes := int64(len(line) + 1)
				if collectDiagnosticNeedsRotation(size, writeBytes) {
					_ = f.Close()
					backupPath := path + ".1"
					_ = os.Remove(backupPath)
					if renameErr := os.Rename(path, backupPath); renameErr != nil {
						// If another scanner briefly prevents a Windows rename, truncating
						// the generated diagnostic is safer than allowing unbounded growth.
						f, err = os.OpenFile(path, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0600)
					} else {
						f, err = os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
					}
					if err != nil {
						return
					}
					size = 0
				}
				n, writeErr := f.Write(append(line, '\n'))
				if writeErr == nil {
					size += int64(n)
				}
			}
		}()
	})
}

const collectDiagnosticMaxBytes int64 = 16 << 20

func collectDiagnosticNeedsRotation(currentSize, nextWrite int64) bool {
	if nextWrite < 0 {
		nextWrite = 0
	}
	return currentSize > 0 && currentSize+nextWrite > collectDiagnosticMaxBytes
}

func logCollectDiagnostic(bot *BotSession, event, detail string) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	entry := collectDiagnosticLogEntry{
		Time:           time.Now().Format(time.RFC3339Nano),
		Event:          strings.TrimSpace(event),
		BotID:          bot.ID,
		BotName:        clean(bot.Name),
		Connected:      bot.Connected,
		CollectRunning: bot.CollectRunning,
		CollectStatus:  bot.CollectStatus,
		CollectError:   bot.CollectLastError,
		Detail:         strings.TrimSpace(detail),
	}
	bot.mu.Unlock()
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	startCollectDiagnosticWriter()
	select {
	case collectDiagnosticLogCh <- line:
	default:
		// Diagnostic I/O must never stall packet reading, collection movement or UI.
	}
}

// logTPATextPacket records only messages already identified as TPA/TPAHERE.
// It avoids logging unrelated chat while preserving the server's exact Text layout.
func logTPATextPacket(bot *BotSession, pk *packet.Text, matched string) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	botID := bot.ID
	botName := bot.Name
	bot.mu.Unlock()
	params := make([]string, 0, len(pk.Parameters))
	for _, param := range pk.Parameters {
		params = append(params, clean(param))
	}
	entry := tpaTextPacketLogEntry{
		Time:             time.Now().Format(time.RFC3339Nano),
		BotID:            botID,
		BotName:          clean(botName),
		TextType:         pk.TextType,
		NeedsTranslation: pk.NeedsTranslation,
		SourceName:       clean(pk.SourceName),
		Message:          clean(pk.Message),
		Parameters:       params,
		Matched:          clean(matched),
		Respawning:       bot.Respawning.Load(),
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	tpaPacketLogMu.Lock()
	defer tpaPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "tpa-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

func logTPAResponse(bot *BotSession, matched, action string, responseErr error) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	botID, botName := bot.ID, bot.Name
	bot.mu.Unlock()
	entry := map[string]any{
		"time":     time.Now().Format(time.RFC3339Nano),
		"event":    "response",
		"bot_id":   botID,
		"bot_name": clean(botName),
		"matched":  clean(matched),
		"action":   strings.TrimSpace(action),
	}
	if responseErr != nil {
		entry["error"] = responseErr.Error()
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	tpaPacketLogMu.Lock()
	defer tpaPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "tpa-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

// logCollectTextPacket writes only packets that contain an actual collect command.
// Keeping the raw fields makes server-specific whisper/translation formats diagnosable
// without logging unrelated player chat.
func logCollectTextPacket(bot *BotSession, pk *packet.Text) {
	if bot == nil || pk == nil {
		return
	}
	bot.mu.Lock()
	botID := bot.ID
	botName := bot.Name
	bot.mu.Unlock()
	found := false
	for _, raw := range tpaTextPacketCandidates(pk) {
		candidate := collectCommandTail(raw)
		if _, matched, _ := ParseCollectCommand(candidate, botName); matched {
			found = true
			break
		}
		if _, matched, _ := ParseBedrockActionCommand(candidate, botName); matched {
			found = true
			break
		}
	}
	if !found {
		return
	}
	entry := collectTextPacketLogEntry{
		Time:             time.Now().Format(time.RFC3339Nano),
		BotID:            botID,
		BotName:          clean(botName),
		TextType:         pk.TextType,
		NeedsTranslation: pk.NeedsTranslation,
		SourceName:       clean(pk.SourceName),
		Message:          clean(pk.Message),
		Parameters:       append([]string(nil), pk.Parameters...),
	}
	line, err := json.Marshal(entry)
	if err != nil {
		return
	}
	collectPacketLogMu.Lock()
	defer collectPacketLogMu.Unlock()
	if err := os.MkdirAll(botDataDir, 0755); err != nil {
		return
	}
	f, err := os.OpenFile(filepath.Join(botDataDir, "collect-packets.log"), os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0600)
	if err != nil {
		return
	}
	_, _ = f.Write(append(line, '\n'))
	_ = f.Close()
}

func sendCollectChatReply(bot *BotSession, recipient, message string) {
	if bot == nil {
		return
	}
	recipient = strings.TrimSpace(clean(recipient))
	message = strings.TrimSpace(clean(message))
	if recipient == "" || message == "" {
		return
	}
	bot.mu.Lock()
	conn := bot.conn
	connected := bot.Connected
	bot.mu.Unlock()
	if !connected || conn == nil {
		return
	}
	if err := sendClientMessage(conn, "/m "+recipient+" [採集Bot] "+message); err != nil {
		bot.AddSystemLog("採集指令回覆失敗：" + err.Error())
		return
	}
	if err := conn.Flush(); err != nil {
		bot.AddSystemLog("採集指令回覆送出失敗：" + err.Error())
	}
}

// handleCollectTextPacket reads every field in packet.Text. Some servers put a private
// message in Message, while translated chat formats put the sender/command in Parameters.
func handleCollectTextPacket(bot *BotSession, pk *packet.Text) bool {
	if bot == nil || pk == nil {
		return false
	}
	logCollectTextPacket(bot, pk)
	replyTo, command, authorised := collectWhitelistedTextCommand(bot, pk)
	if !authorised {
		return false
	}
	if handleBedrockActionChatCommand(bot, command, replyTo) {
		bot.AddSystemLog(fmt.Sprintf("已接受白名單控制指令（TextType=%d，發送者=%s）", pk.TextType, replyTo))
		return true
	}
	if handleCollectChatCommand(bot, command, replyTo) {
		bot.AddSystemLog(fmt.Sprintf("已接受白名單採集指令（TextType=%d，發送者=%s）", pk.TextType, replyTo))
		return true
	}
	return false
}

// dropChineseItemAliases 讓遠端 drop/丟 指令可直接使用繁體中文物品名稱。
// 值統一使用 Bedrock item identifier；英文 ID / minecraft:ID 仍照舊可用。
// 這裡同時收常見台灣譯名、玩家常用簡稱與少數同義詞。

// vanillaZhTWTranslationNames comes from Mojang's official Bedrock vanilla
// resource_pack/texts/zh_TW.lang. It is matched against the server's live
// GameData().Items registry at login, so only item IDs that actually exist on
// the connected server are enabled.
var vanillaZhTWTranslationNames = loadStaticStringMap("vanilla_zh_tw.json")

func dropNameWords(value string) []string {
	value = strings.TrimSpace(value)
	if value == "" {
		return nil
	}
	// Split legacy language keys such as muttonCooked and cooked_beef into
	// comparable word sets.
	var b strings.Builder
	var prev rune
	for i, r := range value {
		if i > 0 && unicode.IsUpper(r) && (unicode.IsLower(prev) || unicode.IsDigit(prev)) {
			b.WriteByte('_')
		}
		switch r {
		case '.', ':', '-', '/', '\\', ' ':
			b.WriteByte('_')
		default:
			b.WriteRune(unicode.ToLower(r))
		}
		prev = r
	}
	raw := strings.FieldsFunc(b.String(), func(r rune) bool {
		return r == '_' || r == '.' || r == ':' || r == '-' || r == '/'
	})
	out := make([]string, 0, len(raw))
	for _, word := range raw {
		word = strings.TrimSpace(word)
		switch word {
		case "", "minecraft", "item", "tile", "name":
			continue
		}
		out = append(out, word)
	}
	return out
}

func dropWordsSignature(value string, removeBlock bool) string {
	words := dropNameWords(value)
	if removeBlock {
		filtered := words[:0]
		for _, word := range words {
			if word == "block" {
				continue
			}
			filtered = append(filtered, word)
		}
		words = filtered
	}
	sort.Strings(words)
	return strings.Join(words, "|")
}

func dropCompactName(value string) string {
	words := dropNameWords(value)
	return strings.Join(words, "")
}

func translationBody(key string) string {
	key = strings.TrimSpace(key)
	key = strings.TrimPrefix(key, "item.")
	key = strings.TrimPrefix(key, "tile.")
	key = strings.TrimSuffix(key, ".name")
	return key
}

// addOfficialVanillaZhTWAliases binds Mojang's official Traditional-Chinese
// names to the exact runtime item registry sent by the current Bedrock server.
// It uses several conservative matching passes and only accepts fuzzy matches
// that resolve to exactly one registered item ID.
func normaliseLegacyTranslationWords(words []string) []string {
	if len(words) == 0 {
		return nil
	}

	out := make([]string, 0, len(words)+2)
	for i := 0; i < len(words); i++ {
		word := strings.ToLower(strings.TrimSpace(words[i]))
		if word == "" {
			continue
		}

		// Old Bedrock language keys used "cloth" for wool.
		if word == "cloth" {
			out = append(out, "wool")
			continue
		}

		// Older translation keys used "silver" for what modern IDs call
		// light_gray.
		if word == "silver" {
			out = append(out, "light", "gray")
			continue
		}

		// stained_hardened_clay.* / hardened_clay.* are modern terracotta IDs.
		if word == "stained" && i+2 < len(words) &&
			strings.EqualFold(words[i+1], "hardened") &&
			strings.EqualFold(words[i+2], "clay") {
			out = append(out, "terracotta")
			i += 2
			continue
		}
		if word == "hardened" && i+1 < len(words) &&
			strings.EqualFold(words[i+1], "clay") {
			out = append(out, "terracotta")
			i++
			continue
		}

		// Common old names.
		switch word {
		case "wooden":
			out = append(out, "wood")
		case "reeds":
			out = append(out, "sugar", "cane")
		default:
			out = append(out, word)
		}
	}
	return out
}

func removeLegacyTranslationStateWords(words []string) []string {
	if len(words) == 0 {
		return nil
	}
	out := make([]string, 0, len(words))
	for _, word := range words {
		switch strings.ToLower(strings.TrimSpace(word)) {
		// These are legacy localisation-state suffixes, not item identity.
		case "", "dry", "normal", "default", "plain":
			continue
		default:
			out = append(out, word)
		}
	}
	return out
}

func wordsSignature(words []string, removeBlock bool) string {
	if len(words) == 0 {
		return ""
	}
	copyWords := make([]string, 0, len(words))
	for _, word := range words {
		word = strings.ToLower(strings.TrimSpace(word))
		if word == "" || (removeBlock && word == "block") {
			continue
		}
		copyWords = append(copyWords, word)
	}
	sort.Strings(copyWords)
	return strings.Join(copyWords, "|")
}

func joinWordsUnderscore(words []string) string {
	cleaned := make([]string, 0, len(words))
	for _, word := range words {
		word = strings.ToLower(strings.TrimSpace(word))
		if word != "" {
			cleaned = append(cleaned, word)
		}
	}
	return strings.Join(cleaned, "_")
}

func uniqueRegisteredID(matches []string) (string, bool) {
	seen := map[string]bool{}
	unique := ""
	for _, id := range matches {
		id = strings.ToLower(strings.TrimSpace(id))
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		if unique == "" {
			unique = id
			continue
		}
		if unique != id {
			return "", false
		}
	}
	return unique, unique != ""
}

// legacyTranslationFallbackID bridges old Bedrock localisation keys to the
// modern server item registry. It intentionally accepts only unique matches.
func legacyTranslationFallbackID(
	body string,
	exactShort map[string]string,
	sigIDs map[string][]string,
	reducedSigIDs map[string][]string,
) (string, bool) {
	words := normaliseLegacyTranslationWords(dropNameWords(body))
	if len(words) == 0 {
		return "", false
	}

	trySignature := func(candidate []string) (string, bool) {
		if sig := wordsSignature(candidate, false); sig != "" {
			if id, ok := uniqueRegisteredID(sigIDs[sig]); ok {
				return id, true
			}
		}
		if sig := wordsSignature(candidate, true); sig != "" {
			if id, ok := uniqueRegisteredID(reducedSigIDs[sig]); ok {
				return id, true
			}
		}
		return "", false
	}

	// First normalise legacy vocabulary without dropping any state.
	if id, ok := trySignature(words); ok {
		return id, true
	}

	// "tile.sponge.dry.name" -> minecraft:sponge.
	withoutState := removeLegacyTranslationStateWords(words)
	if id, ok := trySignature(withoutState); ok {
		return id, true
	}
	if direct := joinWordsUnderscore(withoutState); direct != "" {
		if id, ok := exactShort[direct]; ok {
			return id, true
		}
	}

	// Old keys frequently used a family prefix plus the real modern item name:
	// tile.stone.granite.name -> minecraft:granite.
	// Prefer the longest suffix, then longest prefix, and only exact IDs.
	for length := len(withoutState) - 1; length >= 1; length-- {
		suffix := joinWordsUnderscore(withoutState[len(withoutState)-length:])
		if id, ok := exactShort[suffix]; ok {
			return id, true
		}
	}
	for length := len(withoutState) - 1; length >= 1; length-- {
		prefix := joinWordsUnderscore(withoutState[:length])
		if id, ok := exactShort[prefix]; ok {
			return id, true
		}
	}

	// Single-token fallback is only safe if it is itself an exact registered
	// short ID. This catches sponge.dry -> sponge without fuzzy guessing.
	if len(withoutState) > 0 {
		for i := len(withoutState) - 1; i >= 0; i-- {
			token := withoutState[i]
			switch token {
			case "block", "item", "tile", "wood", "stone", "brick", "planks",
				"log", "door", "slab", "stairs", "wall", "fence":
				continue
			}
			if id, ok := exactShort[token]; ok {
				return id, true
			}
		}
	}

	return "", false
}

// addOfficialVanillaZhTWAliases binds Mojang's official Traditional-Chinese
// names to the exact runtime item registry sent by the current Bedrock server.
// It supports both modern keys and older metadata/family-style localisation
// keys, while refusing ambiguous fuzzy matches.
func addOfficialVanillaZhTWAliases(aliases map[string]string, registeredIDs map[string]bool) {
	if aliases == nil || len(registeredIDs) == 0 {
		return
	}

	exactShort := make(map[string]string, len(registeredIDs))
	sigIDs := map[string][]string{}
	reducedSigIDs := map[string][]string{}
	compactIDs := map[string][]string{}

	for id := range registeredIDs {
		id = strings.ToLower(strings.TrimSpace(id))
		if id == "" {
			continue
		}
		short := strings.TrimPrefix(id, "minecraft:")
		exactShort[short] = id
		if sig := dropWordsSignature(short, false); sig != "" {
			sigIDs[sig] = append(sigIDs[sig], id)
		}
		if sig := dropWordsSignature(short, true); sig != "" {
			reducedSigIDs[sig] = append(reducedSigIDs[sig], id)
		}
		if compact := dropCompactName(short); compact != "" {
			compactIDs[compact] = append(compactIDs[compact], id)
		}
	}

	// Pass 1: direct/current IDs.
	for key, zh := range vanillaZhTWTranslationNames {
		body := strings.ToLower(strings.TrimSpace(translationBody(key)))
		if body == "" || zh == "" {
			continue
		}
		if id, ok := exactShort[body]; ok {
			addDropAlias(aliases, zh, id)
			continue
		}
		direct := strings.ReplaceAll(body, ".", "_")
		if id, ok := exactShort[direct]; ok {
			addDropAlias(aliases, zh, id)
			continue
		}
	}

	// Pass 2: token reordering and compact-name matches.
	for key, zh := range vanillaZhTWTranslationNames {
		if zh == "" {
			continue
		}
		if existing := aliases[normaliseDropAliasKey(zh)]; existing != "" {
			continue
		}
		body := translationBody(key)
		if sig := dropWordsSignature(body, false); sig != "" {
			if id, ok := uniqueRegisteredID(sigIDs[sig]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
		if compact := dropCompactName(body); compact != "" {
			if id, ok := uniqueRegisteredID(compactIDs[compact]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
		if sig := dropWordsSignature(body, true); sig != "" {
			if id, ok := uniqueRegisteredID(reducedSigIDs[sig]); ok {
				addDropAlias(aliases, zh, id)
				continue
			}
		}
	}

	// Pass 3: bridge old Bedrock localisation vocabulary/metadata keys.
	for key, zh := range vanillaZhTWTranslationNames {
		if zh == "" {
			continue
		}
		if existing := aliases[normaliseDropAliasKey(zh)]; existing != "" {
			continue
		}
		if id, ok := legacyTranslationFallbackID(
			translationBody(key),
			exactShort,
			sigIDs,
			reducedSigIDs,
		); ok {
			addDropAlias(aliases, zh, id)
		}
	}
}

