func normaliseDropItemTarget(value string) string {
	v := strings.ToLower(strings.TrimSpace(clean(value)))
	v = strings.ReplaceAll(v, "　", " ")
	v = strings.Join(strings.Fields(v), " ")
	if alias, ok := dropChineseItemAliases[v]; ok {
		return alias
	}
	// 允許使用 minecraft:stone、stone、cobblestone 等原始 ID。
	return normaliseCollectItemName(v)
}

func dropVariantBaseName(value string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	value = strings.TrimPrefix(value, "minecraft:")
	if value == "" {
		return ""
	}
	parts := strings.Split(value, "_")
	for len(parts) > 1 {
		last := parts[len(parts)-1]
		if _, err := strconv.Atoi(last); err == nil {
			parts = parts[:len(parts)-1]
			continue
		}
		break
	}
	return strings.Join(parts, "_")
}

func dropVariantWords(value string) []string {
	value = strings.ToLower(strings.TrimSpace(value))
	value = strings.TrimPrefix(value, "minecraft:")
	if value == "" {
		return nil
	}
	words := strings.FieldsFunc(value, func(r rune) bool {
		return r == '_' || r == '-' || r == '.' || r == ':' || r == '/' || r == '\\' || unicode.IsSpace(r)
	})
	out := make([]string, 0, len(words))
	for _, word := range words {
		word = strings.TrimSpace(word)
		if word == "" {
			continue
		}
		if _, err := strconv.Atoi(word); err == nil {
			continue
		}
		switch word {
		case "minecraft":
			continue
		}
		out = append(out, word)
	}
	return out
}

func dropVariantSignature(value string, dropGeneric bool) string {
	words := dropVariantWords(value)
	if dropGeneric {
		filtered := words[:0]
		for _, word := range words {
			switch word {
			case "block", "item":
				continue
			default:
				filtered = append(filtered, word)
			}
		}
		words = filtered
	}
	sort.Strings(words)
	return strings.Join(words, "|")
}

func dropVariantCompact(value string, dropGeneric bool) string {
	words := dropVariantWords(value)
	if dropGeneric {
		filtered := words[:0]
		for _, word := range words {
			if word == "block" || word == "item" {
				continue
			}
			filtered = append(filtered, word)
		}
		words = filtered
	}
	return strings.Join(words, "")
}

func dropItemVariantScore(targetID, itemID string) int {
	targetID = strings.ToLower(strings.TrimSpace(targetID))
	itemID = strings.ToLower(strings.TrimSpace(itemID))
	if targetID == "" || itemID == "" {
		return -1
	}

	targetShort := strings.TrimPrefix(targetID, "minecraft:")
	itemShort := strings.TrimPrefix(itemID, "minecraft:")
	if targetShort == itemShort {
		return 1000
	}

	targetBase := dropVariantBaseName(targetShort)
	itemBase := dropVariantBaseName(itemShort)
	if targetBase != "" && targetBase == itemBase {
		return 950
	}

	// 同 token、只是順序不同，例如 legacy key/variant 命名順序差異。
	targetSig := dropVariantSignature(targetShort, false)
	itemSig := dropVariantSignature(itemShort, false)
	if targetSig != "" && targetSig == itemSig {
		return 900
	}

	// 忽略 block/item 這類泛稱再比。
	targetReduced := dropVariantSignature(targetShort, true)
	itemReduced := dropVariantSignature(itemShort, true)
	if targetReduced != "" && targetReduced == itemReduced {
		return 850
	}

	// compact 比對可處理部分底線/命名格式差異。
	targetCompact := dropVariantCompact(targetShort, true)
	itemCompact := dropVariantCompact(itemShort, true)
	if targetCompact != "" && targetCompact == itemCompact {
		return 820
	}

	// 最後才接受明顯「標準 ID + 變體尾碼」的情況。
	if strings.HasPrefix(itemShort, targetShort+"_") || strings.HasPrefix(targetShort, itemShort+"_") {
		return 780
	}

	// 某些 Bedrock 舊 ID 會多一層 block/item 單字。
	if targetCompact != "" && itemCompact != "" {
		if strings.HasSuffix(targetCompact, itemCompact) || strings.HasSuffix(itemCompact, targetCompact) {
			shorter := len([]rune(targetCompact))
			if n := len([]rune(itemCompact)); n < shorter {
				shorter = n
			}
			if shorter >= 6 {
				return 700
			}
		}
	}
	return -1
}

func dropItemFamilyMatches(targetID, itemID string) bool {
	return dropItemVariantScore(targetID, itemID) >= 780
}

func chooseBestDropVariant(targetID string, candidates []string) (string, bool) {
	bestID := ""
	bestScore := -1
	tied := false
	seen := map[string]bool{}

	for _, id := range candidates {
		id = strings.ToLower(strings.TrimSpace(id))
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		score := dropItemVariantScore(targetID, id)
		if score < 0 {
			continue
		}
		if score > bestScore {
			bestScore = score
			bestID = id
			tied = false
		} else if score == bestScore && id != bestID {
			tied = true
		}
	}

	// 模糊等級太低或同分撞多個時不自動選，避免誤丟。
	if bestScore < 700 || bestID == "" || tied {
		return "", false
	}
	return bestID, true
}

// resolveRegisteredDropVariant 把繁中/標準原版 ID 對到伺服器真正使用的 Item ID。
// 1) 先找背包實際存在的物品。
// 2) 再找 live GameData registry。
// 3) 只有唯一最高分、安全匹配才採用。
func (bot *BotSession) resolveRegisteredDropVariant(targetID string) string {
	if bot == nil {
		return targetID
	}
	targetID = strings.ToLower(strings.TrimSpace(targetID))
	if targetID == "" || targetID == "*" {
		return targetID
	}

	bot.mu.Lock()
	itemNames := make(map[int32]string, len(bot.MapArtItemNames))
	for networkID, id := range bot.MapArtItemNames {
		itemNames[networkID] = strings.ToLower(strings.TrimSpace(id))
	}
	inventory := append([]protocol.ItemInstance(nil), bot.MapArtInventory...)
	bot.mu.Unlock()

	// 精確 registry ID 優先。
	for _, id := range itemNames {
		if id == targetID {
			return id
		}
	}

	inventoryCandidates := make([]string, 0, 8)
	for i, item := range inventory {
		if i >= 36 || item.Stack.Count == 0 {
			continue
		}
		id := itemNames[item.Stack.NetworkID]
		if id != "" {
			inventoryCandidates = append(inventoryCandidates, id)
		}
	}
	if id, ok := chooseBestDropVariant(targetID, inventoryCandidates); ok {
		return id
	}

	registryCandidates := make([]string, 0, len(itemNames))
	for _, id := range itemNames {
		if id != "" {
			registryCandidates = append(registryCandidates, id)
		}
	}
	if id, ok := chooseBestDropVariant(targetID, registryCandidates); ok {
		return id
	}
	return targetID
}

func collectDropItemMatches(target, itemName string) bool {
	target = strings.ToLower(strings.TrimSpace(clean(target)))
	itemName = strings.ToLower(strings.TrimSpace(itemName))
	if target == "*" {
		return itemName != ""
	}
	if target == "" || itemName == "" {
		return false
	}
	normTarget := normaliseDropItemTarget(target)
	return dropItemVariantScore(normTarget, itemName) >= 700
}

func sendBedrockDropRequest(bot *BotSession, conn *minecraft.Conn, req protocol.ItemStackRequest) error {
	if bot == nil || conn == nil {
		return errors.New("丟棄連線不存在")
	}

	// 1.26.x 的 ServerAuthoritativeInventory 下，真實客戶端會把 stack request
	// 掛在 PlayerAuthInput，並帶 PerformItemStackRequest flag。
	if conn.GameData().ServerAuthoritativeInventory {
		bot.mu.Lock()
		if bot.conn != conn || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
			bot.mu.Unlock()
			return errors.New("BOT 尚未完成登入/出生")
		}
		pos := bot.LastPlayerPos
		onGround := bot.LastPlayerOnGround
		pitch := bot.LastPlayerPitch
		yaw := bot.LastPlayerYaw
		headYaw := bot.LastPlayerHeadYaw
		ackServerData := !bot.MapArtServerDataAcknowledged
		bot.mu.Unlock()

		flags := protocol.NewInputFlags(packet.InputFlagCount)
		flags.Set(packet.InputFlagBlockBreakingDelayEnabled)
		flags.Set(packet.InputFlagPerformItemStackRequest)
		if ackServerData {
			flags.Set(packet.InputFlagClientAckServerData)
		}
		if mapArtLikelyOnGround(pos, onGround) {
			flags.Set(packet.InputFlagVerticalCollision)
		}

		input := &packet.PlayerAuthInput{
			Pitch:              pitch,
			Yaw:                yaw,
			HeadYaw:            headYaw,
			Position:           mgl32.Vec3{pos[0], pos[1], pos[2]},
			MoveVector:         mgl32.Vec2{},
			InputData:          flags,
			InputMode:          packet.InputModeMouse,
			PlayMode:           packet.PlayModeNormal,
			InteractionModel:   packet.InteractionModelCrosshair,
			InteractPitch:      pitch,
			InteractYaw:        yaw,
			Delta:              mgl32.Vec3{},
			ItemStackRequest:   protocol.Option(req),
			AnalogueMoveVector: mgl32.Vec2{},
			CameraOrientation:  mapArtCameraForward(yaw),
			RawMoveVector:      mgl32.Vec2{},
		}
		if _, err := bot.sendBedrockAuthInput(conn, input); err != nil {
			return err
		}
		bot.mu.Lock()
		if bot.conn == conn {
			bot.MapArtLastAuthInputAt = time.Now()
			if ackServerData {
				bot.MapArtServerDataAcknowledged = true
			}
		}
		bot.mu.Unlock()
		return nil
	}

	// 舊式 client-authoritative inventory 仍走獨立 ItemStackRequest。
	if err := conn.WritePacket(&packet.ItemStackRequest{Requests: []protocol.ItemStackRequest{req}}); err != nil {
		return err
	}
	return conn.Flush()
}

func autoDropRuleTargetKnown(bot *BotSession, target string) (string, bool) {
	if bot == nil {
		return "", false
	}
	if id, ok := bot.tradeVerifiedItemID(target); ok {
		return id, true
	}
	key := normaliseDropAliasKey(target)
	if key == "" {
		return "", false
	}
	bot.mu.Lock()
	if id := bot.DropItemAliases[key]; id != "" {
		bot.mu.Unlock()
		return bot.resolveRegisteredDropVariant(id), true
	}
	bot.mu.Unlock()
	if id, ok := bot.inventoryItemIDByVisibleName(target); ok {
		bot.mu.Lock()
		addDropAlias(bot.DropItemAliases, target, id)
		bot.mu.Unlock()
		return id, true
	}
	bot.mu.Lock()
	// 原始 minecraft:id / 英文短 ID / 中文 canonical ID 先正規化，
	// 再接受同一家族的 Bedrock variant（例如 light_block_15）。
	candidate := normaliseCollectItemName(target)
	bot.mu.Unlock()
	candidate = bot.resolveRegisteredDropVariant(candidate)

	bot.mu.Lock()
	known := false
	for _, id := range bot.MapArtItemNames {
		if dropItemVariantScore(candidate, strings.TrimSpace(id)) >= 700 {
			known = true
			break
		}
	}
	bot.mu.Unlock()
	return candidate, known
}

func autoDropRuleTargetForSave(bot *BotSession, target string) string {
	target = strings.TrimSpace(clean(target))
	if target == "" {
		return ""
	}
	if target == "*" || strings.EqualFold(target, "all") || target == "全部" {
		return "*"
	}

	// Highest priority: exact ID already proven by purchase auto-drop.
	if bot != nil {
		if id, ok := bot.tradeVerifiedItemID(target); ok && strings.TrimSpace(id) != "" {
			return strings.ToLower(strings.TrimSpace(id))
		}
		if id, known := autoDropRuleTargetKnown(bot, target); known && strings.TrimSpace(id) != "" {
			return strings.ToLower(strings.TrimSpace(id))
		}
	}

	// Do NOT invent minecraft:<display-name>. Save the normalised display name
	// itself. When the item enters the backpack, live NBT/alias learning will
	// resolve this rule to the real server ID.
	return normaliseDropAliasKey(target)
}

func autoDropRuleLookupKeys(bot *BotSession, target string) []string {
	target = strings.TrimSpace(clean(target))
	seen := map[string]bool{}
	out := make([]string, 0, 8)
	add := func(v string) {
		v = strings.TrimSpace(v)
		if v == "" || seen[v] {
			return
		}
		seen[v] = true
		out = append(out, v)
	}

	add(target)
	add(normaliseDropAliasKey(target))
	add(strings.ToLower(strings.TrimSpace(target)))
	add(autoDropRuleTargetForSave(bot, target))

	if bot != nil {
		if id, ok := bot.tradeVerifiedItemID(target); ok {
			add(id)
		}
		if id, known := autoDropRuleTargetKnown(bot, target); known {
			add(id)
		}
	}
	return out
}

func (bot *BotSession) backpackAutoDropMustYieldLocked() bool {
	if bot == nil {
		return false
	}
	if bedrockExclusiveControlActiveLocked(bot) {
		owner := bedrockCurrentControlOwnerLocked(bot)
		if !(owner == "collect" && bot.AutoDropSafePoint) {
			return true
		}
	}
	if !bot.TradeAutoDropEnabled {
		return false
	}
	if bot.TradeAutoDropArmed || bot.TradeAutoDropRunning || len(bot.TradeAutoDropQueue) > 0 {
		return true
	}
	// While navigating/confirming a purchase, keep the normal backpack worker
	// out of the inventory. During repeat_wait it may run between purchases.
	return strings.TrimSpace(bot.WantExchangeItem) != "" && bot.PurchasePhase != purchasePhaseRepeatWait
}

// Only controls WHEN the original backpack worker starts. It never changes the
// worker itself or the Bedrock drop request implementation.
func (bot *BotSession) triggerBackpackAutoDropFromInventoryUpdate() {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	if !bot.backpackAutoDropMustYieldLocked() {
		bot.mu.Unlock()
		bot.triggerAutoDrop()
		return
	}
	bot.AutoDropDirty = true
	if bot.AutoDropResumePending {
		bot.mu.Unlock()
		return
	}
	bot.AutoDropResumePending = true
	bot.mu.Unlock()

	go func() {
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		for range ticker.C {
			bot.mu.Lock()
			if !bot.AutoDropEnabled || len(bot.AutoDropRules) == 0 || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
				bot.AutoDropResumePending = false
				bot.mu.Unlock()
				return
			}
			if !bot.backpackAutoDropMustYieldLocked() {
				bot.AutoDropResumePending = false
				shouldRun := bot.AutoDropDirty
				bot.mu.Unlock()
				if shouldRun {
					bot.triggerAutoDrop()
				}
				return
			}
			bot.mu.Unlock()
		}
	}()
}

type autoDropServerItemOption struct {
	ID      string   `json:"id"`
	Label   string   `json:"label"`
	Custom  bool     `json:"custom"`
	Aliases []string `json:"aliases,omitempty"`
}

func autoDropAliasLooksDisplayName(alias, id string) bool {
	alias = strings.TrimSpace(clean(alias))
	if alias == "" || strings.EqualFold(alias, id) ||
		strings.EqualFold(alias, strings.TrimPrefix(id, "minecraft:")) {
		return false
	}
	if strings.Contains(alias, "{") || strings.Contains(alias, "}") ||
		strings.Contains(alias, "[") || strings.Contains(alias, "]") ||
		len([]rune(alias)) > 64 {
		return false
	}
	return true
}

// autoDropServerItemOptionsLocked returns only item IDs that the currently
// connected server actually registered in GameData().Items.
// Caller must hold bot.mu.
func (bot *BotSession) autoDropServerItemOptionsLocked() []autoDropServerItemOption {
	if bot == nil || len(bot.MapArtItemNames) == 0 {
		return []autoDropServerItemOption{}
	}

	ids := make([]string, 0, len(bot.MapArtItemNames))
	seenIDs := map[string]bool{}
	for _, rawID := range bot.MapArtItemNames {
		id := strings.ToLower(strings.TrimSpace(rawID))
		if id == "" || seenIDs[id] {
			continue
		}
		seenIDs[id] = true
		ids = append(ids, id)
	}
	sort.Strings(ids)

	aliasesByID := make(map[string][]string, len(ids))
	for alias, rawID := range bot.DropItemAliases {
		id := strings.ToLower(strings.TrimSpace(rawID))
		if !seenIDs[id] {
			continue
		}
		alias = strings.TrimSpace(clean(alias))
		if !autoDropAliasLooksDisplayName(alias, id) {
			continue
		}
		aliasesByID[id] = append(aliasesByID[id], alias)
	}

	options := make([]autoDropServerItemOption, 0, len(ids))
	for _, id := range ids {
		aliases := aliasesByID[id]
		sort.SliceStable(aliases, func(i, j int) bool {
			ai, aj := aliases[i], aliases[j]
			iNonASCII := strings.IndexFunc(ai, func(r rune) bool { return r > 127 }) >= 0
			jNonASCII := strings.IndexFunc(aj, func(r rune) bool { return r > 127 }) >= 0
			if iNonASCII != jNonASCII {
				return iNonASCII
			}
			ri, rj := len([]rune(ai)), len([]rune(aj))
			if ri != rj {
				return ri < rj
			}
			return ai < aj
		})

		uniq := make([]string, 0, minInt(len(aliases), 12))
		seen := map[string]bool{}
		for _, alias := range aliases {
			key := normaliseDropAliasKey(alias)
			if key == "" || seen[key] {
				continue
			}
			seen[key] = true
			uniq = append(uniq, alias)
			if len(uniq) >= 12 {
				break
			}
		}

		label := strings.TrimPrefix(id, "minecraft:")
		if len(uniq) > 0 {
			label = uniq[0]
		} else if !strings.HasPrefix(id, "minecraft:") {
			// Custom server/add-on items may have no translated display name in
			// StartGame. The registered namespace:id is still authoritative.
			label = id
		}
		options = append(options, autoDropServerItemOption{
			ID:      id,
			Label:   label,
			Custom:  !strings.HasPrefix(id, "minecraft:"),
			Aliases: uniq,
		})
	}

	sort.SliceStable(options, func(i, j int) bool {
		if options[i].Custom != options[j].Custom {
			return options[i].Custom // custom/server items first
		}
		li := normaliseDropAliasKey(options[i].Label)
		lj := normaliseDropAliasKey(options[j].Label)
		if li != lj {
			return li < lj
		}
		return options[i].ID < options[j].ID
	})
	return options
}

func (bot *BotSession) resolveRegisteredAutoDropItem(target string) (string, string, bool) {
	if bot == nil {
		return "", "", false
	}
	target = strings.TrimSpace(clean(target))
	key := normaliseDropAliasKey(target)
	if key == "" {
		return "", "", false
	}

	bot.mu.Lock()
	defer bot.mu.Unlock()

	registered := map[string]bool{}
	for _, rawID := range bot.MapArtItemNames {
		id := strings.ToLower(strings.TrimSpace(rawID))
		if id != "" {
			registered[id] = true
		}
	}

	// Exact registered namespace:id.
	rawLower := strings.ToLower(strings.TrimSpace(target))
	if registered[rawLower] {
		label := strings.TrimPrefix(rawLower, "minecraft:")
		for alias, mapped := range bot.DropItemAliases {
			if strings.EqualFold(strings.TrimSpace(mapped), rawLower) &&
				autoDropAliasLooksDisplayName(alias, rawLower) &&
				strings.IndexFunc(alias, func(r rune) bool { return r > 127 }) >= 0 {
				label = clean(alias)
				break
			}
		}
		return rawLower, label, true
	}

	// Exact alias learned from this server's registry / vanilla translation /
	// real ItemStack NBT / verified purchase receipt.
	if mapped := strings.ToLower(strings.TrimSpace(bot.DropItemAliases[key])); registered[mapped] {
		return mapped, target, true
	}

	// Short ID match is allowed only when it resolves uniquely in the server registry.
	shortMatches := make([]string, 0, 2)
	for id := range registered {
		short := strings.TrimPrefix(id, "minecraft:")
		if normaliseDropAliasKey(short) == key ||
			normaliseDropAliasKey(strings.ReplaceAll(short, "_", " ")) == key {
			shortMatches = append(shortMatches, id)
		}
	}
	if len(shortMatches) == 1 {
		return shortMatches[0], target, true
	}
	return "", "", false
}

func tradeVerifiedAliasCandidates(value string) []string {
	value = strings.TrimSpace(clean(value))
	if value == "" {
		return nil
	}

	seen := map[string]bool{}
	out := make([]string, 0, 16)
	add := func(v string) {
		v = normaliseDropAliasKey(v)
		v = strings.Trim(v, " :：-—|>→⇒»[]【】()（）")
		v = strings.TrimSpace(v)
		if v == "" || seen[v] {
			return
		}
		seen[v] = true
		out = append(out, v)
	}

	add(value)

	// Full automation target: "分類 > 商品".
	if _, itemText := splitPurchaseTarget(value); strings.TrimSpace(itemText) != "" {
		add(itemText)
		if parsed, ok := parseHelperTradeOutput(itemText); ok {
			add(parsed.Item)
		}
	}
	if parsed, ok := parseHelperTradeOutput(value); ok {
		add(parsed.Item)
	}

	// Also remember individual display lines. Form buttons often add price/count
	// on another line while the lower auto-drop input uses only the item name.
	for _, line := range strings.FieldsFunc(value, func(r rune) bool {
		switch r {
		case '\n', '\r', '|', '｜', '>', '→', '⇒', '»':
			return true
		default:
			return false
		}
	}) {
		add(line)
	}

	// Strip common quantity/price decoration without changing the actual item
	// word. Keep the original candidates above as the strongest aliases.
	cleaned := normaliseDropAliasKey(value)
	cleaned = regexp.MustCompile(`(?i)\s*[x×]\s*[\d,]+\s*$`).ReplaceAllString(cleaned, "")
	cleaned = regexp.MustCompile(`\s*[\d,]+\s*(?:個|顆|颗|份|枚|組|组|塊|块)\s*$`).ReplaceAllString(cleaned, "")
	cleaned = regexp.MustCompile(`\s*[\(（\[]\s*[\d,]+\s*[\)）\]]\s*$`).ReplaceAllString(cleaned, "")
	add(cleaned)

	// Do the same for each already extracted alias.
	base := append([]string(nil), out...)
	for _, alias := range base {
		v := regexp.MustCompile(`(?i)\s*[x×]\s*[\d,]+\s*$`).ReplaceAllString(alias, "")
		v = regexp.MustCompile(`\s*[\d,]+\s*(?:個|顆|颗|份|枚|組|组|塊|块)\s*$`).ReplaceAllString(v, "")
		v = regexp.MustCompile(`\s*[\(（\[]\s*[\d,]+\s*[\)）\]]\s*$`).ReplaceAllString(v, "")
		add(v)
	}

	return out
}

func (bot *BotSession) rememberTradeVerifiedItemID(displayName, target, itemID string) {
	if bot == nil {
		return
	}
	itemID = strings.ToLower(strings.TrimSpace(itemID))
	if itemID == "" || !strings.Contains(itemID, ":") {
		return
	}

	aliases := make([]string, 0, 32)
	aliases = append(aliases, tradeVerifiedAliasCandidates(itemID)...)
	aliases = append(aliases, tradeVerifiedAliasCandidates(strings.TrimPrefix(itemID, "minecraft:"))...)
	aliases = append(aliases, tradeVerifiedAliasCandidates(displayName)...)
	aliases = append(aliases, tradeVerifiedAliasCandidates(target)...)

	_, itemText := splitPurchaseTarget(target)
	aliases = append(aliases, tradeVerifiedAliasCandidates(itemText)...)
	if parsed, ok := parseHelperTradeOutput(itemText); ok {
		aliases = append(aliases, tradeVerifiedAliasCandidates(parsed.Item)...)
	}

	bot.mu.Lock()
	aliasCountBefore := len(bot.DropItemAliases)
	if bot.TradeVerifiedItemIDs == nil {
		bot.TradeVerifiedItemIDs = map[string]string{}
	}
	if bot.DropItemAliases == nil {
		bot.DropItemAliases = map[string]string{}
	}

	for _, alias := range aliases {
		key := normaliseDropAliasKey(alias)
		if key == "" {
			continue
		}
		// This mapping is backed by an actual positive inventory delta from the
		// purchase receipt watcher, so it is stronger than a guessed alias.
		bot.TradeVerifiedItemIDs[key] = itemID
		bot.DropItemAliases[key] = itemID
	}
	if len(bot.DropItemAliases) != aliasCountBefore {
		bot.AutoDropRegistryGeneration++
	}
	bot.mu.Unlock()
}

func (bot *BotSession) tradeVerifiedItemID(target string) (string, bool) {
	if bot == nil {
		return "", false
	}
	candidates := tradeVerifiedAliasCandidates(target)
	if len(candidates) == 0 {
		return "", false
	}

	bot.mu.Lock()
	verified := make(map[string]string, len(bot.TradeVerifiedItemIDs))
	for key, id := range bot.TradeVerifiedItemIDs {
		verified[key] = strings.ToLower(strings.TrimSpace(id))
	}
	bot.mu.Unlock()

	// Exact aliases first.
	for _, candidate := range candidates {
		key := normaliseDropAliasKey(candidate)
		if id := verified[key]; id != "" {
			return id, true
		}
	}

	// Then allow a UNIQUE containment match. This handles forms such as
	// "✦ 物品名稱 ✦ x1" versus lower input "物品名稱", but refuses to guess if
	// the same text could refer to multiple verified item IDs.
	matchedID := ""
	for _, candidate := range candidates {
		q := normaliseDropAliasKey(candidate)
		if len([]rune(q)) < 2 {
			continue
		}
		for alias, id := range verified {
			if id == "" || len([]rune(alias)) < 2 {
				continue
			}
			if !strings.Contains(alias, q) && !strings.Contains(q, alias) {
				continue
			}
			if matchedID == "" {
				matchedID = id
				continue
			}
			if matchedID != id {
				// More than one real ID matches: fail closed instead of dropping
				// the wrong item.
				return "", false
			}
		}
	}
	return matchedID, matchedID != ""
}

func (bot *BotSession) backpackInventoryFullLocked() bool {
	if bot == nil || !bot.MapArtInventoryReady || len(bot.MapArtInventory) < 36 {
		return false
	}
	for slot := 0; slot < 36; slot++ {
		if bot.MapArtInventory[slot].Stack.Count == 0 {
			return false
		}
	}
	return true
}

func (bot *BotSession) stopPurchaseForFullInventory(conn *minecraft.Conn, formID uint32, generation uint64, activeWant string) bool {
	if bot == nil {
		return false
	}
	if formID != 0 {
		closePurchaseForm(conn, formID)
	}
	bot.mu.Lock()
	if bot.OperationGeneration != generation || strings.TrimSpace(bot.WantExchangeItem) != strings.TrimSpace(activeWant) {
		bot.mu.Unlock()
		return false
	}
	bot.RepeatExchange = false
	bot.WantExchangeItem = ""
	bot.OperationCurrent = "自動購買：" + activeWant
	bot.OperationResult = "❌ 背包已滿，停止購買"
	bot.setTradeOutcomeLocked("failure", activeWant, bot.OperationResult)
	bot.resetPurchaseStateLocked()
	if bot.LastFormID == formID {
		bot.LastFormID = 0
	}
	bot.mu.Unlock()
	bot.AddSystemLog("❌ 背包已滿，停止購買")
	return true
}

func (bot *BotSession) sanitizeAutoDropRulesToRegistry() {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	old := make(map[string]int, len(bot.AutoDropRules))
	for key, keep := range bot.AutoDropRules {
		old[key] = keep
	}
	bot.mu.Unlock()

	if len(old) == 0 {
		return
	}

	next := make(map[string]int, len(old))
	changed := false
	for key, keep := range old {
		// "*" is the existing wildcard understood by the unchanged drop core.
		// It is an intentional special rule, not a server registry Item ID.
		if strings.TrimSpace(key) == "*" {
			next["*"] = 0
			if keep != 0 {
				changed = true
			}
			continue
		}
		id, _, known := bot.resolveRegisteredAutoDropItem(key)
		if !known || id == "" {
			// Broken/old guessed rule is intentionally removed. It can never
			// reach the drop worker again.
			changed = true
			continue
		}
		if id != key {
			changed = true
		}
		if existing, ok := next[id]; !ok || keep > existing {
			next[id] = keep
		}
	}
	if !changed {
		return
	}

	bot.mu.Lock()
	bot.AutoDropRules = next
	bot.AutoDropDirty = true
	bot.mu.Unlock()
	bot.AddSystemLog("背包自動丟：已清除/修正舊的非伺服器 Item ID 規則")
}

func autoDropInventoryCount(bot *BotSession, itemID string) int {
	if bot == nil {
		return 0
	}

	// A rule may have been saved by display name before its ID was known.
	// Resolve it now from purchase-verified IDs / live NBT aliases / registry.
	original := strings.TrimSpace(itemID)
	if id, ok := bot.tradeVerifiedItemID(original); ok {
		itemID = id
	} else {
		itemID = bot.resolveDropItemTarget(original)
	}
	itemID = strings.ToLower(strings.TrimSpace(itemID))

	bot.mu.Lock()
	defer bot.mu.Unlock()
	total := 0
	for i, item := range bot.MapArtInventory {
		if i >= 36 || item.Stack.Count == 0 {
			continue
		}
		name := bedrockItemIdentityLocked(bot, item)
		if collectDropItemMatches(itemID, name) {
			total += int(item.Stack.Count)
		}
	}
	return total
}

func autoDropRulesSummary(bot *BotSession) string {
	if bot == nil {
		return "自動丟不可用"
	}
	bot.mu.Lock()
	enabled := bot.AutoDropEnabled
	rules := make(map[string]int, len(bot.AutoDropRules))
	for id, keep := range bot.AutoDropRules {
		rules[id] = keep
	}
	aliases := make(map[string]string, len(bot.DropItemAliases))
	for alias, id := range bot.DropItemAliases {
		aliases[alias] = id
	}
	bot.mu.Unlock()

	state := "關"
	if enabled {
		state = "開"
	}
	if len(rules) == 0 {
		return "自動丟：" + state + "；目前沒有規則"
	}
	ids := make([]string, 0, len(rules))
	for id := range rules {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	parts := make([]string, 0, len(ids))
	for _, id := range ids {
		label := strings.TrimPrefix(id, "minecraft:")
		if id == "*" {
			label = "全部物品"
		}
		for alias, mapped := range aliases {
			if mapped == id && alias != label && alias != id && strings.IndexFunc(alias, func(r rune) bool { return r > 127 }) >= 0 {
				label = alias
				break
			}
		}
		keep := rules[id]
		if keep > 0 {
			parts = append(parts, fmt.Sprintf("%s(保留%d)", label, keep))
		} else {
			parts = append(parts, label+"(全丟)")
		}
	}
	return fmt.Sprintf("自動丟：%s；%s", state, strings.Join(parts, "、"))
}

// triggerAutoDrop 只排一個 worker；背包在 worker 執行期間再次更新時只標 dirty，
// 不會再開第二個丟棄 goroutine 去搶 ItemStackRequest。
func (bot *BotSession) triggerAutoDrop() {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	// destructive action: rules may exist while disabled; only explicit enabled state may run them.
	if bedrockExclusiveControlActiveLocked(bot) {
		owner := bedrockCurrentControlOwnerLocked(bot)
		if !(owner == "collect" && bot.AutoDropSafePoint) {
			bot.AutoDropDirty = true
			bot.mu.Unlock()
			return
		}
	}
	if !bot.AutoDropEnabled || len(bot.AutoDropRules) == 0 || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return
	}
	if bot.AutoDropRunning {
		bot.AutoDropDirty = true
		bot.mu.Unlock()
		return
	}
	bot.AutoDropRunning = true
	bot.AutoDropDirty = false
	bot.mu.Unlock()

	go bot.runAutoDropWorker()
}

func (bot *BotSession) runAutoDropWorker() {
	defer func() {
		bot.mu.Lock()
		bot.AutoDropRunning = false
		again := bot.AutoDropDirty && bot.AutoDropEnabled && len(bot.AutoDropRules) > 0 &&
			bot.Connected && bot.PlayerReady && !bot.Respawning.Load()
		bot.AutoDropDirty = false
		bot.mu.Unlock()
		if again {
			bot.triggerAutoDrop()
		}
	}()

	// 一個 worker 最多重掃幾輪，讓同物品分散在多格時也能一次清乾淨。
	for pass := 0; pass < 4; pass++ {
		bot.mu.Lock()
		blockedByControl := false
		if bedrockExclusiveControlActiveLocked(bot) {
			owner := bedrockCurrentControlOwnerLocked(bot)
			blockedByControl = !(owner == "collect" && bot.AutoDropSafePoint)
		}
		if blockedByControl || !bot.AutoDropEnabled || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
			if blockedByControl {
				bot.AutoDropDirty = true
			}
			bot.mu.Unlock()
			return
		}
		rules := make(map[string]int, len(bot.AutoDropRules))
		for id, keep := range bot.AutoDropRules {
			rules[id] = keep
		}
		bot.AutoDropDirty = false
		bot.mu.Unlock()

		changed := false
		ids := make([]string, 0, len(rules))
		for id := range rules {
			ids = append(ids, id)
		}
		sort.Strings(ids)

		for _, id := range ids {
			keep := rules[id]
			have := autoDropInventoryCount(bot, id)
			excess := have - keep
			if excess <= 0 {
				continue
			}

			dropTarget := id
			if verified, ok := bot.tradeVerifiedItemID(id); ok {
				dropTarget = verified
			} else {
				dropTarget = bot.resolveDropItemTarget(id)
			}

			ctx, cancel := context.WithTimeout(context.Background(), 15*time.Second)
			dropped, err := dropBedrockInventoryItem(ctx, bot, dropTarget, excess)
			cancel()
			if err != nil {
				bot.AddSystemLog(fmt.Sprintf("自動丟 %s 失敗：%v", strings.TrimPrefix(id, "minecraft:"), err))
				// 協定/伺服器暫時拒絕時不要高速重試。
				return
			}
			if dropped > 0 {
				changed = true
				bot.AddSystemLog(fmt.Sprintf("自動丟 %s × %d", strings.TrimPrefix(id, "minecraft:"), dropped))
			}
		}

		bot.mu.Lock()
		dirty := bot.AutoDropDirty
		bot.mu.Unlock()
		if !changed && !dirty {
			return
		}
		select {
		case <-time.After(180 * time.Millisecond):
		}
	}
}

func dropBedrockInventoryItem(ctx context.Context, bot *BotSession, target string, requested int) (int, error) {
	if bot == nil {
		return 0, errors.New("找不到 BOT")
	}
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	target = strings.TrimSpace(target)
	if target == "" {
		return 0, errors.New("缺少要丟棄的物品")
	}
	originalTarget := target
	target = bot.resolveDropItemTarget(target)
	totalDropped := 0
	for {
		if err := ctx.Err(); err != nil {
			return totalDropped, err
		}
		bot.mu.Lock()
		connected := bot.Connected && bot.conn != nil && bot.PlayerReady && !bot.Respawning.Load()
		conn := bot.conn
		ready := bot.MapArtInventoryReady
		inventoryLen := len(bot.MapArtInventory)
		bot.mu.Unlock()
		if !connected || conn == nil {
			return totalDropped, errors.New("BOT 尚未完成登入/出生")
		}
		if !ready || inventoryLen == 0 {
			return totalDropped, errors.New("背包資料尚未同步，請等 BOT 進服後再試")
		}

		remaining := requested - totalDropped
		if requested > 0 && remaining <= 0 {
			return totalDropped, nil
		}
		matches, _ := bot.bedrockSearchInventory(target, remaining)
		matchSlot := -1
		dropCount := 0
		var source protocol.ItemInstance
		if len(matches) > 0 {
			matchSlot = matches[0].Slot
			source = matches[0].Item
			dropCount = matches[0].Count
		}
		if matchSlot < 0 {
			if totalDropped > 0 {
				return totalDropped, nil
			}
			hints := bot.inventoryItemHints(12)
			if hints != "" {
				return 0, fmt.Errorf("背包找不到 %s（辨識為 %s）；目前物品：%s", originalTarget, target, hints)
			}
			return 0, fmt.Errorf("背包找不到 %s（辨識為 %s）", originalTarget, target)
		}
		if dropCount <= 0 || dropCount > 255 {
			return totalDropped, fmt.Errorf("無效的丟棄數量 %d", dropCount)
		}

		req, pending, err := bot.bedrockBuildDropRequest(matchSlot, source, dropCount)
		if err != nil {
			// 背包剛好在掃描與送出之間更新：重新掃一次，而不是拿舊 StackNetworkID 硬送。
			if totalDropped > 0 {
				return totalDropped, nil
			}
			continue
		}
		sourceContainer := pending.SourceContainer
		if _, err := bot.bedrockSendStackRequest(ctx, conn, req, pending, 3500*time.Millisecond); err != nil {
			return totalDropped, fmt.Errorf(
				"丟棄失敗（slot=%d container=0x%02x stackNetID=%d）：%w",
				matchSlot, sourceContainer.ContainerID, source.StackNetworkID, err,
			)
		}
		totalDropped += dropCount
		// ItemStackResponse 已核准，立即更新本地鏡像，避免下一輪在
		// InventorySlot 還沒抵達前又拿同一個舊 StackNetworkID/數量重送。
		bot.mu.Lock()
		if matchSlot >= 0 && matchSlot < len(bot.MapArtInventory) && bot.MapArtInventory[matchSlot].StackNetworkID == source.StackNetworkID {
			if int(bot.MapArtInventory[matchSlot].Stack.Count) <= dropCount {
				bot.MapArtInventory[matchSlot] = protocol.ItemInstance{}
			} else {
				bot.MapArtInventory[matchSlot].Stack.Count -= uint16(dropCount)
			}
		}
		bot.mu.Unlock()
		select {
		case <-ctx.Done():
			return totalDropped, ctx.Err()
		case <-time.After(80 * time.Millisecond):
		}
	}
}

type appInventoryItemView struct {
	Ref            string   `json:"ref"`
	Area           string   `json:"area"`
	Slot           int      `json:"slot"`
	LogicalSlot    int      `json:"logical_slot"`
	ID             string   `json:"id"`
	Label          string   `json:"label"`
	IconURL        string   `json:"icon_url,omitempty"`
	IconTexture    string   `json:"-"`
	Count          int      `json:"count"`
	NetworkID      int32    `json:"network_id"`
	StackNetworkID int32    `json:"stack_network_id"`
	Metadata       uint32   `json:"metadata"`
	Lore           []string `json:"lore,omitempty"`
	MapID          int64    `json:"map_id,omitempty"`
	HasMap         bool     `json:"has_map,omitempty"`
	Empty          bool     `json:"empty"`
}

func stableItemDisplayNameLocked(bot *BotSession, id string) string {
	id = strings.ToLower(strings.TrimSpace(id))
	if id == "" {
		return ""
	}
	label := strings.TrimPrefix(id, "minecraft:")
	aliases := make([]string, 0, 8)
	for alias, mapped := range bot.DropItemAliases {
		if mapped != id || strings.EqualFold(alias, id) || strings.EqualFold(alias, label) {
			continue
		}
		if strings.IndexFunc(alias, func(r rune) bool { return r > 127 }) < 0 {
			continue
		}
		alias = strings.TrimSpace(clean(alias))
		if alias != "" && len([]rune(alias)) <= 48 {
			aliases = append(aliases, alias)
		}
	}
	if len(aliases) == 0 {
		return label
	}
	sort.Slice(aliases, func(i, j int) bool {
		ri, rj := len([]rune(aliases[i])), len([]rune(aliases[j]))
		if ri != rj {
			return ri < rj
		}
		return aliases[i] < aliases[j]
	})
	return aliases[0]
}

func inventoryNBTDisplayName(item protocol.ItemInstance) string {
	nbt := item.Stack.NBTData
	if len(nbt) == 0 {
		return ""
	}
	readName := func(v interface{}) string {
		switch t := v.(type) {
		case string:
			return clean(t)
		case []byte:
			return clean(string(t))
		default:
			return ""
		}
	}
	for _, key := range []string{"display", "Display"} {
		if raw, ok := nbt[key]; ok {
			if d, ok := raw.(map[string]interface{}); ok {
				for _, nameKey := range []string{"Name", "name"} {
					if s := readName(d[nameKey]); s != "" {
						return s
					}
				}
			}
		}
	}
	for _, key := range []string{"Name", "name", "CustomName", "custom_name"} {
		if s := readName(nbt[key]); s != "" {
			return s
		}
	}
	return ""
}

// inventoryNBTIdentifier is a fallback for proxy/plugin supplied items whose
// numeric runtime ID is missing from the advertised ItemRegistry. Several
// Bedrock server stacks preserve the real namespaced identifier in item NBT.
func inventoryNBTIdentifier(item protocol.ItemInstance) string {
	var find func(map[string]any, int) string
	find = func(values map[string]any, depth int) string {
		if depth > 5 || len(values) == 0 {
			return ""
		}
		for _, key := range []string{"identifier", "Identifier", "item_identifier", "itemIdentifier", "item_id", "ItemId", "itemID", "id"} {
			raw, ok := values[key]
			if !ok {
				continue
			}
			if value, ok := raw.(string); ok {
				value = strings.ToLower(strings.TrimSpace(clean(value)))
				if strings.Contains(value, ":") && !strings.ContainsAny(value, "{}[]\n\r") {
					return value
				}
			}
		}
		for _, raw := range values {
			if nested, ok := raw.(map[string]any); ok {
				if value := find(nested, depth+1); value != "" {
					return value
				}
			}
		}
		return ""
	}
	return find(item.Stack.NBTData, 0)
}

func inventoryNBTLore(item protocol.ItemInstance) []string {
	read := func(raw interface{}) []string {
		out := []string{}
		switch values := raw.(type) {
		case []string:
			for _, value := range values {
				if value = strings.TrimSpace(clean(value)); value != "" {
					out = append(out, value)
				}
			}
		case []interface{}:
			for _, rawValue := range values {
				if value, ok := rawValue.(string); ok {
					if value = strings.TrimSpace(clean(value)); value != "" {
						out = append(out, value)
					}
				}
			}
		}
		return out
	}
	nbt := item.Stack.NBTData
	for _, displayKey := range []string{"display", "Display"} {
		if display, ok := nbt[displayKey].(map[string]interface{}); ok {
			for _, loreKey := range []string{"Lore", "lore"} {
				if lore := read(display[loreKey]); len(lore) > 0 {
					return lore
				}
			}
		}
	}
	for _, loreKey := range []string{"Lore", "lore"} {
		if lore := read(nbt[loreKey]); len(lore) > 0 {
			return lore
		}
	}
	return nil
}

func inventoryNBTMapID(item protocol.ItemInstance) (int64, bool) {
	toInt64 := func(raw interface{}) (int64, bool) {
		switch value := raw.(type) {
		case int64:
			return value, true
		case int32:
			return int64(value), true
		case int:
			return int64(value), true
		case uint64:
			return int64(value), value <= uint64(1<<63-1)
		case uint32:
			return int64(value), true
		case float64:
			return int64(value), value == math.Trunc(value)
		case string:
			parsed, err := strconv.ParseInt(strings.TrimSpace(value), 10, 64)
			return parsed, err == nil
		default:
			return 0, false
		}
	}
	var find func(map[string]interface{}, int) (int64, bool)
	find = func(values map[string]interface{}, depth int) (int64, bool) {
		if depth > 5 {
			return 0, false
		}
		for _, key := range []string{"map_uuid", "mapUUID", "map_id", "mapId", "MapId", "MapID"} {
			if value, ok := toInt64(values[key]); ok {
				return value, true
			}
		}
		for _, raw := range values {
			if nested, ok := raw.(map[string]interface{}); ok {
				if value, found := find(nested, depth+1); found {
					return value, true
				}
			}
		}
		return 0, false
	}
	return find(item.Stack.NBTData, 0)
}

func inventoryNBTIconTextureKeyV121(item protocol.ItemInstance) string {
	wanted := map[string]bool{"minecraft:icon": true, "icon": true, "texture": true, "texture_key": true, "texturekey": true, "texture_name": true, "texturename": true, "item_texture": true, "itemtexture": true, "custom_texture": true}
	var walk func(interface{}, int) string
	walk = func(v interface{}, depth int) string {
		if depth > 7 {
			return ""
		}
		switch t := v.(type) {
		case map[string]interface{}:
			for k, x := range t {
				if wanted[strings.ToLower(strings.TrimSpace(k))] {
					if got := strings.TrimSpace(itemIconTextureKey(x)); got != "" && len(got) <= 256 {
						return got
					}
				}
			}
			for _, x := range t {
				if got := walk(x, depth+1); got != "" {
					return got
				}
			}
		case []interface{}:
			for _, x := range t {
				if got := walk(x, depth+1); got != "" {
					return got
				}
			}
		}
		return ""
	}
	return walk(item.Stack.NBTData, 0)
}

// bedrockItemIdentityLocked is the single identity order used by UI and
// automation. Callers must hold bot.mu because registry maps are updated by the
// packet reader. Proxy/plugin items may only expose their identifier through NBT.
func bedrockItemIdentityLocked(bot *BotSession, item protocol.ItemInstance) string {
	if bot == nil || item.Stack.Count == 0 {
		return ""
	}
	id := strings.ToLower(strings.TrimSpace(bot.MapArtItemNames[item.Stack.NetworkID]))
	if id == "" {
		id = inventoryNBTIdentifier(item)
	}
	if id == "" && item.Stack.BlockRuntimeID >= 0 {
		id = strings.ToLower(strings.TrimSpace(bot.MapArtBlockNames[uint32(item.Stack.BlockRuntimeID)]))
	}
	return id
}

func appInventoryItemViewLocked(bot *BotSession, area string, slot, logical int, item protocol.ItemInstance) appInventoryItemView {
	view := appInventoryItemView{Ref: fmt.Sprintf("%s:%d", area, slot), Area: area, Slot: slot, LogicalSlot: logical, Empty: item.Stack.Count == 0}
	if item.Stack.Count == 0 {
		return view
	}
	id := bedrockItemIdentityLocked(bot, item)
	view.ID = id
	view.Label = inventoryNBTDisplayName(item)
	if view.Label == "" {
		view.Label = stableItemDisplayNameLocked(bot, id)
	}
	if view.Label == "" {
		view.Label = fmt.Sprintf("未知物品 #%d", item.Stack.NetworkID)
	}
	textureKey := strings.TrimSpace(bot.MapArtItemIconKeys[item.Stack.NetworkID])
	if textureKey == "" {
		textureKey = inventoryNBTIconTextureKeyV121(item)
	}
	view.IconTexture = textureKey
	view.Metadata = item.Stack.MetadataValue
	if id != "" || textureKey != "" || view.Label != "" {
		view.IconURL = "/api/item-icon?bot=" + strconv.Itoa(bot.ID) +
			"&id=" + url.QueryEscape(id) +
			"&label=" + url.QueryEscape(view.Label) +
			"&texture=" + url.QueryEscape(textureKey) +
			"&meta=" + strconv.FormatUint(uint64(view.Metadata), 10)
	}
	view.Count = int(item.Stack.Count)
	view.NetworkID = item.Stack.NetworkID
	view.StackNetworkID = item.StackNetworkID
	view.Lore = inventoryNBTLore(item)
	if mapID, ok := inventoryNBTMapID(item); ok {
		view.MapID = mapID
		view.HasMap = true
	}
	return view
}

func appInventorySnapshot(bot *BotSession) map[string]interface{} {
	if bot == nil {
		return map[string]interface{}{"ok": false, "error": "找不到機器人"}
	}
	bot.mu.Lock()

	slots := make([]appInventoryItemView, 36)
	used := 0
	for i := 0; i < 36; i++ {
		var item protocol.ItemInstance
		if i < len(bot.MapArtInventory) {
			item = bot.MapArtInventory[i]
		}
		slots[i] = appInventoryItemViewLocked(bot, "inventory", i, i, item)
		if item.Stack.Count > 0 {
			used++
		}
	}

	armourNames := []string{"helmet", "chest", "legs", "feet"}
	armour := make([]appInventoryItemView, 4)
	armourRaw := []int{0, 1, 2, 3}
	if len(bot.MapArtArmourInventory) >= 6 {
		armourRaw = []int{2, 3, 4, 5}
	}
	for i := 0; i < 4; i++ {
		raw := armourRaw[i]
		var item protocol.ItemInstance
		if raw >= 0 && raw < len(bot.MapArtArmourInventory) {
			item = bot.MapArtArmourInventory[raw]
		}
		view := appInventoryItemViewLocked(bot, "armour", raw, i, item)
		view.Area = armourNames[i]
		armour[i] = view
	}

	var offhand protocol.ItemInstance
	if len(bot.MapArtOffhandInventory) > 0 {
		offhand = bot.MapArtOffhandInventory[0]
	}
	offhandView := appInventoryItemViewLocked(bot, "offhand", 0, 0, offhand)
	cursorView := appInventoryItemViewLocked(bot, "cursor", 0, 0, bot.MapArtCursor)
	// The player inventory always has a 2x2 crafting grid and one preview slot.
	// Expose all five refs even before the server sends their first empty-content
	// packet so the Web UI can immediately accept drag/drop operations.
	crafting := make([]appInventoryItemView, 4)
	for i := 0; i < 4; i++ {
		var item protocol.ItemInstance
		if i < len(bot.MapArtCraftingInput) {
			item = bot.MapArtCraftingInput[i]
		}
		crafting[i] = appInventoryItemViewLocked(bot, "crafting", i, i, item)
	}
	craftOutput := make([]appInventoryItemView, 1)
	var output protocol.ItemInstance
	if len(bot.MapArtCraftingOutput) > 0 {
		output = bot.MapArtCraftingOutput[0]
	}
	computedCraftOutput := false
	craftDiagnosticDetail := ""
	if output.Stack.Count == 0 {
		if _, preview, _, ok := bedrockCraftPreviewForGridLocked(bot); ok {
			output = preview
			computedCraftOutput = true
		} else {
			detail := bedrockCraftGridDiagnosticLocked(bot)
			if detail != "" {
				key := fmt.Sprintf("%d/%d/%d/%d", bot.ID, bot.SessionGeneration, bot.InventoryRevision, len(bot.MapArtCraftRecipes))
				if _, loaded := bedrockCraftGridDiagnosticSeen.LoadOrStore(key, struct{}{}); !loaded {
					craftDiagnosticDetail = detail
				}
			}
		}
	}
	craftOutput[0] = appInventoryItemViewLocked(bot, "craft_output", 0, 0, output)
	ready := bot.MapArtInventoryReady
	transportConnected := bot.Connected && bot.conn != nil && !bot.Respawning.Load()
	playerReady := bot.PlayerReady && !bot.Respawning.Load()
	connected := bot.Connected && bot.PlayerReady && !bot.Respawning.Load()
	rawSlots := len(bot.MapArtInventory)
	heldSlot := bot.MapArtHeldSlot
	offhandReady := bot.MapArtOffhandReady
	armourReady := bot.MapArtArmourReady
	cursorReady := bot.MapArtCursorReady
	craftingReady := bot.MapArtCraftingInputReady
	craftOutputReady := bot.MapArtCraftingOutputReady || computedCraftOutput
	revision := bot.InventoryRevision
	sessionGeneration := bot.SessionGeneration
	botID := bot.ID
	bot.mu.Unlock()
	if craftDiagnosticDetail != "" {
		logCollectDiagnostic(bot, "crafting_grid_no_match", craftDiagnosticDetail)
	}

	// file:// WebView pages can load data:image URLs directly. Resolve icons in the
	// background and place the PNG data URL in subsequent inventory snapshots so
	// rendering no longer depends on a second fetch -> Blob -> object URL bridge.
	for i := range slots {
		hydrateAppInventoryIconDataURL(botID, &slots[i])
	}
	for i := range armour {
		hydrateAppInventoryIconDataURL(botID, &armour[i])
	}
	hydrateAppInventoryIconDataURL(botID, &offhandView)
	hydrateAppInventoryIconDataURL(botID, &cursorView)
	for i := range crafting {
		hydrateAppInventoryIconDataURL(botID, &crafting[i])
	}
	for i := range craftOutput {
		hydrateAppInventoryIconDataURL(botID, &craftOutput[i])
	}

	return map[string]interface{}{
		"ok":                  true,
		"ready":               ready,
		"connected":           connected,
		"transport_connected": transportConnected,
		"player_ready":        playerReady,
		"source_slots":        rawSlots,
		"used":                used,
		"capacity":            36,
		"held_slot":           heldSlot,
		"slots":               slots,
		"armour":              armour,
		"offhand":             offhandView,
		"cursor":              cursorView,
		"crafting":            crafting,
		"craft_output":        craftOutput,
		"offhand_ready":       offhandReady,
		"armour_ready":        armourReady,
		"cursor_ready":        cursorReady,
		"crafting_ready":      craftingReady,
		"craft_output_ready":  craftOutputReady,
		"revision":            revision,
		"session_generation":  sessionGeneration,
	}
}

func appInventoryRefLocked(bot *BotSession, ref string) (protocol.ItemInstance, protocol.FullContainerName, int, error) {
	parts := strings.Split(strings.TrimSpace(ref), ":")
	if len(parts) != 2 {
		return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("無效的背包位置")
	}
	slot, err := strconv.Atoi(parts[1])
	if err != nil || slot < 0 || slot > 255 {
		return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("無效的背包 slot")
	}
	switch strings.ToLower(parts[0]) {
	case "inventory":
		if slot >= 36 {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("主背包 slot 超出範圍")
		}
		var item protocol.ItemInstance
		if slot < len(bot.MapArtInventory) {
			item = bot.MapArtInventory[slot]
		}
		// ItemStackRequest uses the player's split stack-request containers, not
		// the InventoryContent window/container descriptor. Keep this identical to
		// the already proven collect/drop path: hotbar=0x1c, inventory=0x1d.
		return item, collectInventorySourceContainer(slot), collectInventoryWireSlot(slot), nil
	case "offhand":
		var item protocol.ItemInstance
		if slot < len(bot.MapArtOffhandInventory) {
			item = bot.MapArtOffhandInventory[slot]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerOffhand)}, slot, nil
	case "armour":
		var item protocol.ItemInstance
		if slot < len(bot.MapArtArmourInventory) {
			item = bot.MapArtArmourInventory[slot]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerArmor)}, slot, nil
	case "container":
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("目前沒有已同步的容器")
		}
		var item protocol.ItemInstance
		if slot < len(bot.MapArtContainerItems) {
			item = bot.MapArtContainerItems[slot]
		}
		return item, bot.MapArtContainerName, slot, nil
	case "anvil_input":
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("鐵砧尚未開啟")
		}
		var item protocol.ItemInstance
		if len(bot.MapArtContainerItems) > 0 {
			item = bot.MapArtContainerItems[0]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerAnvilInput)}, 1, nil
	case "anvil_material":
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("鐵砧尚未開啟")
		}
		var item protocol.ItemInstance
		if len(bot.MapArtContainerItems) > 1 {
			item = bot.MapArtContainerItems[1]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerAnvilMaterial)}, 2, nil
	case "anvil_result":
		if !bot.MapArtContainerOpen || !bot.MapArtContainerItemsReady {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("鐵砧尚未開啟")
		}
		var item protocol.ItemInstance
		if len(bot.MapArtContainerItems) > 2 {
			item = bot.MapArtContainerItems[2]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerAnvilResultPreview)}, 50, nil
	case "crafting":
		if slot >= 4 {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("合成格 slot 超出範圍")
		}
		var item protocol.ItemInstance
		if slot < len(bot.MapArtCraftingInput) {
			item = bot.MapArtCraftingInput[slot]
		}
		wireSlot, _ := bedrockPlayerCraftingWireSlot(slot)
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerCraftingInput)}, wireSlot, nil
	case "craft_output":
		if slot != 0 {
			return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("合成結果 slot 超出範圍")
		}
		var item protocol.ItemInstance
		if slot < len(bot.MapArtCraftingOutput) {
			item = bot.MapArtCraftingOutput[slot]
		}
		return item, protocol.FullContainerName{ContainerID: byte(protocol.ContainerCraftingOutputPreview)}, slot, nil
	default:
		return protocol.ItemInstance{}, protocol.FullContainerName{}, 0, errors.New("不支援的背包區域")
	}
}

func appInventoryApplySwapLocked(bot *BotSession, aRef, bRef string) {
	get := func(ref string) (*[]protocol.ItemInstance, int, bool) {
		parts := strings.Split(strings.TrimSpace(ref), ":")
		if len(parts) != 2 {
			return nil, 0, false
		}
		slot, err := strconv.Atoi(parts[1])
		if err != nil || slot < 0 {
			return nil, 0, false
		}
		switch parts[0] {
		case "inventory":
			return &bot.MapArtInventory, slot, true
		case "offhand":
			return &bot.MapArtOffhandInventory, slot, true
		case "armour":
			return &bot.MapArtArmourInventory, slot, true
		case "container":
			return &bot.MapArtContainerItems, slot, true
		case "crafting":
			return &bot.MapArtCraftingInput, slot, true
		case "craft_output":
			return &bot.MapArtCraftingOutput, slot, true
		}
		return nil, 0, false
	}
	a, ai, aok := get(aRef)
	b, bi, bok := get(bRef)
	if !aok || !bok || a == nil || b == nil {
		return
	}
	if ai >= len(*a) {
		next := make([]protocol.ItemInstance, ai+1)
		copy(next, *a)
		*a = next
	}
	if bi >= len(*b) {
		next := make([]protocol.ItemInstance, bi+1)
		copy(next, *b)
		*b = next
	}
	(*a)[ai], (*b)[bi] = (*b)[bi], (*a)[ai]
}

func appInventorySetRefLocked(bot *BotSession, ref string, item protocol.ItemInstance) {
	parts := strings.Split(strings.TrimSpace(ref), ":")
	if len(parts) != 2 {
		return
	}
	slot, err := strconv.Atoi(parts[1])
	if err != nil || slot < 0 {
		return
	}
	var target *[]protocol.ItemInstance
	if parts[0] == "anvil_input" {
		target = &bot.MapArtContainerItems
		slot = 0
	} else if parts[0] == "anvil_material" {
		target = &bot.MapArtContainerItems
		slot = 1
	} else if parts[0] == "anvil_result" {
		target = &bot.MapArtContainerItems
		slot = 2
	}
	switch parts[0] {
	case "inventory":
		target = &bot.MapArtInventory
	case "offhand":
		target = &bot.MapArtOffhandInventory
	case "armour":
		target = &bot.MapArtArmourInventory
	case "container":
		target = &bot.MapArtContainerItems
	case "crafting":
		target = &bot.MapArtCraftingInput
	case "craft_output":
		target = &bot.MapArtCraftingOutput
	case "anvil_input", "anvil_material", "anvil_result":
		// target/local slot were normalised above.
	default:
		return
	}
	if slot >= len(*target) {
		next := make([]protocol.ItemInstance, slot+1)
		copy(next, *target)
		*target = next
	}
	(*target)[slot] = item
}

func bedrockCraftDescriptorMatchLocked(bot *BotSession, descriptor protocol.ItemDescriptorCount, item protocol.ItemInstance) (bool, bool) {
	count := descriptor.Count
	if count <= 0 {
		count = 1
	}
	if count > 255 {
		return false, true
	}
	switch value := descriptor.Descriptor.(type) {
	case nil, *protocol.InvalidItemDescriptor:
		return item.Stack.Count == 0, true
	case *protocol.DefaultItemDescriptor:
		if item.Stack.Count < uint16(count) {
			return false, true
		}
		actual := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, item)))
		want := strings.ToLower(strings.TrimSpace(value.Name))
		if actual == "" || want == "" || actual != want {
			return false, true
		}
		if value.MetadataValue >= 0 && value.MetadataValue != 32767 && uint32(value.MetadataValue) != item.Stack.MetadataValue {
			return false, true
		}
		return true, true
	case *protocol.ItemTagItemDescriptor, *protocol.MoLangItemDescriptor:
		// The current packet does not include the server's expanded tag/MoLang
		// membership table. The server output preview is authoritative, so keep
		// these as a lower-confidence match instead of rejecting valid custom recipes.
		return item.Stack.Count >= uint16(count), false
	default:
		return false, true
	}
}

func bedrockCraftOutputMatches(recipe bedrockCraftRecipe, preview protocol.ItemInstance) bool {
	if preview.Stack.Count == 0 || len(recipe.Output) == 0 {
		return false
	}
	for _, output := range recipe.Output {
		if output.Count == 0 || output.NetworkID != preview.Stack.NetworkID || output.MetadataValue != preview.Stack.MetadataValue {
			continue
		}
		return true
	}
	return false
}

func bedrockCraftDescriptorIsEmpty(descriptor protocol.ItemDescriptorCount) bool {
	switch descriptor.Descriptor.(type) {
	case nil, *protocol.InvalidItemDescriptor:
		return true
	default:
		return false
	}
}

// bedrockCraftPartialRecipeCompatibleLocked mirrors the recipe-book check used
// by the Bedrock client while the player is still filling a crafting grid. An
// empty ingredient may be completed later, but every item already placed must
// fit a distinct ingredient/position announced by the server.
func bedrockCraftPartialRecipeCompatibleLocked(bot *BotSession, recipe bedrockCraftRecipe, grid [4]protocol.ItemInstance) bool {
	if recipe.Shapeless {
		ingredients := make([]protocol.ItemDescriptorCount, 0, len(recipe.Input))
		for _, ingredient := range recipe.Input {
			if !bedrockCraftDescriptorIsEmpty(ingredient) {
				ingredients = append(ingredients, ingredient)
			}
		}
		occupied := make([]int, 0, 4)
		for slot, item := range grid {
			if item.Stack.Count > 0 {
				occupied = append(occupied, slot)
			}
		}
		if len(occupied) == 0 || len(occupied) > len(ingredients) {
			return false
		}
		used := make([]bool, len(ingredients))
		var search func(int) bool
		search = func(index int) bool {
			if index >= len(occupied) {
				return true
			}
			item := grid[occupied[index]]
			for ingredientIndex, ingredient := range ingredients {
				if used[ingredientIndex] {
					continue
				}
				matches, _ := bedrockCraftDescriptorMatchLocked(bot, ingredient, item)
				if !matches {
					continue
				}
				used[ingredientIndex] = true
				if search(index + 1) {
					return true
				}
				used[ingredientIndex] = false
			}
			return false
		}
		return search(0)
	}

	if recipe.Width <= 0 || recipe.Height <= 0 || recipe.Width > 2 || recipe.Height > 2 || len(recipe.Input) < int(recipe.Width*recipe.Height) {
		return false
	}
	for mirror := 0; mirror < 2; mirror++ {
		if recipe.Width == 1 && mirror == 1 {
			break
		}
		for offsetY := int32(0); offsetY <= 2-recipe.Height; offsetY++ {
			for offsetX := int32(0); offsetX <= 2-recipe.Width; offsetX++ {
				valid := true
				occupied := 0
				for y := int32(0); y < 2 && valid; y++ {
					for x := int32(0); x < 2; x++ {
						gridSlot := int(y*2 + x)
						item := grid[gridSlot]
						if item.Stack.Count == 0 {
							continue
						}
						occupied++
						inside := x >= offsetX && x < offsetX+recipe.Width && y >= offsetY && y < offsetY+recipe.Height
						if !inside {
							valid = false
							break
						}
						recipeX := x - offsetX
						if mirror == 1 {
							recipeX = recipe.Width - 1 - recipeX
						}
						recipeSlot := int((y-offsetY)*recipe.Width + recipeX)
						ingredient := recipe.Input[recipeSlot]
						if bedrockCraftDescriptorIsEmpty(ingredient) {
							valid = false
							break
						}
						matches, _ := bedrockCraftDescriptorMatchLocked(bot, ingredient, item)
						if !matches {
							valid = false
							break
						}
					}
				}
				if valid && occupied > 0 {
					return true
				}
			}
		}
	}
	return false
}

func bedrockCraftGridHasServerPotentialLocked(bot *BotSession, grid [4]protocol.ItemInstance) bool {
	if bot == nil || len(bot.MapArtCraftRecipes) == 0 {
		return false
	}
	for _, recipe := range bot.MapArtCraftRecipes {
		if len(recipe.Output) == 0 || recipe.Output[0].Count == 0 {
			continue
		}
		if bedrockCraftPartialRecipeCompatibleLocked(bot, recipe, grid) {
			return true
		}
	}
	return false
}

func appInventoryCraftingLogicalRef(ref string) (int, bool) {
	parts := strings.Split(strings.ToLower(strings.TrimSpace(ref)), ":")
	if len(parts) != 2 || parts[0] != "crafting" {
		return 0, false
	}
	slot, err := strconv.Atoi(parts[1])
	return slot, err == nil && slot >= 0 && slot < 4
}

func appInventoryRefArea(ref string) string {
	parts := strings.SplitN(strings.ToLower(strings.TrimSpace(ref)), ":", 2)
	if len(parts) != 2 {
		return ""
	}
	return parts[0]
}

func bedrockItemAllowsOffhandLocked(bot *BotSession, item protocol.ItemInstance) bool {
	if bot == nil || item.Stack.Count == 0 {
		return true
	}
	if bot.MapArtItemAllowsOffhand[item.Stack.NetworkID] {
		return true
	}
	return bedrockVanillaItemAllowsOffhand(bedrockItemIdentityLocked(bot, item))
}

func appInventoryValidateOffhandMoveLocked(bot *BotSession, fromRef, toRef string, source, destination protocol.ItemInstance) error {
	fromArea := appInventoryRefArea(fromRef)
	toArea := appInventoryRefArea(toRef)
	var entering protocol.ItemInstance
	switch {
	case toArea == "offhand":
		entering = source
	case fromArea == "offhand" && destination.Stack.Count > 0:
		// A swap out of the offhand leaves the old destination item in it.
		entering = destination
	default:
		return nil
	}
	if bedrockItemAllowsOffhandLocked(bot, entering) {
		return nil
	}
	label := inventoryNBTDisplayName(entering)
	if label == "" {
		label = stableItemDisplayNameLocked(bot, bedrockItemIdentityLocked(bot, entering))
	}
	if label == "" {
		label = "這個物品"
	}
	return fmt.Errorf("%s 依伺服器物品設定不能放進副手", label)
}

// appInventoryValidateCraftingMoveLocked rejects a move before the cursor is
// touched if it would strand an item in a grid that cannot become any server
// recipe. Moving an item out to an empty non-crafting slot is always allowed.
func appInventoryValidateCraftingMoveLocked(bot *BotSession, fromRef, toRef string, source, destination protocol.ItemInstance) error {
	if err := appInventoryValidateOffhandMoveLocked(bot, fromRef, toRef, source, destination); err != nil {
		return err
	}
	fromSlot, fromCrafting := appInventoryCraftingLogicalRef(fromRef)
	toSlot, toCrafting := appInventoryCraftingLogicalRef(toRef)
	if !fromCrafting && !toCrafting {
		return nil
	}
	if fromCrafting && !toCrafting && destination.Stack.Count == 0 {
		return nil
	}
	if len(bot.MapArtCraftRecipes) == 0 {
		return errors.New("伺服器合成配方尚未同步，暫時不能把物品放進合成格")
	}
	grid := [4]protocol.ItemInstance{}
	copy(grid[:], bot.MapArtCraftingInput)
	switch {
	case fromCrafting && toCrafting:
		grid[fromSlot], grid[toSlot] = grid[toSlot], grid[fromSlot]
	case toCrafting:
		grid[toSlot] = source
	case fromCrafting:
		// Swapping onto an occupied backpack slot places that backpack item into
		// the crafting source slot. Validate the resulting grid before doing so.
		grid[fromSlot] = destination
	}
	occupied := false
	for _, item := range grid {
		occupied = occupied || item.Stack.Count > 0
	}
	if !occupied || bedrockCraftGridHasServerPotentialLocked(bot, grid) {
		return nil
	}
	return errors.New("這個物品無法形成目前伺服器的 2×2 配方，未放入合成格")
}

// bedrockCraftConsumeCountsLocked validates a recipe against the live 2x2
// input grid and returns how many items each grid slot consumes for one craft.
func bedrockCraftConsumeCountsLocked(bot *BotSession, recipe bedrockCraftRecipe) ([4]byte, bool, bool) {
	var empty [4]byte
	grid := [4]protocol.ItemInstance{}
	copy(grid[:], bot.MapArtCraftingInput)

	if recipe.Shapeless {
		ingredients := make([]protocol.ItemDescriptorCount, 0, len(recipe.Input))
		for _, ingredient := range recipe.Input {
			switch ingredient.Descriptor.(type) {
			case nil, *protocol.InvalidItemDescriptor:
				continue
			default:
				ingredients = append(ingredients, ingredient)
			}
		}
		occupied := make([]int, 0, 4)
		for slot, item := range grid {
			if item.Stack.Count > 0 {
				occupied = append(occupied, slot)
			}
		}
		if len(ingredients) != len(occupied) {
			return empty, false, false
		}
		used := [4]bool{}
		var search func(int, [4]byte, bool) ([4]byte, bool, bool)
		search = func(index int, counts [4]byte, exact bool) ([4]byte, bool, bool) {
			if index >= len(ingredients) {
				return counts, true, exact
			}
			ingredient := ingredients[index]
			for _, slot := range occupied {
				if used[slot] {
					continue
				}
				matches, known := bedrockCraftDescriptorMatchLocked(bot, ingredient, grid[slot])
				if !matches {
					continue
				}
				count := ingredient.Count
				if count <= 0 {
					count = 1
				}
				if count > 255 {
					continue
				}
				used[slot] = true
				counts[slot] = byte(count)
				if result, ok, allKnown := search(index+1, counts, exact && known); ok {
					return result, true, allKnown
				}
				used[slot] = false
				counts[slot] = 0
			}
			return empty, false, false
		}
		return search(0, empty, true)
	}

	if recipe.Width <= 0 || recipe.Height <= 0 || recipe.Width > 2 || recipe.Height > 2 || len(recipe.Input) < int(recipe.Width*recipe.Height) {
		return empty, false, false
	}
	for mirror := 0; mirror < 2; mirror++ {
		if recipe.Width == 1 && mirror == 1 {
			break
		}
		for offsetY := int32(0); offsetY <= 2-recipe.Height; offsetY++ {
			for offsetX := int32(0); offsetX <= 2-recipe.Width; offsetX++ {
				counts := [4]byte{}
				allKnown := true
				valid := true
				for y := int32(0); y < 2 && valid; y++ {
					for x := int32(0); x < 2; x++ {
						gridSlot := int(y*2 + x)
						var ingredient protocol.ItemDescriptorCount
						inside := x >= offsetX && x < offsetX+recipe.Width && y >= offsetY && y < offsetY+recipe.Height
						if inside {
							recipeX := x - offsetX
							if mirror == 1 {
								recipeX = recipe.Width - 1 - recipeX
							}
							recipeSlot := int((y-offsetY)*recipe.Width + recipeX)
							ingredient = recipe.Input[recipeSlot]
						}
						matches, known := bedrockCraftDescriptorMatchLocked(bot, ingredient, grid[gridSlot])
						if !matches {
							valid = false
							break
						}
						allKnown = allKnown && known
						if grid[gridSlot].Stack.Count > 0 {
							count := ingredient.Count
							if count <= 0 {
								count = 1
							}
							if count > 255 {
								valid = false
								break
							}
							counts[gridSlot] = byte(count)
						}
					}
				}
				if valid {
					return counts, true, allKnown
				}
			}
		}
	}
	return empty, false, false
}

func bedrockCraftRecipeForPreviewLocked(bot *BotSession, preview protocol.ItemInstance) (bedrockCraftRecipe, [4]byte, bool) {
	var fallback bedrockCraftRecipe
	var fallbackCounts [4]byte
	fallbackSet := false
	for _, recipe := range bot.MapArtCraftRecipes {
		if !bedrockCraftOutputMatches(recipe, preview) {
			continue
		}
		counts, matches, exact := bedrockCraftConsumeCountsLocked(bot, recipe)
		if !matches {
			continue
		}
		if exact {
			return recipe, counts, true
		}
		if !fallbackSet {
			fallback, fallbackCounts, fallbackSet = recipe, counts, true
		}
	}
	return fallback, fallbackCounts, fallbackSet
}

func bedrockCraftRecipeForGridLocked(bot *BotSession) (bedrockCraftRecipe, [4]byte, bool) {
	var fallback bedrockCraftRecipe
	var fallbackCounts [4]byte
	fallbackSet := false
	for _, recipe := range bot.MapArtCraftRecipes {
		if len(recipe.Output) == 0 || recipe.Output[0].Count == 0 {
			continue
		}
		counts, matches, exact := bedrockCraftConsumeCountsLocked(bot, recipe)
		if !matches {
			continue
		}
		if exact {
			return recipe, counts, true
		}
		if !fallbackSet {
			fallback, fallbackCounts, fallbackSet = recipe, counts, true
		}
	}
	return fallback, fallbackCounts, fallbackSet
}

// Bedrock clients calculate the visible player-crafting result from the
// CraftingData recipe table. The server is not required to send a separate
// CraftingOutputPreview InventorySlot packet for the 2x2 player grid.
func bedrockCraftPreviewForGridLocked(bot *BotSession) (bedrockCraftRecipe, protocol.ItemInstance, [4]byte, bool) {
	recipe, counts, ok := bedrockCraftRecipeForGridLocked(bot)
	if !ok || len(recipe.Output) == 0 || recipe.Output[0].Count == 0 {
		return bedrockCraftRecipe{}, protocol.ItemInstance{}, [4]byte{}, false
	}
	return recipe, protocol.ItemInstance{Stack: recipe.Output[0]}, counts, true
}

type suiteInternalInventoryContextKeyV117 struct{}

func suiteInternalInventoryContextV117(ctx context.Context) context.Context {
	if ctx == nil {
		ctx = context.Background()
	}
	return context.WithValue(ctx, suiteInternalInventoryContextKeyV117{}, true)
}

func suiteInternalInventoryAllowedV117(ctx context.Context) bool {
	if ctx == nil {
		return false
	}
	allowed, _ := ctx.Value(suiteInternalInventoryContextKeyV117{}).(bool)
	return allowed
}

func appInventoryCraft(ctx context.Context, bot *BotSession, toRef string) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	bot.mu.Lock()
	if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" && !suiteInternalInventoryAllowedV117(ctx) {
		msg := bedrockControlBusyMessageLocked(bot, owner)
		bot.mu.Unlock()
		return errors.New(msg)
	}
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return errors.New("BOT 尚未完成登入/出生")
	}
	if bot.MapArtCursor.Stack.Count != 0 {
		bot.mu.Unlock()
		return errors.New("游標目前有物品，請先放回背包再合成")
	}
	recipe, preview, consumeCounts, ok := bedrockCraftPreviewForGridLocked(bot)
	if !ok {
		bot.mu.Unlock()
		return errors.New("這四格材料沒有可用的伺服器合成配方")
	}
	destination, destinationContainer, destinationSlot, err := appInventoryRefLocked(bot, toRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	if !strings.HasPrefix(strings.ToLower(strings.TrimSpace(toRef)), "inventory:") {
		bot.mu.Unlock()
		return errors.New("合成結果目前只能放進主背包或快捷欄")
	}
	previewID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, preview)))
	if previewID == "" {
		bot.mu.Unlock()
		return errors.New("伺服器的合成結果缺少物品識別碼")
	}
	if destination.Stack.Count > 0 {
		destinationID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, destination)))
		if destinationID != previewID || destination.Stack.MetadataValue != preview.Stack.MetadataValue {
			bot.mu.Unlock()
			return errors.New("合成結果只能拖到空格或相同物品上")
		}
	}
	conn := bot.conn
	bot.mu.Unlock()

	requestID := bot.nextMapArtStackRequestID()
	actions := make([]protocol.StackRequestAction, 0, 8)
	actions = append(actions,
		&protocol.CraftRecipeStackRequestAction{RecipeNetworkID: recipe.NetworkID, NumberOfCrafts: 1},
		&protocol.CraftResultsDeprecatedStackRequestAction{
			ResultItems: []protocol.StackRequestItem{{
				Identifier:     previewID,
				MetadataValue:  preview.Stack.MetadataValue,
				BlockRuntimeID: preview.Stack.BlockRuntimeID,
				Count:          preview.Stack.Count,
				NBTData:        preview.Stack.NBTData,
				CanBePlacedOn:  preview.Stack.CanBePlacedOn,
				CanBreak:       preview.Stack.CanBreak,
				BlockingTick:   preview.Stack.BlockingTick,
			}},
			TimesCrafted: 1,
		},
	)
	for slot, count := range consumeCounts {
		if count == 0 {
			continue
		}
		bot.mu.Lock()
		var ingredient protocol.ItemInstance
		if slot < len(bot.MapArtCraftingInput) {
			ingredient = bot.MapArtCraftingInput[slot]
		}
		bot.mu.Unlock()
		if ingredient.Stack.Count < uint16(count) {
			return fmt.Errorf("合成格 %d 的材料數量已變更", slot+1)
		}
		consume := &protocol.ConsumeStackRequestAction{}
		consume.Count = count
		consume.Source = protocol.StackRequestSlotInfo{
			Container:      protocol.FullContainerName{ContainerID: byte(protocol.ContainerCraftingInput)},
			Slot:           byte(slot + bedrockPlayerCraftingSlotOffset),
			StackNetworkID: ingredient.StackNetworkID,
		}
		actions = append(actions, consume)
	}
	outputCount := int(preview.Stack.Count)
	if outputCount <= 0 || outputCount > 255 {
		return errors.New("合成結果數量不正確")
	}
	actions = append(actions, collectNewPlaceStackRequestAction(byte(outputCount),
		protocol.StackRequestSlotInfo{
			Container:      protocol.FullContainerName{ContainerID: byte(protocol.ContainerCreatedOutput)},
			Slot:           bedrockCreatedOutputSlot,
			StackNetworkID: requestID,
		},
		protocol.StackRequestSlotInfo{
			Container:      destinationContainer,
			Slot:           byte(destinationSlot),
			StackNetworkID: destination.StackNetworkID,
		},
	))

	req := protocol.ItemStackRequest{RequestID: requestID, Actions: actions, FilterCause: -1}
	pending := bedrockPendingStackRequest{RequestID: requestID, Kind: "app_craft", CreatedAt: time.Now(), SourceSlot: bedrockCreatedOutputSlot, Source: preview, Requested: outputCount, SourceContainer: protocol.FullContainerName{ContainerID: byte(protocol.ContainerCreatedOutput)}}
	response, err := bot.bedrockSendStackRequest(ctx, conn, req, pending, 4*time.Second)
	if err != nil {
		return fmt.Errorf("合成失敗: %w", err)
	}

	updatedDestination := destination
	if updatedDestination.Stack.Count == 0 {
		updatedDestination = preview
	} else {
		updatedDestination.Stack.Count += preview.Stack.Count
	}
	for _, containerInfo := range response.ContainerInfo {
		if containerInfo.Container.ContainerID != destinationContainer.ContainerID {
			continue
		}
		for _, slotInfo := range containerInfo.SlotInfo {
			if int(slotInfo.Slot) != destinationSlot {
				continue
			}
			updatedDestination.Stack.Count = uint16(slotInfo.Count)
			updatedDestination.StackNetworkID = slotInfo.StackNetworkID
		}
	}

	bot.mu.Lock()
	appInventorySetRefLocked(bot, toRef, updatedDestination)
	for slot, count := range consumeCounts {
		if count == 0 || slot >= len(bot.MapArtCraftingInput) {
			continue
		}
		ingredientAfter := bot.MapArtCraftingInput[slot]
		if ingredientAfter.Stack.Count <= uint16(count) {
			ingredientAfter = protocol.ItemInstance{}
		} else {
			ingredientAfter.Stack.Count -= uint16(count)
		}
		wireSlot := slot + bedrockPlayerCraftingSlotOffset
		if authoritative, found := appInventoryResponseItem(response, protocol.FullContainerName{ContainerID: byte(protocol.ContainerCraftingInput)}, wireSlot, ingredientAfter); found {
			ingredientAfter = authoritative
		}
		bot.MapArtCraftingInput[slot] = ingredientAfter
	}
	bot.MapArtCraftingOutput = []protocol.ItemInstance{{}}
	bot.MapArtCraftingOutputReady = true
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
	return nil
}

func appInventoryResponseItem(response protocol.ItemStackResponse, container protocol.FullContainerName, slot int, fallback protocol.ItemInstance) (protocol.ItemInstance, bool) {
	for _, containerInfo := range response.ContainerInfo {
		if containerInfo.Container.ContainerID != container.ContainerID {
			continue
		}
		for _, slotInfo := range containerInfo.SlotInfo {
			if int(slotInfo.Slot) != slot {
				continue
			}
			if slotInfo.Count == 0 {
				return protocol.ItemInstance{}, true
			}
			item := fallback
			item.Stack.Count = uint16(slotInfo.Count)
			item.StackNetworkID = slotInfo.StackNetworkID
			return item, true
		}
	}
	return fallback, false
}

// bedrockOpenPlayerInventoryActionScene mirrors the native Bedrock UI flow.
// Servers keep a scene stack for inventory predictions and reject main-inventory
// requests sent while the player's inventory screen is not open.
func bedrockOpenPlayerInventoryActionScene(ctx context.Context, bot *BotSession, conn *minecraft.Conn) (byte, bool, error) {
	if bot == nil || conn == nil {
		return 0, false, errors.New("背包連線不存在")
	}
	bot.mu.Lock()
	if bot.conn != conn || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return 0, false, errors.New("BOT 尚未完成登入/出生")
	}
	if bot.PlayerInventoryActionOpen {
		windowID := bot.PlayerInventoryActionWindowID
		bot.mu.Unlock()
		return windowID, false, nil
	}
	if bot.MapArtContainerOpen {
		bot.mu.Unlock()
		return 0, false, errors.New("目前有其他容器開啟，請先關閉再操作背包")
	}
	runtimeID := bot.CurrentEntityRuntimeID
	if runtimeID == 0 {
		runtimeID = conn.GameData().EntityRuntimeID
	}
	bot.mu.Unlock()
	if runtimeID == 0 {
		return 0, false, errors.New("無法取得 BOT 的 EntityRuntimeID")
	}

	if err := conn.WritePacket(&packet.Interact{
		ActionType:            packet.InteractActionOpenInventory,
		TargetEntityRuntimeID: runtimeID,
	}); err != nil {
		return 0, false, fmt.Errorf("開啟玩家背包失敗: %w", err)
	}
	if err := conn.Flush(); err != nil {
		return 0, false, fmt.Errorf("開啟玩家背包失敗: %w", err)
	}

	timer := time.NewTimer(3 * time.Second)
	defer timer.Stop()
	for {
		bot.mu.Lock()
		current := bot.conn == conn && bot.Connected
		opened := bot.PlayerInventoryActionOpen
		windowID := bot.PlayerInventoryActionWindowID
		notify := bot.MapArtNotify
		bot.mu.Unlock()
		if !current {
			return 0, false, errors.New("開啟背包時 BOT 連線已變更")
		}
		if opened {
			return windowID, true, nil
		}
		select {
		case <-ctx.Done():
			return 0, false, ctx.Err()
		case <-timer.C:
			return 0, false, errors.New("等待伺服器開啟玩家背包逾時")
		case <-notify:
		}
	}
}

func bedrockClosePlayerInventoryActionScene(bot *BotSession, conn *minecraft.Conn, windowID byte) {
	if bot == nil || conn == nil {
		return
	}
	_ = conn.WritePacket(&packet.ContainerClose{WindowID: windowID, ContainerType: 0xff, ServerSide: false})
	_ = conn.Flush()
	bot.mu.Lock()
	if bot.conn == conn && bot.PlayerInventoryActionWindowID == windowID {
		bot.PlayerInventoryActionOpen = false
		bot.PlayerInventoryActionWindowID = 0
	}
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func appInventoryDirectMoveAction(source, destination protocol.ItemInstance, sourceInfo, destinationInfo protocol.StackRequestSlotInfo) protocol.StackRequestAction {
	if destination.Stack.Count == 0 {
		return collectNewTakeStackRequestAction(byte(source.Stack.Count), sourceInfo, destinationInfo)
	}
	return &protocol.SwapStackRequestAction{Source: sourceInfo, Destination: destinationInfo}
}

func appInventoryApplyDirectMove(bot *BotSession, fromRef, toRef string, sourceAfter, destinationAfter protocol.ItemInstance) {
	bot.mu.Lock()
	appInventorySetRefLocked(bot, fromRef, sourceAfter)
	appInventorySetRefLocked(bot, toRef, destinationAfter)
	if _, crafting := appInventoryCraftingLogicalRef(fromRef); crafting {
		bot.MapArtCraftingOutput = []protocol.ItemInstance{{}}
		bot.MapArtCraftingOutputReady = false
	}
	if _, crafting := appInventoryCraftingLogicalRef(toRef); crafting {
		bot.MapArtCraftingOutput = []protocol.ItemInstance{{}}
		bot.MapArtCraftingOutputReady = false
	}
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
}

func appInventorySetMoveState(bot *BotSession, ref string, item, cursor protocol.ItemInstance) {
	bot.mu.Lock()
	appInventorySetRefLocked(bot, ref, item)
	if _, crafting := appInventoryCraftingLogicalRef(ref); crafting {
		// Any input move invalidates the previous client-side crafting preview.
		// The next inventory snapshot recomputes it from the retained recipe table.
		bot.MapArtCraftingOutput = []protocol.ItemInstance{{}}
		bot.MapArtCraftingOutputReady = false
	}
	bot.MapArtCursor = cursor
	bot.MapArtCursorReady = true
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
}

// appInventoryReturnCursor is the recovery half of the native click sequence.
// Once Take succeeds the server really holds the stack on the Bedrock cursor,
// so a rejected Place must return it to the original empty slot.
func appInventoryReturnCursor(ctx context.Context, bot *BotSession, conn *minecraft.Conn, ref string, sourceContainer protocol.FullContainerName, sourceSlot int, cursor protocol.ItemInstance) error {
	if cursor.Stack.Count == 0 || cursor.Stack.Count > 255 || cursor.StackNetworkID == 0 {
		return errors.New("游標物品資料不正確")
	}
	cursorContainer := protocol.FullContainerName{ContainerID: byte(protocol.ContainerCursor)}
	requestID := bot.nextMapArtStackRequestID()
	req := protocol.ItemStackRequest{
		RequestID: requestID,
		Actions: []protocol.StackRequestAction{collectNewPlaceStackRequestAction(
			byte(cursor.Stack.Count),
			protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: cursor.StackNetworkID},
			protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: 0},
		)},
		FilterCause: -1,
	}
	pending := bedrockPendingStackRequest{RequestID: requestID, Kind: "app_move_rollback", CreatedAt: time.Now(), SourceSlot: 0, Source: cursor, Requested: int(cursor.Stack.Count), SourceContainer: cursorContainer}
	response, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, req, pending, 2500*time.Millisecond)
	if err != nil {
		logCollectDiagnostic(bot, "app_inventory_move_rejected", fmt.Sprintf(
			"stage=rollback source_container=0x%02x source_slot=%d cursor_stack_network_id=%d error=%v",
			sourceContainer.ContainerID, sourceSlot, cursor.StackNetworkID, err,
		))
		return err
	}
	sourceAfter, found := appInventoryResponseItem(response, sourceContainer, sourceSlot, cursor)
	if !found {
		sourceAfter = cursor
	}
	cursorAfter, found := appInventoryResponseItem(response, cursorContainer, 0, protocol.ItemInstance{})
	if !found {
		cursorAfter = protocol.ItemInstance{}
	}
	appInventorySetMoveState(bot, ref, sourceAfter, cursorAfter)
	return nil
}

// suiteInventoryMoveCountV117 moves an exact count directly between two logical
// inventory references using one server-authoritative ItemStackRequest. It is
// task-internal: UI drag/drop keeps appInventorySwap's normal ownership checks.
func suiteInventoryMoveCountV117(ctx context.Context, bot *BotSession, fromRef, toRef string, count int) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if count <= 0 || count > 255 {
		return errors.New("移動數量必須介於 1~255")
	}
	if strings.EqualFold(strings.TrimSpace(fromRef), strings.TrimSpace(toRef)) {
		return nil
	}
	ctx = suiteInternalInventoryContextV117(ctx)
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	bot.mu.Lock()
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return errors.New("BOT 尚未完成登入/出生")
	}
	if bot.MapArtCursor.Stack.Count != 0 {
		bot.mu.Unlock()
		return errors.New("游標目前有物品，無法執行工作流搬運")
	}
	conn := bot.conn
	source, sourceContainer, sourceSlot, err := appInventoryRefLocked(bot, fromRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	destination, destinationContainer, destinationSlot, err := appInventoryRefLocked(bot, toRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	if source.Stack.Count < uint16(count) {
		bot.mu.Unlock()
		return fmt.Errorf("來源 %s 只有 %d 個，無法移動 %d 個", fromRef, source.Stack.Count, count)
	}
	if destination.Stack.Count > 0 {
		sourceID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, source)))
		destinationID := strings.ToLower(strings.TrimSpace(bedrockItemIdentityLocked(bot, destination)))
		if sourceID == "" || sourceID != destinationID || source.Stack.MetadataValue != destination.Stack.MetadataValue {
			bot.mu.Unlock()
			return errors.New("目的格不是空格或相同物品")
		}
		if sourceMapID, sourceMap := inventoryNBTMapID(source); sourceMap {
			if destinationMapID, destinationMap := inventoryNBTMapID(destination); !destinationMap || destinationMapID != sourceMapID {
				bot.mu.Unlock()
				return errors.New("不同 Map ID 的地圖不能堆疊")
			}
		}
		if int(destination.Stack.Count)+count > 64 {
			bot.mu.Unlock()
			return fmt.Errorf("目的格容量不足：目前 %d，要再放 %d", destination.Stack.Count, count)
		}
	}
	bot.mu.Unlock()

	requestID := bot.nextMapArtStackRequestID()
	req := protocol.ItemStackRequest{
		RequestID: requestID,
		Actions: []protocol.StackRequestAction{collectNewPlaceStackRequestAction(
			byte(count),
			protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: source.StackNetworkID},
			protocol.StackRequestSlotInfo{Container: destinationContainer, Slot: byte(destinationSlot), StackNetworkID: destination.StackNetworkID},
		)},
		FilterCause: -1,
	}
	pending := bedrockPendingStackRequest{RequestID: requestID, Kind: "suite_inventory_move_v117", CreatedAt: time.Now(), SourceSlot: sourceSlot, Source: source, Requested: count, SourceContainer: sourceContainer}
	response, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, req, pending, 3500*time.Millisecond)
	if err != nil {
		_ = requestBedrockInventoryResync(bot)
		return fmt.Errorf("工作流搬運 %s → %s 失敗: %w", fromRef, toRef, err)
	}

	sourceAfter := source
	if int(sourceAfter.Stack.Count) <= count {
		sourceAfter = protocol.ItemInstance{}
	} else {
		sourceAfter.Stack.Count -= uint16(count)
	}
	destinationAfter := destination
	if destinationAfter.Stack.Count == 0 {
		destinationAfter = source
		destinationAfter.Stack.Count = uint16(count)
	} else {
		destinationAfter.Stack.Count += uint16(count)
	}
	if authoritative, ok := appInventoryResponseItem(response, sourceContainer, sourceSlot, sourceAfter); ok {
		sourceAfter = authoritative
	}
	if authoritative, ok := appInventoryResponseItem(response, destinationContainer, destinationSlot, destinationAfter); ok {
		destinationAfter = authoritative
	}
	appInventoryApplyDirectMove(bot, fromRef, toRef, sourceAfter, destinationAfter)
	return nil
}

func appInventorySwap(ctx context.Context, bot *BotSession, fromRef, toRef string) error {
	if bot == nil {
		return errors.New("找不到 BOT")
	}
	if strings.HasPrefix(strings.ToLower(strings.TrimSpace(fromRef)), "craft_output:") || strings.HasPrefix(strings.ToLower(strings.TrimSpace(toRef)), "craft_output:") {
		return errors.New("合成結果格不能用一般背包換位")
	}
	if fromRef == toRef {
		return nil
	}
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	bot.mu.Lock()
	if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" && !suiteInternalInventoryAllowedV117(ctx) {
		msg := bedrockControlBusyMessageLocked(bot, owner)
		bot.mu.Unlock()
		return errors.New(msg)
	}
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return errors.New("BOT 尚未完成登入/出生")
	}
	if bot.MapArtCursor.Stack.Count != 0 {
		bot.mu.Unlock()
		return errors.New("游標目前有物品，請先放回背包再換位")
	}
	conn := bot.conn
	source, sourceContainer, sourceSlot, err := appInventoryRefLocked(bot, fromRef)
	if err != nil {
		bot.mu.Unlock()
		return err
	}
	destination, destinationContainer, destinationSlot, err := appInventoryRefLocked(bot, toRef)
	if err == nil {
		err = appInventoryValidateCraftingMoveLocked(bot, fromRef, toRef, source, destination)
	}
	bot.mu.Unlock()
	if err != nil {
		return err
	}
	if source.Stack.Count == 0 {
		return errors.New("來源格已經是空的")
	}
	if source.Stack.Count > 255 || destination.Stack.Count > 255 {
		return errors.New("物品數量不正確")
	}
	windowID, openedScene, err := bedrockOpenPlayerInventoryActionScene(ctx, bot, conn)
	if err != nil {
		return fmt.Errorf("背包換位失敗: %w", err)
	}
	if openedScene {
		defer bedrockClosePlayerInventoryActionScene(bot, conn, windowID)
	}

	// Reproduce the native inventory clicks exactly: Take to cursor first, wait for
	// the authoritative cursor StackNetworkID, then Place/Swap from the cursor.
	// Keeping the player-inventory scene open for the whole sequence is important
	// for offhand and armour containers on strict Bedrock/Geyser servers.
	cursorContainer := protocol.FullContainerName{ContainerID: byte(protocol.ContainerCursor)}
	takeRequestID := bot.nextMapArtStackRequestID()
	takeReq := protocol.ItemStackRequest{
		RequestID: takeRequestID,
		Actions: []protocol.StackRequestAction{collectNewTakeStackRequestAction(
			byte(source.Stack.Count),
			protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: source.StackNetworkID},
			protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: 0},
		)},
		FilterCause: -1,
	}
	takePending := bedrockPendingStackRequest{RequestID: takeRequestID, Kind: "app_move_take", CreatedAt: time.Now(), SourceSlot: sourceSlot, Source: source, Requested: int(source.Stack.Count), SourceContainer: sourceContainer}
	takeResponse, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, takeReq, takePending, 3500*time.Millisecond)
	if err != nil {
		logCollectDiagnostic(bot, "app_inventory_move_rejected", fmt.Sprintf(
			"stage=take from=%s to=%s source_container=0x%02x source_slot=%d source_stack_network_id=%d cursor_container=0x%02x error=%v",
			fromRef, toRef, sourceContainer.ContainerID, sourceSlot, source.StackNetworkID, cursorContainer.ContainerID, err,
		))
		_ = requestBedrockInventoryResync(bot)
		return fmt.Errorf("背包換位失敗（拿起物品）: %w", err)
	}
	sourceAfter, found := appInventoryResponseItem(takeResponse, sourceContainer, sourceSlot, protocol.ItemInstance{})
	if !found {
		sourceAfter = protocol.ItemInstance{}
	}
	cursorAfterTake, found := appInventoryResponseItem(takeResponse, cursorContainer, 0, source)
	if !found {
		cursorAfterTake = source
	}
	if cursorAfterTake.Stack.Count == 0 || cursorAfterTake.StackNetworkID == 0 {
		_ = requestBedrockInventoryResync(bot)
		return errors.New("背包換位失敗：伺服器沒有回傳游標物品編號")
	}
	appInventorySetMoveState(bot, fromRef, sourceAfter, cursorAfterTake)

	moveRequestID := bot.nextMapArtStackRequestID()
	cursorInfo := protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: cursorAfterTake.StackNetworkID}
	destinationInfo := protocol.StackRequestSlotInfo{Container: destinationContainer, Slot: byte(destinationSlot), StackNetworkID: destination.StackNetworkID}
	var moveAction protocol.StackRequestAction
	moveStage := "place"
	if destination.Stack.Count == 0 {
		moveAction = collectNewPlaceStackRequestAction(byte(cursorAfterTake.Stack.Count), cursorInfo, destinationInfo)
	} else {
		moveStage = "swap"
		moveAction = &protocol.SwapStackRequestAction{Source: cursorInfo, Destination: destinationInfo}
	}
	moveReq := protocol.ItemStackRequest{RequestID: moveRequestID, Actions: []protocol.StackRequestAction{moveAction}, FilterCause: -1}
	movePending := bedrockPendingStackRequest{RequestID: moveRequestID, Kind: "app_move_" + moveStage, CreatedAt: time.Now(), SourceSlot: 0, Source: cursorAfterTake, Requested: int(cursorAfterTake.Stack.Count), SourceContainer: cursorContainer}
	moveResponse, err := bot.bedrockSendStandaloneStackRequest(ctx, conn, moveReq, movePending, 3500*time.Millisecond)
	if err != nil {
		logCollectDiagnostic(bot, "app_inventory_move_rejected", fmt.Sprintf(
			"stage=%s from=%s to=%s cursor_container=0x%02x cursor_stack_network_id=%d destination_container=0x%02x destination_slot=%d destination_stack_network_id=%d error=%v",
			moveStage, fromRef, toRef, cursorContainer.ContainerID, cursorAfterTake.StackNetworkID,
			destinationContainer.ContainerID, destinationSlot, destination.StackNetworkID, err,
		))
		rollbackErr := appInventoryReturnCursor(ctx, bot, conn, fromRef, sourceContainer, sourceSlot, cursorAfterTake)
		if rollbackErr != nil {
			_ = requestBedrockInventoryResync(bot)
			return fmt.Errorf("背包換位失敗（%s）: %v；物品放回原格也失敗: %v", moveStage, err, rollbackErr)
		}
		return fmt.Errorf("背包換位失敗（%s）: %w", moveStage, err)
	}
	destinationAfter, found := appInventoryResponseItem(moveResponse, destinationContainer, destinationSlot, cursorAfterTake)
	if !found {
		destinationAfter = cursorAfterTake
	}
	cursorFallback := protocol.ItemInstance{}
	if destination.Stack.Count > 0 {
		cursorFallback = destination
	}
	cursorAfterMove, found := appInventoryResponseItem(moveResponse, cursorContainer, 0, cursorFallback)
	if !found {
		cursorAfterMove = cursorFallback
	}
	appInventorySetMoveState(bot, toRef, destinationAfter, cursorAfterMove)

	if destination.Stack.Count > 0 {
		if cursorAfterMove.Stack.Count == 0 || cursorAfterMove.Stack.Count > 255 || cursorAfterMove.StackNetworkID == 0 {
			_ = requestBedrockInventoryResync(bot)
			return errors.New("背包換位失敗：伺服器沒有回傳交換後的游標物品")
		}
		returnRequestID := bot.nextMapArtStackRequestID()
		returnReq := protocol.ItemStackRequest{
			RequestID: returnRequestID,
			Actions: []protocol.StackRequestAction{collectNewPlaceStackRequestAction(
				byte(cursorAfterMove.Stack.Count),
				protocol.StackRequestSlotInfo{Container: cursorContainer, Slot: 0, StackNetworkID: cursorAfterMove.StackNetworkID},
				protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: sourceAfter.StackNetworkID},
			)},
			FilterCause: -1,
		}
		returnPending := bedrockPendingStackRequest{RequestID: returnRequestID, Kind: "app_move_swap_finish", CreatedAt: time.Now(), SourceSlot: 0, Source: cursorAfterMove, Requested: int(cursorAfterMove.Stack.Count), SourceContainer: cursorContainer}
		returnResponse, returnErr := bot.bedrockSendStandaloneStackRequest(ctx, conn, returnReq, returnPending, 3500*time.Millisecond)
		if returnErr != nil {
			logCollectDiagnostic(bot, "app_inventory_move_rejected", fmt.Sprintf(
				"stage=swap_finish from=%s to=%s cursor_stack_network_id=%d source_container=0x%02x source_slot=%d error=%v",
				fromRef, toRef, cursorAfterMove.StackNetworkID, sourceContainer.ContainerID, sourceSlot, returnErr,
			))
			_ = requestBedrockInventoryResync(bot)
			return fmt.Errorf("背包換位最後一步失敗: %w", returnErr)
		}
		sourceFinal, found := appInventoryResponseItem(returnResponse, sourceContainer, sourceSlot, cursorAfterMove)
		if !found {
			sourceFinal = cursorAfterMove
		}
		cursorFinal, found := appInventoryResponseItem(returnResponse, cursorContainer, 0, protocol.ItemInstance{})
		if !found {
			cursorFinal = protocol.ItemInstance{}
		}
		appInventorySetMoveState(bot, fromRef, sourceFinal, cursorFinal)
	}
	return nil
}

func appInventoryDropRef(ctx context.Context, bot *BotSession, ref string, requested int) (int, error) {
	if bot == nil {
		return 0, errors.New("找不到 BOT")
	}
	bot.dropMu.Lock()
	defer bot.dropMu.Unlock()

	bot.mu.Lock()
	if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" {
		msg := bedrockControlBusyMessageLocked(bot, owner)
		bot.mu.Unlock()
		return 0, errors.New(msg)
	}
	if !bot.Connected || bot.conn == nil || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return 0, errors.New("BOT 尚未完成登入/出生")
	}
	conn := bot.conn
	containerSceneOpen := bot.MapArtContainerOpen
	source, sourceContainer, sourceSlot, err := appInventoryRefLocked(bot, ref)
	bot.mu.Unlock()
	if err != nil {
		return 0, err
	}
	if source.Stack.Count == 0 {
		return 0, errors.New("這個格子已經是空的")
	}
	count := requested
	if count <= 0 || count > int(source.Stack.Count) {
		count = int(source.Stack.Count)
	}
	if count > 255 {
		count = 255
	}

	// DropStackRequestAction is the native "drag out of an open inventory"
	// operation. Sending it without an inventory scene makes this server reject it
	// with status=1. A standalone ItemStackRequest was then observed to receive no
	// response at all on mcFallout. Open the real player-inventory scene first, but
	// route the request through PlayerAuthInput, which is the channel this server
	// already acknowledges for server-authoritative inventory requests.
	if !containerSceneOpen {
		windowID, openedScene, openErr := bedrockOpenPlayerInventoryActionScene(ctx, bot, conn)
		if openErr != nil {
			return 0, fmt.Errorf("丟棄前開啟背包失敗: %w", openErr)
		}
		if openedScene {
			defer bedrockClosePlayerInventoryActionScene(bot, conn, windowID)
		}
	}
	requestID := bot.nextMapArtStackRequestID()
	req := protocol.ItemStackRequest{
		RequestID: requestID,
		Actions: []protocol.StackRequestAction{
			&protocol.DropStackRequestAction{
				Count:  byte(count),
				Source: protocol.StackRequestSlotInfo{Container: sourceContainer, Slot: byte(sourceSlot), StackNetworkID: source.StackNetworkID},
			},
		},
		FilterCause: -1,
	}
	pending := bedrockPendingStackRequest{RequestID: requestID, Kind: "app_drop", CreatedAt: time.Now(), SourceSlot: sourceSlot, Source: source, Requested: count, SourceContainer: sourceContainer}
	logCollectDiagnostic(bot, "app_inventory_drop_request", fmt.Sprintf(
		"ref=%s request_id=%d count=%d source_container=0x%02x source_slot=%d source_stack_network_id=%d container_scene_open=%v",
		ref, requestID, count, sourceContainer.ContainerID, sourceSlot, source.StackNetworkID, containerSceneOpen,
	))
	response, err := bot.bedrockSendStackRequest(ctx, conn, req, pending, 3500*time.Millisecond)
	if err != nil {
		logCollectDiagnostic(bot, "app_inventory_drop_rejected", fmt.Sprintf(
			"ref=%s request_id=%d source_container=0x%02x source_slot=%d source_stack_network_id=%d error=%v",
			ref, requestID, sourceContainer.ContainerID, sourceSlot, source.StackNetworkID, err,
		))
		_ = requestBedrockInventoryResync(bot)
		return 0, err
	}
	// ItemStackResponse itself is a server confirmation. Apply its authoritative
	// count/stack-network-id immediately; later InventorySlot/Content still wins.
	updated := source
	foundAuthoritative := false
	for _, containerInfo := range response.ContainerInfo {
		if containerInfo.Container.ContainerID != sourceContainer.ContainerID {
			continue
		}
		for _, slotInfo := range containerInfo.SlotInfo {
			if int(slotInfo.Slot) != sourceSlot {
				continue
			}
			foundAuthoritative = true
			if slotInfo.Count == 0 {
				updated = protocol.ItemInstance{}
			} else {
				updated.Stack.Count = uint16(slotInfo.Count)
				updated.StackNetworkID = slotInfo.StackNetworkID
			}
			break
		}
	}
	if !foundAuthoritative {
		if count >= int(source.Stack.Count) {
			updated = protocol.ItemInstance{}
		} else {
			updated.Stack.Count -= uint16(count)
		}
	}
	bot.mu.Lock()
	appInventorySetRefLocked(bot, ref, updated)
	bot.InventoryRevision++
	bot.mu.Unlock()
	bot.mapArtSignal()
	return count, nil
}

func runBackpackAutoDropOnce(ctx context.Context, bot *BotSession) (int, error) {
	if bot == nil {
		return 0, errors.New("找不到 BOT")
	}
	bot.mu.Lock()
	if owner := bedrockCurrentControlOwnerLocked(bot); owner != "" {
		msg := bedrockControlBusyMessageLocked(bot, owner)
		bot.mu.Unlock()
		return 0, errors.New(msg)
	}
	rules := make(map[string]int, len(bot.AutoDropRules))
	for id, keep := range bot.AutoDropRules {
		rules[id] = keep
	}
	bot.mu.Unlock()
	if len(rules) == 0 {
		return 0, errors.New("目前沒有背包自動丟規則")
	}
	ids := make([]string, 0, len(rules))
	for id := range rules {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	total := 0
	for _, id := range ids {
		have := autoDropInventoryCount(bot, id)
		excess := have - rules[id]
		if excess <= 0 {
			continue
		}
		dropped, err := dropBedrockInventoryItem(ctx, bot, id, excess)
		total += dropped
		if err != nil {
			return total, err
		}
	}
	return total, nil
}

func collectRunAutoDropSafePoint(ctx context.Context, bot *BotSession) {
	if bot == nil {
		return
	}
	bot.mu.Lock()
	if !bot.AutoDropEnabled || len(bot.AutoDropRules) == 0 || !bot.Connected || !bot.PlayerReady || bot.Respawning.Load() {
		bot.mu.Unlock()
		return
	}
	bot.AutoDropSafePoint = true
	bot.AutoDropDirty = true
	bot.mu.Unlock()
	bot.triggerAutoDrop()

	// Do not leave the safe point merely because a fixed timer elapsed. The old
	// behaviour could let collect start moving/digging again while an accepted
	// inventory request was still in flight. Wait until the auto-drop worker has
	// completely drained this safe point. Individual stack requests already have
	// their own finite timeouts, so this cannot spin forever on a dead request.
	for {
		bot.mu.Lock()
		running := bot.AutoDropRunning
		dirty := bot.AutoDropDirty
		bot.mu.Unlock()
		if !running && !dirty {
			break
		}
		if ctx.Err() != nil {
			// Collection cancellation will release the collect owner immediately after
			// this function returns. Clear the safe-point grant so no new inventory
			// pass starts under the cancelled collect task.
			break
		}
		select {
		case <-ctx.Done():
		case <-time.After(40 * time.Millisecond):
		}
	}
	bot.mu.Lock()
	bot.AutoDropSafePoint = false
	bot.mu.Unlock()
}

func handleCollectChatCommand(bot *BotSession, message, replyTo string) bool {
	if bot == nil {
		return false
	}
	bot.mu.Lock()
	botName := bot.Name
	bot.mu.Unlock()
	cmd, matched, err := ParseCollectCommand(message, botName)
	if !matched {
		return false
	}
	if err != nil {
		bot.AddGameLog("[採集Bot] " + err.Error())
		sendCollectChatReply(bot, replyTo, err.Error())
		return true
	}
	switch cmd.Action {
	case "autodrop_on":
		bot.mu.Lock()
		bot.AutoDropEnabled = true
		if bot.AutoDropRules == nil {
			bot.AutoDropRules = map[string]int{}
		}
		bot.mu.Unlock()
		sendCollectChatReply(bot, replyTo, autoDropRulesSummary(bot))
		bot.triggerAutoDrop()
	case "autodrop_off":
		bot.mu.Lock()
		bot.AutoDropEnabled = false
		bot.AutoDropDirty = false
		bot.mu.Unlock()
		sendCollectChatReply(bot, replyTo, "自動丟已關閉")
	case "autodrop_status":
		sendCollectChatReply(bot, replyTo, autoDropRulesSummary(bot))
	case "autodrop_clear":
		bot.mu.Lock()
		bot.AutoDropRules = map[string]int{}
		bot.AutoDropDirty = false
		bot.mu.Unlock()
		sendCollectChatReply(bot, replyTo, "自動丟規則已清空")
	case "autodrop_add":
		itemID, _, known := bot.resolveRegisteredAutoDropItem(cmd.Target)
		if !known || itemID == "" {
			sendCollectChatReply(bot, replyTo, "只能新增 Bot 本次上線後從伺服器物品表讀到的物品："+cmd.Target)
			return true
		}
		bot.mu.Lock()
		if bot.AutoDropRules == nil {
			bot.AutoDropRules = map[string]int{}
		}
		bot.AutoDropRules[itemID] = cmd.Count
		enabled := bot.AutoDropEnabled
		bot.mu.Unlock()
		if cmd.Count > 0 {
			if enabled {
				sendCollectChatReply(bot, replyTo, fmt.Sprintf("已加入自動丟：%s，保留 %d 個", cmd.Target, cmd.Count))
			} else {
				sendCollectChatReply(bot, replyTo, fmt.Sprintf("已加入自動丟：%s，保留 %d 個（目前關閉）", cmd.Target, cmd.Count))
			}
		} else {
			if enabled {
				sendCollectChatReply(bot, replyTo, "已加入自動丟："+cmd.Target+"（全部丟）")
			} else {
				sendCollectChatReply(bot, replyTo, "已加入自動丟："+cmd.Target+"（全部丟；目前關閉）")
			}
		}
		if enabled {
			bot.triggerAutoDrop()
		}
	case "autodrop_remove":
		candidates := autoDropRuleLookupKeys(bot, cmd.Target)
		existed := false
		bot.mu.Lock()
		for _, key := range candidates {
			if _, ok := bot.AutoDropRules[key]; ok {
				delete(bot.AutoDropRules, key)
				existed = true
			}
		}
		bot.mu.Unlock()
		if existed {
			sendCollectChatReply(bot, replyTo, "已刪除自動丟規則："+cmd.Target)
		} else {
			sendCollectChatReply(bot, replyTo, "找不到自動丟規則："+cmd.Target)
		}
	case "drop":
		bot.mu.Lock()
		owner := bedrockCurrentControlOwnerLocked(bot)
		bot.mu.Unlock()
		if owner != "" {
			sendCollectChatReply(bot, replyTo, bedrockControlOwnerLabel(owner)+" 正在使用 BOT；丟棄不會搶走控制權")
			return true
		}
		targetLabel := cmd.Target
		if targetLabel == "*" {
			targetLabel = "全部物品"
		}
		amountLabel := "全部"
		if cmd.Count > 0 {
			amountLabel = strconv.Itoa(cmd.Count)
		}
		resolvedTarget := bot.resolveDropItemTarget(cmd.Target)
		if resolvedTarget != cmd.Target && resolvedTarget != "*" {
			sendCollectChatReply(bot, replyTo, fmt.Sprintf("開始丟棄：%s（%s，ID=%s）", targetLabel, amountLabel, resolvedTarget))
		} else {
			sendCollectChatReply(bot, replyTo, fmt.Sprintf("開始丟棄：%s（%s）", targetLabel, amountLabel))
		}
		go func(target string, count int, recipient, label string) {
			ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
			defer cancel()
			dropped, dropErr := dropBedrockInventoryItem(ctx, bot, target, count)
			if dropErr != nil {
				msg := fmt.Sprintf("丟棄失敗：%v", dropErr)
				if dropped > 0 {
					msg = fmt.Sprintf("已丟 %d 個，但後續失敗：%v", dropped, dropErr)
				}
				bot.AddGameLog("[採集Bot] " + msg)
				sendCollectChatReply(bot, recipient, msg)
				return
			}
			msg := fmt.Sprintf("丟棄完成：%s × %d", label, dropped)
			bot.AddGameLog("[採集Bot] " + msg)
			sendCollectChatReply(bot, recipient, msg)
		}(cmd.Target, cmd.Count, replyTo, targetLabel)
	case "storage":
		bot.mu.Lock()
		bot.CollectStoragePos = cmd.Storage
		bot.CollectStorageConfigured = true
		bot.mu.Unlock()
		bot.AddGameLog("[採集Bot] 存放箱已設定：" + cmd.Storage.String())
		sendCollectChatReply(bot, replyTo, "存放箱已設定："+cmd.Storage.String())
	case "start":
		logCollectDiagnostic(bot, "collect_command_start", fmt.Sprintf("target=%s count=%d vein=%v reply_to=%s", cmd.Target, cmd.Count, cmd.Vein, replyTo))
		bot.mu.Lock()
		previousReplyTo := bot.CollectReplyTo
		if strings.TrimSpace(replyTo) != "" {
			bot.CollectReplyTo = strings.TrimSpace(replyTo)
		}
		bot.mu.Unlock()
		if err := startBedrockCollect(bot, cmd.Target, cmd.Count, cmd.MaxDistance, cmd.Vein); err != nil {
			bot.mu.Lock()
			bot.CollectReplyTo = previousReplyTo
			bot.mu.Unlock()
			bot.AddGameLog("[採集Bot] 無法啟動：" + err.Error())
			sendCollectChatReply(bot, replyTo, "無法啟動："+err.Error())
			return true
		}
		mode := "一般"
		if cmd.Vein {
			mode = "礦脈"
		}
		bot.AddGameLog(fmt.Sprintf("[採集Bot] 開始：%s × %d（%s）", cmd.Target, cmd.Count, mode))
		sendCollectChatReply(bot, replyTo, fmt.Sprintf("開始：%s × %d（%s）", cmd.Target, cmd.Count, mode))
	case "stop":
		stopBedrockCollect(bot)
		sendCollectChatReply(bot, replyTo, "已停止")
	case "status":
		bot.mu.Lock()
		status := bot.CollectStatus
		done, total := bot.CollectCompleted, bot.CollectRequested
		errText := bot.CollectLastError
		bot.mu.Unlock()
		if errText != "" {
			bot.AddGameLog(fmt.Sprintf("[採集Bot] %s（%d/%d）：%s", status, done, total, errText))
			sendCollectChatReply(bot, replyTo, fmt.Sprintf("%s（%d/%d）：%s", status, done, total, errText))
		} else {
			bot.AddGameLog(fmt.Sprintf("[採集Bot] %s（%d/%d）", status, done, total))
			sendCollectChatReply(bot, replyTo, fmt.Sprintf("%s（%d/%d）", status, done, total))
		}
	}
	return true
}

// embeddedDashboardGzipBase64Merged 直接內嵌目前使用者提供的 dashboard.html。
// 這讓 App 介面不再依賴 EXE 旁邊的外部 dashboard.html。
const embeddedDashboardGzipBase64Merged = ``

func embeddedDashboardHTMLMerged() string {
	compressed, err := base64.StdEncoding.DecodeString(embeddedDashboardGzipBase64Merged)
	if err != nil {
		return `<!doctype html><html><head><meta charset="utf-8"><title>Minecraft Bot</title></head><body style="background:#10151d;color:#fff;font-family:sans-serif;padding:24px"><h2>介面資源解壓失敗</h2><p>內建 dashboard 解碼失敗。</p></body></html>`
	}
	zr, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return `<!doctype html><html><head><meta charset="utf-8"><title>Minecraft Bot</title></head><body style="background:#10151d;color:#fff;font-family:sans-serif;padding:24px"><h2>介面資源解壓失敗</h2><p>內建 dashboard 解壓失敗。</p></body></html>`
	}
	defer zr.Close()
	decoded, err := io.ReadAll(io.LimitReader(zr, 16<<20))
	if err != nil || len(decoded) == 0 {
		return `<!doctype html><html><head><meta charset="utf-8"><title>Minecraft Bot</title></head><body style="background:#10151d;color:#fff;font-family:sans-serif;padding:24px"><h2>介面資源解壓失敗</h2><p>內建 dashboard 讀取失敗。</p></body></html>`
	}
	return string(decoded)
}

