// patchDashboardAppV115 repairs integration gaps without replacing the large
// bundled dashboard. Storage fields are saved quietly after edits, a dedicated
// "facing container" action records the real block position, and one-shot buying
// uses the same verified state machine as repeat buying (repeat=false).
func patchDashboardAppV115(html string) string {
	if strings.TrimSpace(html) == "" {
		return html
	}
	// The dedicated setwant state machine supports nested/paged menus and result
	// confirmation. helper_once was an older parallel path that could lose forms.
	html = strings.Replace(html, "helperOnce(full);", "autoBuy(full,false);", 1)
	html = strings.Replace(html, "const deadline=Date.now()+75000;", "const deadline=Date.now()+165000;", 1)
	// V123 updater reliability: status polling is advisory only. A short WebView
	// binding/bridge interruption must never cancel a still-running go build.
	html = strings.Replace(html, "const deadline=startedAt+5*60*1000;", "const deadline=startedAt+8*60*1000;", 1)
	html = strings.Replace(html, "let statusErrors=0;", "let statusErrors=0,lastGoodStatusAt=Date.now();", 1)
	html = strings.Replace(html, "statusErrors=0;\n", "statusErrors=0;lastGoodStatusAt=Date.now();\n", 1)
	html = strings.Replace(html,
		"if(statusErrors>=20) throw new Error('更新狀態連線中斷超過約 10 秒；請查看 updater 紀錄');",
		"if(Date.now()-lastGoodStatusAt>120000){setInlineUpdateProgress(updateProgressValue,'更新狀態暫時無法讀取，但不會中止背景編譯；持續等待後端最終結果',false);}",
		1)
	// V125: Promise.race protects the update loop from a WebView2 binding that
	// never resolves. Without this, one hung status request freezes the displayed
	// percentage forever (commonly around 48~50%) even though go build is alive.
	html = strings.Replace(html,
		"const statusResponse=await fetch('/api/source/import/status',{cache:'no-store'});",
		"const statusResponse=await Promise.race([fetch('/api/source/import/status',{cache:'no-store'}),new Promise((_,reject)=>setTimeout(()=>reject(new Error('更新狀態請求逾時')),1500))]);",
		1)

	html = strings.Replace(html,
		`<button class="action" onclick="toolboxStorageCurrent()">讀取 BOT 目前位置</button>`,
		`<button class="action" onclick="toolboxStorageCurrent()">讀取 BOT 目前位置</button>
              <button class="action" onclick="toolboxStorageFacing()">讀取面前箱子</button>`, 1)
	html = strings.Replace(html,
		`掃描材料箱會搜尋範圍內所有高度的箱子、木桶與界伏盒，依最短 3D 路線逐箱讀取；成功後會以真正箱子座標更新設定並套用補料。`,
		`掃描材料箱只會自動搜尋 BOT 目前樓層附近的箱子、木桶與界伏盒；手動加入的指定箱子不受樓層限制。掃完會直接套用成建築 / 地圖畫補料來源。`, 1)
	const integrationScript = `<script id="dashboard-integration-v115">
(function(){
  const storageIds=['toolbox-storage-name','toolbox-storage-mode','toolbox-storage-scan-mode','toolbox-storage-server','toolbox-storage-warp','toolbox-storage-return','toolbox-storage-commands','toolbox-storage-offsets','toolbox-storage-range','toolbox-storage-x','toolbox-storage-y','toolbox-storage-z','toolbox-storage-drop-x','toolbox-storage-drop-y','toolbox-storage-drop-z'];
  let storageSaveTimer=0,storageSaveRunning=false,storageSaveDirty=false;
  function storageStatus(message,isError){
    let el=document.getElementById('toolbox-storage-autosave-status');
    if(!el){
      const anchor=document.querySelector('#toolbox-storage-name');
      const actions=anchor&&anchor.closest('.suite-card')?.querySelector('.suite-actions');
      if(!actions)return;
      el=document.createElement('small');el.id='toolbox-storage-autosave-status';el.className='suite-note';actions.appendChild(el);
    }
    el.textContent=message||'';el.style.color=isError?'#fca5a5':'#86efac';
  }
  async function storageSaveNow(){
    if(storageSaveRunning){storageSaveDirty=true;return;}
    const nameEl=document.getElementById('toolbox-storage-name');
    if(!nameEl||typeof toolboxJSON!=='function'||typeof toolboxStorageParams!=='function')return;
    const xyz=['toolbox-storage-x','toolbox-storage-y','toolbox-storage-z'].map(id=>document.getElementById(id)?.value);
    if(xyz.some(v=>String(v??'').trim()===''||!Number.isFinite(Number(v))))return;
    storageSaveRunning=true;storageSaveDirty=false;storageStatus('正在自動儲存…',false);
    try{
      const out=await toolboxJSON('/api/suite/storage',Object.assign({action:'save',profile_id:String(nameEl.dataset.editId||'')},toolboxStorageParams(true)));
      const id=String(out?.profile?.id||nameEl.dataset.editId||'');if(id)nameEl.dataset.editId=id;
      storageStatus('已自動儲存 '+new Date().toLocaleTimeString(),false);
    }catch(e){storageStatus('自動儲存失敗：'+String(e?.message||e),true);}
    finally{storageSaveRunning=false;if(storageSaveDirty)scheduleStorageSave();}
  }
  function scheduleStorageSave(){clearTimeout(storageSaveTimer);storageSaveTimer=setTimeout(storageSaveNow,800);}
  window.toolboxStorageFacing=async function(){
    if(!sid)return;
    try{
      const range=Math.max(2,Math.min(96,Number(document.getElementById('toolbox-storage-range')?.value)||8));
      const out=await toolboxJSON('/api/suite/storage',{action:'scan_facing',range:String(range)});
      const p=out?.container?.position;if(!p)throw new Error('伺服器沒有回傳箱子座標');
      suiteSetValue('toolbox-storage-x',Number(p.x));suiteSetValue('toolbox-storage-y',Number(p.y));suiteSetValue('toolbox-storage-z',Number(p.z));
      storageStatus('已讀取面前箱子 '+Number(p.x)+','+Number(p.y)+','+Number(p.z)+'；準備自動儲存',false);
      scheduleStorageSave();
    }catch(e){storageStatus('讀取面前箱子失敗：'+String(e?.message||e),true);if(typeof showToast==='function')showToast('讀取面前箱子失敗：'+String(e?.message||e),true);}
  };
  function init(){
    storageIds.forEach(id=>{const el=document.getElementById(id);if(!el||el.dataset.autosaveV115==='1')return;el.dataset.autosaveV115='1';el.addEventListener('input',scheduleStorageSave);el.addEventListener('change',scheduleStorageSave);});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
  setTimeout(init,250);
})();
</script>`
	if !strings.Contains(html, `id="dashboard-integration-v115"`) {
		html = strings.Replace(html, "</body>", integrationScript+"\n</body>", 1)
	}
	return html
}

var dashboardHTML = patchDashboardAppV115(patchDashboardInventoryV112(embeddedDashboardHTMLMerged()))
